    public function notifications(): never
    {
        $rows=$this->db->all("SELECT TOP 200 id,template,subject,payload,read_at,CONVERT(varchar(16),created_at,120) created_at FROM notifications WHERE recipient_id=:u AND channel='in_app' ORDER BY created_at DESC",['u'=>$this->userId()]);
        $items='';foreach($rows as$row){$payload=json_decode((string)$row['payload'],true)?:[];$url=is_string($payload['url']??null)&&str_starts_with($payload['url'],'/')&&!str_starts_with($payload['url'],'//')?$payload['url']:(isset($payload['project_id'])?'/projects/'.(int)$payload['project_id']:(isset($payload['case_id'])?'/cases/'.(int)$payload['case_id']:(isset($payload['risk_id'])?'/risks/'.(int)$payload['risk_id'].'/edit':null)));
            $items.='<li class="notification'.($row['read_at']===null?' is-unread':'').'"><div><strong>'.($url?'<a href="'.View::e($url).'">'.View::e($row['subject']).'</a>':View::e($row['subject'])).'</strong><p>'.View::e((string)($payload['body']??'')).'</p><small class="muted">'.View::e($row['created_at']).'</small></div>'.($row['read_at']===null?'<form method="post" action="/notifications/read">'.$this->view->csrf().'<input type="hidden" name="id" value="'.View::e($row['id']).'"><button class="button button-secondary button-small">Означи како прочитано</button></form>':'').'</li>';}
        $body='<section class="card"><div class="card-header"><h2>Мои известувања</h2>'.($rows?'<form method="post" action="/notifications/read">'.$this->view->csrf().'<button class="button button-secondary">Означи ги сите како прочитани</button></form>':'').'</div>'.($items?'<ul class="notification-list">'.$items.'</ul>':'<p class="empty-state">Немате известувања.</p>').'</section>';
        $this->view->render('Известувања',$body);
    }

