    }

    public function dashboard(): never
    {
        [$where,$params] = $this->scope->budgetLineSql($this->userId(), 'bl', 'report', 'dashboardBudget');
        $budgetAmount=$this->db->scalar("SELECT COALESCE(SUM(bl.total_amount),0) FROM budget_lines bl JOIN budget_versions bv ON bv.id=bl.budget_version_id WHERE bv.is_official=1 AND bl.budget_category IS NOT NULL AND {$where}",$params);
        // Allocations and commitments default to the imported FreeBalance report; lines with e-Kabineti project data use those.
        $figures=$this->db->one("SELECT COALESCE(SUM(lf.allocated),0) allocated,COALESCE(SUM(lf.committed),0) committed,COALESCE(SUM(lf.spent),0) spent,COALESCE(SUM(lf.reserved),0) reserved FROM (SELECT ".BudgetExecution::LINE_FIGURES_SELECT." FROM budget_lines bl JOIN budget_versions bv ON bv.id=bl.budget_version_id".BudgetExecution::LINE_FIGURES_APPLY." WHERE bv.is_official=1 AND {$where}) lf",$params)?:[];
        $allocatedAmount=$figures['allocated']??0;$committedAmount=$figures['committed']??0;$spentAmount=$figures['spent']??0;$reservedAmount=$figures['reserved']??0;
        $totals=['current_amount'=>$budgetAmount,'allocated'=>$allocatedAmount,'committed'=>$committedAmount,'spent'=>$spentAmount,'reserved'=>$reservedAmount];
        [$pWhere,$pParams] = $this->scope->sql($this->userId(), 'p.directorate_id', 'p');
        $projects = $this->db->all("SELECT TOP 7 p.id,p.code,p.name,p.progress,p.status,d.name directorate FROM projects p JOIN directorates d ON d.id=p.directorate_id WHERE {$pWhere} ORDER BY p.updated_at DESC", $pParams);
        $updates = $this->db->all("SELECT TOP 10 pu.id,pu.project_id,p.code project_code,p.name project_name,d.code directorate,pu.progress,pu.narrative,pu.blockers,pu.next_step,u.name author,CONVERT(varchar(10),pu.period,23) period,CONVERT(varchar(33),pu.created_at,127) created_at FROM progress_updates pu JOIN projects p ON p.id=pu.project_id JOIN directorates d ON d.id=p.directorate_id JOIN users u ON u.id=pu.created_by WHERE {$pWhere} ORDER BY pu.id DESC", $pParams);
        [$riskWhere,$riskParams]=$this->scope->sql($this->userId(),'r.directorate_id','dashboardrisk');
        $risks=$this->db->all("SELECT TOP 10 r.id,d.code directorate_code,d.name directorate,r.project_id,p.code project_code,p.name project_name,p.status project_status,r.category,r.description,r.probability,r.impact,r.inherent_score,r.residual_probability,r.residual_impact,r.residual_score,r.status,(SELECT COUNT(*) FROM risk_actions ra WHERE ra.risk_id=r.id) measure_count,(SELECT COUNT(*) FROM risk_actions ra WHERE ra.risk_id=r.id AND ra.status='completed') completed_measure_count FROM risks r JOIN directorates d ON d.id=r.directorate_id LEFT JOIN projects p ON p.id=r.project_id WHERE {$riskWhere} AND r.status NOT IN ('closed','mitigated') ORDER BY COALESCE(r.residual_score,r.inherent_score) DESC,r.id DESC",$riskParams);
        $current=(float)($totals['current_amount']??0); $committed=(float)($totals['committed']??0); $reserved=(float)($totals['reserved']??0);
        $allocated=(float)($totals['allocated']??0);
        // Same definitions as the Budget page: free = allocated − reserved − committed.
        $cards = [['Тековен план',$current],['Распределено',$allocated],['Преземено',$committed],['Потрошено',(float)($totals['spent']??0)],['Слободни (распределено − преземено)',$allocated-$committed-$reserved]];
        $body='';
        $preferences=(new UserPreferences($this->db))->get($this->userId());$widgets=$preferences['dashboard_widgets'];
        if(in_array('agenda',$widgets,true)&&array_intersect(['mayor','mayor_admin','system_admin'],$this->scope->roles($this->userId()))){
            $agenda=$this->mayorAgendaRows();
            $body.='<section class="card mayor-agenda"><h2>Агенда за дискусија и внимание на Градоначалникот</h2><p class="muted">Активните проекти, ризици и теми избрани од секторите.</p>'.$this->mayorAgendaTable($this->pageOf($agenda,'agenda'),false).$this->pager('agenda').'</section>';
        }
        $body.='<p class="page-actions"><a class="button" href="/dashboard.xlsx">Извези го панелот во Excel</a> <a class="button button-secondary" href="/help/dashboard">Прирачник и помош</a></p>';
        if(in_array('metrics',$widgets,true)){ $body.='<div class="metrics">'; foreach($cards as [$label,$value]) $body.='<div class="metric"><span>'.View::e($label).'</span><strong>'.View::money($value).'</strong></div>'; $body.='</div>'; }
        $dashboardGrid='';if(in_array('projects',$widgets,true))$dashboardGrid.='<section class="card"><h2>Последни проекти</h2>'.$this->projectsTable($this->pageOf($projects,'recent')).$this->pager('recent').'</section>';if(in_array('updates',$widgets,true))$dashboardGrid.='<section class="card"><h2>Известувања во реално време</h2><div id="live-reports" data-after="'.(int)($updates[0]['id']??0).'">'.$this->updatesHtml($updates).'</div></section>';if($dashboardGrid!=='')$body.='<div class="grid">'.$dashboardGrid.'</div>';if(in_array('risks',$widgets,true))$body.='<section class="card risk-dashboard"><h2>Приоритетни ризици</h2><p class="muted">Активните ризици се подредени според резидуалниот резултат, по спроведувањето на завршените мерки.</p>'.$this->risksTable($risks,false).'</section>';
        $script='<script src="/assets/live.js" defer></script>';
        $this->view->render('Раководен панел', $body, ['script'=>$script]);
    }

    public function mayorDashboard(): never
    {
        $sheets=MayorGoogleSheetsConfig::fromApplication($this->config);
        $spreadsheetId=trim((string)($sheets['spreadsheet_id']??''));
        $dashboardGid=(string)($sheets['dashboard_gid']??'0');
        if(!preg_match('/^[A-Za-z0-9_-]{20,}$/',$spreadsheetId)||!preg_match('/^\d+$/',$dashboardGid)){
            $body='<section class="card"><h2>Неделен панел</h2><div class="alert error" role="alert">Google Sheets панелот сѐ уште не е конфигуриран во оваа средина.</div><p class="muted">Конфигурирајте ги GOOGLE_SHEETS_SPREADSHEET_ID и GOOGLE_SHEETS_DASHBOARD_GID во приватната конфигурација на серверот.</p></section>';
            $this->view->render('Панел на Градоначалникот',$body);
        }

        $encodedId=rawurlencode($spreadsheetId);$encodedGid=rawurlencode($dashboardGid);
        $openUrl='https://docs.google.com/spreadsheets/d/'.$encodedId.'/edit#gid='.$encodedGid;
        $previewUrl='https://docs.google.com/spreadsheets/d/'.$encodedId.'/preview?gid='.$encodedGid.'&rm=minimal';
        $body='<section class="card mayor-dashboard-card"><div class="mayor-dashboard-actions"><div><h2>Неделен панел на Градоначалникот</h2><p class="muted">Извршниот приказ се освежува од податоците на е-Кабинет. Пристапот до Google датотеката се контролира одделно преку дозволите на Google Drive.</p></div><a class="button" href="'.View::e($openUrl).'" target="_blank" rel="noopener noreferrer">Отвори во Google Sheets</a></div><div class="mayor-dashboard-frame"><iframe src="'.View::e($previewUrl).'" title="Неделен панел на Градоначалникот" loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe></div></section>';
        $this->view->render('Панел на Градоначалникот',$body);
    }

    public function citizenServices(): never
    {
        if (!$this->scope->canAccessCitizenServices($this->userId())) throw new HttpException(403, 'Немате дозвола за известување за услугите за граѓаните.');

        $timezone = new \DateTimeZone(date_default_timezone_get());
        $today = new \DateTimeImmutable('today', $timezone);
        $defaultWeek = $today->modify('monday this week')->format('Y-m-d');
        $week = trim((string) $this->request->input('week_start', $defaultWeek));
        $weekDate = \DateTimeImmutable::createFromFormat('!Y-m-d', $week, $timezone);
        if (!$weekDate || $weekDate->format('Y-m-d') !== $week || $weekDate->format('N') !== '1') throw new HttpException(422, 'Неделата мора да почнува во понеделник.');

        $reportOnly = $this->scope->canViewCitizenServicesReportOnly($this->userId());
        $manager = $this->scope->canManageCitizenServices($this->userId());
        [$where, $params] = $reportOnly
            ? ['1=1', []]
            : $this->scope->sql($this->userId(), 's.directorate_id', 'citizen_service_scope');
        $params['report_week'] = $week;
        $rows = $this->db->all(
            "SELECT s.id service_id,s.code service_code,s.name service_name,s.description,s.sla_target_hours,s.active,s.sort_order,s.window_type,
                    d.id directorate_id,d.code directorate_code,d.name directorate_name,
                    m.id metric_id,m.metric_key,m.label metric_label,m.metric_role,m.sort_order metric_sort_order,
                    r.id report_id,r.average_resolution_hours,r.notes,CONVERT(varchar(19),r.submitted_at,120) submitted_at,u.name submitted_by,
                    v.metric_value,v.amount_value
             FROM citizen_services s
             JOIN directorates d ON d.id=s.directorate_id
             JOIN citizen_service_metrics m ON m.service_id=s.id AND m.active=1
             LEFT JOIN citizen_service_weekly_reports r ON r.service_id=s.id AND r.week_start=:report_week
             LEFT JOIN citizen_service_weekly_values v ON v.report_id=r.id AND v.metric_id=m.id
             LEFT JOIN users u ON u.id=r.submitted_by
             WHERE {$where}".($manager ? '' : ' AND s.active=1')."
             ORDER BY d.name,s.sort_order,s.name,m.sort_order,m.id",
            $params
        );

        $services = [];
        foreach ($rows as $row) {
            $id = (int) $row['service_id'];
            if (!isset($services[$id])) {
                $services[$id] = [
                    'id'=>$id,'code'=>$row['service_code'],'name'=>$row['service_name'],'description'=>$row['description'],
                    'sla'=>$row['sla_target_hours'],'active'=>(bool) $row['active'],'directorate_id'=>(int) $row['directorate_id'],
                    'directorate_code'=>$row['directorate_code'],'directorate_name'=>$row['directorate_name'],
                    'report_id'=>$row['report_id'],'average_resolution_hours'=>$row['average_resolution_hours'],'notes'=>$row['notes'],
                    'submitted_at'=>$row['submitted_at'],'submitted_by'=>$row['submitted_by'],'window_type'=>(string) ($row['window_type'] ?? 'request'),'metrics'=>[],
                ];
            }
            $services[$id]['metrics'][] = [
                'id'=>(int) $row['metric_id'],'key'=>$row['metric_key'],'label'=>$row['metric_label'],
                'role'=>$row['metric_role'],'value'=>$row['metric_role'] === 'amount' ? $row['amount_value'] : $row['metric_value'],
            ];
        }

        $directorates = $manager ? $this->db->all('SELECT id,code,name FROM directorates WHERE active=1 ORDER BY name') : [];
        // Totals per directorate for the week: requests and complaints, forwarded cases (subtracted from the open ones),
        // services delivered and approved subsidies (dbo.vw_citizen_service_directorate_weeks).
        $summary = [];
        foreach ($services as $service) {
            $summary[(int) $service['directorate_id']] ??= ['code'=>$service['directorate_code'],'name'=>$service['directorate_name'],'windows'=>0];
            ++$summary[(int) $service['directorate_id']]['windows'];
        }
        [$weekWhere, $weekParams] = $reportOnly ? ['1=1', []] : $this->scope->sql($this->userId(), 'w.directorate_id', 'citizen_week_scope');
        $weekTotals = [];
        foreach ($this->db->all("SELECT w.* FROM vw_citizen_service_directorate_weeks w WHERE w.week_start=:summary_week AND {$weekWhere}", $weekParams + ['summary_week'=>$week]) as $row) {
            $weekTotals[(int) $row['directorate_id']] = $row;
            $summary[(int) $row['directorate_id']] ??= ['code'=>$row['directorate_code'],'name'=>$row['directorate_name'],'windows'=>0];
        }
        $summaryRows = '';
        foreach ($this->pageOf(array_map(static fn(int $id, array $row): array => $row + ['directorate_id'=>$id], array_keys($summary), $summary), 'summary') as $row) {
            $t = $weekTotals[$row['directorate_id']] ?? [];
            $summaryRows .= '<tr><td><strong>'.View::e($row['code']).'</strong><br><small>'.View::e($row['name']).'</small></td><td>'.(int) ($t['reported_windows'] ?? 0).' / '.(int) $row['windows'].'</td><td>'.(int) ($t['received_count'] ?? 0).'</td><td>'.(int) ($t['resolved_count'] ?? 0).'</td><td>'.(int) ($t['reported_open_count'] ?? 0).'</td><td>'.(int) ($t['forwarded_count'] ?? 0).'</td><td><strong>'.(int) ($t['open_after_forwarding'] ?? 0).'</strong></td><td>'.(int) ($t['volume_count'] ?? 0).'</td><td>'.View::money($t['approved_subsidy_amount'] ?? 0).'</td></tr>';
        }
        $intro = $reportOnly
            ? 'Приказ само за читање. Извештајот ги обединува сите сектори; промените ги прават корисниците од соодветните сектори.'
            : 'Евидентирајте ги само проверените збирови за услугите на вашиот сектор. Панелот на Градоначалникот и Google Sheets ја користат последната пријавена недела.';
        $body = '<section class="card citizen-service-intro"><div><h2>'.($reportOnly ? 'Неделен извештај за услугите' : 'Неделно известување за услугите').'</h2><p class="muted">'.View::e($intro).'</p></div><form method="get" action="/citizen-services"><label>Недела што почнува во понеделник<input type="date" name="week_start" value="'.View::e($week).'" required></label><button class="button" type="submit">Отвори ја неделата</button></form></section>';
        $body .= '<div class="page-actions"><a class="button" href="/citizen-services/by-service?week_start='.View::e($week).'">Известување по услуги</a><a class="button button-secondary" href="/citizen-services/by-service/report?week_start='.View::e($week).'">Извештај по услуги</a><a class="button button-secondary" href="/citizen-services/catalog">Каталог на услуги</a></div>';
        $body .= '<section class="card"><h2>Вкупно по сектор</h2><p class="muted">Барања, субвенции и жалби. Предметите препратени со пропратен акт (од Управни предмети) се одземаат од оние во постапка; посетите и дадените услуги се бројат одделно.</p><div class="table-wrap"><table><thead><tr><th>Сектор</th><th>Пријавени шалтери</th><th>Примени</th><th>Решени</th><th>Во постапка (пријавено)</th><th>Препратени</th><th>Во постапка по препраќањето</th><th>Дадени услуги</th><th>Одобрени субвенции</th></tr></thead><tbody>'.($summaryRows ?: '<tr><td colspan="9">Нема услуги во вашиот опсег.</td></tr>').'</tbody></table></div>'.$this->pager('summary').'</section>';

        // Cases forwarded with a cover letter this week (from Administrative cases), per forwarding and receiving directorate.
        [$forwardWhere, $forwardParams] = $reportOnly ? ['1=1', []] : $this->scope->sql($this->userId(), 'f.from_directorate_id', 'citizen_forward_scope');
        $forwardings = $this->db->all("SELECT fd.code from_code,fd.name from_name,td.code to_code,td.name to_name,COUNT(*) cases,SUM(CASE WHEN f.status='received' THEN 1 ELSE 0 END) received FROM case_forwardings f JOIN directorates fd ON fd.id=f.from_directorate_id JOIN directorates td ON td.id=f.to_directorate_id WHERE f.forwarded_on>=:forward_from AND f.forwarded_on<DATEADD(day,7,:forward_to) AND {$forwardWhere} GROUP BY fd.code,fd.name,td.code,td.name ORDER BY fd.name,td.name", $forwardParams + ['forward_from'=>$week, 'forward_to'=>$week]);
        $forwardRows = '';
        foreach ($this->pageOf($forwardings, 'forwarded') as $row) $forwardRows .= '<tr><td><strong>'.View::e($row['from_code']).'</strong><br><small>'.View::e($row['from_name']).'</small></td><td><strong>'.View::e($row['to_code']).'</strong><br><small>'.View::e($row['to_name']).'</small></td><td>'.(int) $row['cases'].'</td><td>'.(int) $row['received'].'</td></tr>';
        $body .= '<section class="card"><h2>Предмети препратени со пропратен акт</h2><p class="muted">Се бројат автоматски од Управни предмети за избраната недела; не се пополнуваат рачно.</p><div class="table-wrap"><table><thead><tr><th>Сектор што препратил</th><th>Сектор што примил</th><th>Предмети</th><th>Примени</th></tr></thead><tbody>'.($forwardRows ?: '<tr><td colspan="4">Нема препратени предмети оваа недела.</td></tr>').'</tbody></table></div>'.$this->pager('forwarded').'</section>';

        // Each directorate's windows, grouped by type: requests, subsidies, complaints, services delivered.
        $computedWindows = array_flip((new \EKabineti\Service\CitizenServiceCatalog($this->db))->computedWindowIds());
        $typeLabels = ['request'=>'Барање','subsidy'=>'Субвенции','complaint'=>'Жалби','volume'=>'Посети и дадени услуги'];
        $typeRank = array_flip(array_keys($typeLabels));
        $order = array_flip(array_keys($services)); $directorateRank = [];
        foreach ($services as $service) $directorateRank[$service['directorate_id']] ??= count($directorateRank);
        $sortKey = static fn(array $service): array => [$directorateRank[$service['directorate_id']], $typeRank[$service['window_type']] ?? 9, $order[$service['id']]];
        uasort($services, static fn(array $a, array $b): int => $sortKey($a) <=> $sortKey($b));
        $currentDirectorate = null; $currentType = null;
        foreach ($services as $service) {
            if ($currentDirectorate !== $service['directorate_id']) {
                if ($currentDirectorate !== null) $body .= '</div></section>';
                $currentDirectorate = $service['directorate_id']; $currentType = null;
                $body .= '<section class="card citizen-directorate"><h2>'.View::e($service['directorate_code']).' · '.View::e($service['directorate_name']).'</h2>';
            }
            if ($currentType !== $service['window_type']) {
                if ($currentType !== null) $body .= '</div>';
                $currentType = $service['window_type'];
                $body .= '<h3 class="citizen-window-type">'.View::e($typeLabels[$currentType] ?? $currentType).'</h3><div class="citizen-service-grid">';
            }
            $volume = $service['window_type'] === 'volume';
            $isComputed = isset($computedWindows[(int) $service['id']]);
            $canReport = $service['active'] && !$isComputed && $this->scope->canReportCitizenServices($this->userId(), (int) $service['directorate_id']);
            $status = $service['active'] ? '<span class="status-badge status-active">Активно</span>' : '<span class="status-badge status-cancelled">Неактивно</span>';
            $body .= '<article class="citizen-service-card"><header><div><h3>'.View::e($service['name']).'</h3><small>'.View::e($service['code']).'</small></div>'.$status.'</header><p>'.View::e($service['description']).'</p><p class="muted">'.($volume || $service['sla'] === null ? 'Неделни бројки' : 'Ориентационен SLA: '.View::e($service['sla']).' часа').($service['submitted_at'] ? ' · Пријавено од '.View::e($service['submitted_by']).' во '.View::e($service['submitted_at']) : ' · Сѐ уште без извештај').'</p>';
            if ($canReport) {
                $body .= '<form method="post" action="/citizen-services/'.(int)$service['id'].'/weekly-reports">'.$this->view->csrf().'<input type="hidden" name="week_start" value="'.View::e($week).'"><div class="citizen-metric-grid">';
                foreach ($service['metrics'] as $metric) $body .= $metric['role'] === 'amount'
                    ? '<label>'.View::e($metric['label']).'<input type="number" name="metric_'.(int)$metric['id'].'" min="0" max="999999999999.99" step="0.01" inputmode="decimal" value="'.View::e($metric['value'] ?? '0.00').'" required></label>'
                    : '<label>'.View::e($metric['label']).'<input type="number" name="metric_'.(int)$metric['id'].'" min="0" max="1000000000" step="1" value="'.View::e($metric['value'] ?? 0).'" required></label>';
                $body .= '</div>'.($volume ? '' : '<label>Просечно време на решавање (часови)<input type="number" name="average_resolution_hours" min="0" max="1000000" step="0.01" value="'.View::e($service['average_resolution_hours']).'"></label>').'<label>Белешки<textarea name="notes" maxlength="4000" rows="2">'.View::e($service['notes']).'</textarea></label><button class="primary" type="submit">Зачувај го неделниот извештај</button></form>';
            } elseif ($reportOnly || $isComputed) {
                if ($isComputed) $body .= '<p class="muted">Се пресметува од извештаите на одделенијата по услуги. <a href="/citizen-services/by-service?week_start='.View::e($week).'">Известување по услуги</a></p>';
                $body .= '<dl class="citizen-service-report">';
                foreach ($service['metrics'] as $metric) $body .= '<div><dt>'.View::e($metric['label']).'</dt><dd>'.($metric['value'] === null ? '—' : ($metric['role'] === 'amount' ? View::money($metric['value']) : View::e($metric['value']))).'</dd></div>';
                $body .= ($volume ? '' : '<div><dt>Просечно време на решавање</dt><dd>'.($service['average_resolution_hours'] === null ? '—' : View::e($service['average_resolution_hours']).' часа').'</dd></div>').'</dl>';
                if ($service['notes']) $body .= '<p><strong>Белешки:</strong> '.View::e($service['notes']).'</p>';
            }
            if ($manager) {
                $targetOptions = '<option value="">Изберете сектор</option>';
                foreach ($directorates as $directorate) if ((int)$directorate['id'] !== (int)$service['directorate_id']) $targetOptions .= '<option value="'.(int)$directorate['id'].'">'.View::e($directorate['code']).' · '.View::e($directorate['name']).'</option>';
                $body .= '<details class="citizen-service-admin"><summary>Администрирање на услугата</summary><form method="post" action="/citizen-services/'.(int)$service['id'].'/status">'.$this->view->csrf().'<input type="hidden" name="active" value="'.($service['active'] ? '0' : '1').'"><label>Причина<input name="reason" maxlength="1000" required></label><button class="button button-secondary" type="submit">'.($service['active'] ? 'Деактивирај' : 'Активирај').'</button></form><form method="post" action="/citizen-services/'.(int)$service['id'].'/transfer">'.$this->view->csrf().'<label>Префрли во<select name="to_directorate_id" required>'.$targetOptions.'</select></label><label>Причина<input name="reason" maxlength="1000" required></label><button class="button button-secondary" type="submit">Префрли ја услугата</button></form></details>';
            }
            $body .= '</article>';
        }
        if ($currentDirectorate !== null) $body .= '</div></section>';
        $this->view->render('Услуги за граѓаните', $body);
    }

    public function dashboardExport(): never
    {
        $locale=Translator::locale($this->auth->user());
        [$pWhere,$pParams]=$this->scope->sql($this->userId(),'p.directorate_id','dxp');
        [$bWhere,$bParams]=$this->scope->budgetLineSql($this->userId(),'bl','report','dxb');$bWhere.=' AND bl.budget_category IS NOT NULL';
        [$rWhere,$rParams]=$this->scope->sql($this->userId(),'r.directorate_id','dxr');
        $projects=$this->db->all("SELECT p.id,p.code,p.name,d.code directorate_code,d.name directorate,p.status,p.progress,CONVERT(varchar(10),p.starts_at,23) starts_at,CONVERT(varchar(10),p.ends_at,23) ends_at,p.objective FROM projects p JOIN directorates d ON d.id=p.directorate_id WHERE {$pWhere} ORDER BY d.name,p.code",$pParams);
        $tasks=$this->db->all("SELECT t.id,p.code project_code,p.name project,t.title,u.name owner,CONVERT(varchar(10),t.starts_at,23) starts_at,CONVERT(varchar(10),t.due_at,23) due_at,t.status,t.progress,t.weight_percent,t.next_step FROM project_tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN users u ON u.id=t.owner_id WHERE {$pWhere} ORDER BY t.due_at,t.id",$pParams);
        $budget=$this->db->all("SELECT bc.base_year fiscal_year,d.code directorate_code,d.name directorate,bl.code project_code,bl.name,bl.budget_category,bl.own_revenue,bl.government_grant,bl.health_grant,bl.education_grant,bl.loan_financing,bl.carryover_revenue,bl.source_section_code,bl.total_amount,bl.imported_available_amount,CONVERT(varchar(10),bl.imported_available_as_of,23) imported_available_as_of,".BudgetExecution::LINE_FIGURES_SELECT." FROM budget_lines bl JOIN budget_versions bv ON bv.id=bl.budget_version_id JOIN budget_cycles bc ON bc.id=bv.budget_cycle_id JOIN directorates d ON d.id=bl.directorate_id".BudgetExecution::LINE_FIGURES_APPLY." WHERE bv.is_official=1 AND {$bWhere} ORDER BY bc.base_year DESC,d.name,bl.code",$bParams);
        $risks=$this->db->all("SELECT r.id,d.code directorate_code,d.name directorate,p.code project_code,p.name project,r.category,r.description,r.probability,r.impact,r.inherent_score,r.residual_probability,r.residual_impact,r.residual_score,r.status,CONVERT(varchar(10),r.review_at,23) review_at FROM risks r JOIN directorates d ON d.id=r.directorate_id LEFT JOIN projects p ON p.id=r.project_id WHERE {$rWhere} ORDER BY COALESCE(r.residual_score,r.inherent_score) DESC,r.id DESC",$rParams);
        $updates=$this->db->all("SELECT pu.id,d.code directorate_code,p.code project_code,p.name project,CONVERT(varchar(10),pu.period,23) period,pu.progress,pu.narrative,pu.blockers,pu.next_step,u.name author FROM progress_updates pu JOIN projects p ON p.id=pu.project_id JOIN directorates d ON d.id=p.directorate_id JOIN users u ON u.id=pu.created_by WHERE {$pWhere} ORDER BY pu.id DESC",$pParams);
        $metrics=$locale==='en'?[
            ['metric'=>'Projects','value'=>count($projects)],['metric'=>'Open risks','value'=>count(array_filter($risks,static fn($r)=>!in_array($r['status'],['closed','mitigated'],true)))],['metric'=>'Approved budget','value'=>array_sum(array_column($budget,'total_amount'))],['metric'=>'Allocated','value'=>array_sum(array_column($budget,'allocated'))],['metric'=>'Committed','value'=>array_sum(array_column($budget,'committed'))],['metric'=>'Spent','value'=>array_sum(array_column($budget,'spent'))],['metric'=>'Generated at','value'=>gmdate('c')],
        ]:[
            ['metric'=>'Проекти','value'=>count($projects)],['metric'=>'Отворени ризици','value'=>count(array_filter($risks,static fn($r)=>!in_array($r['status'],['closed','mitigated'],true)))],['metric'=>'Одобрен буџет','value'=>array_sum(array_column($budget,'total_amount'))],['metric'=>'Распределено','value'=>array_sum(array_column($budget,'allocated'))],['metric'=>'Преземено','value'=>array_sum(array_column($budget,'committed'))],['metric'=>'Потрошено','value'=>array_sum(array_column($budget,'spent'))],['metric'=>'Генерирано на','value'=>gmdate('c')],
        ];
        $guide=$locale==='en'?[
            ['section'=>'Панел','purpose'=>'Live executive indicators and totals'],['section'=>'Projects','purpose'=>'Scoped project portfolio'],
            ['section'=>'Services','purpose'=>'Dated project tasks and next steps'],['section'=>'Budget','purpose'=>'Approved budget, sources and calculated execution'],
            ['section'=>'Issues','purpose'=>'Risk register and critical items'],['section'=>'Directorate sheets','purpose'=>'Projects and risks grouped by directorate'],
            ['section'=>'Reports','purpose'=>'Immutable progress updates in real time'],['section'=>'Filters','purpose'=>'Each worksheet contains an Excel AutoFilter and a frozen header row'],
        ]:[
            ['section'=>'Панел','purpose'=>'Показатели и извршни збирови во живо'],['section'=>'Проекти','purpose'=>'Портфолио на проекти според опсегот'],['section'=>'Услуги','purpose'=>'Задачи со датум и следни чекори'],['section'=>'Буџет','purpose'=>'Одобрен буџет, извори и пресметано извршување'],['section'=>'Прашања','purpose'=>'Регистар на ризици и критични прашања'],['section'=>'Листови на секторите','purpose'=>'Проекти и ризици по сектор'],['section'=>'Извештаи','purpose'=>'Непроменливи извештаи за напредок во реално време'],['section'=>'Филтри','purpose'=>'Секој лист има Excel AutoFilter и замрзнато заглавие'],
        ];
        $sheets=[
            ['name'=>$locale==='en'?'Guide':'Водич','headers'=>['section'=>$locale==='en'?'Section':'Дел','purpose'=>$locale==='en'?'Purpose':'Цел'],'rows'=>$guide],
            ['name'=>$locale==='en'?'Dashboard':'Панел','headers'=>['metric'=>$locale==='en'?'Indicator':'Показател','value'=>$locale==='en'?'Value':'Вредност'],'rows'=>$metrics],
            ['name'=>$locale==='en'?'Projects':'Проекти','headers'=>$this->localizedHeaders(array_keys($projects[0]??['id'=>null]),$locale),'rows'=>$projects],
            ['name'=>$locale==='en'?'Services':'Услуги','headers'=>$this->localizedHeaders(array_keys($tasks[0]??['id'=>null]),$locale),'rows'=>$tasks],
            ['name'=>$locale==='en'?'Budget':'Буџет','headers'=>$this->localizedHeaders(array_keys($budget[0]??['fiscal_year'=>null]),$locale),'rows'=>$budget],
            ['name'=>$locale==='en'?'Issues and risks':'Прашања и ризици','headers'=>$this->localizedHeaders(array_keys($risks[0]??['id'=>null]),$locale),'rows'=>$risks],
        ];
        if(array_intersect(['mayor','mayor_admin','system_admin'],$this->scope->roles($this->userId()))){$agendaRows=[];foreach($this->mayorAgendaRows()as$row){$agendaRows[]=['priority'=>$row['priority'],'item_type'=>$row['item_type'],'directorate_code'=>$row['directorate_code'],'directorate'=>$row['directorate'],'project_code'=>$row['project_code']??$row['risk_project_code']??$row['case_number']??null,'title'=>$row['topic_title']??$row['project_name']??$row['risk_description']??$row['case_subject']??null,'status'=>$row['status'],'discussion_date'=>$row['discussion_date'],'selected_by'=>$row['selected_by'],'selected_at'=>$row['selected_at']];}$sheets[]=['name'=>$locale==='en'?'Mayor agenda':'Агенда на Градоначалникот','headers'=>$this->localizedHeaders(array_keys($agendaRows[0]??['priority'=>null]),$locale),'rows'=>$agendaRows];}
        $directories=[];foreach($projects as$row){$name=$row['directorate_code'].' · '.$row['directorate'];$directories[$name][]=['record_type'=>$locale==='en'?'Project':'Проект','id'=>$row['id'],'code'=>$row['code'],'title'=>$row['name'],'status'=>$row['status'],'progress'=>$row['progress'],'risk_score'=>null,'next_review'=>null,'details'=>$row['objective']];}foreach($risks as$row){$name=$row['directorate_code'].' · '.$row['directorate'];$directories[$name][]=['record_type'=>$locale==='en'?'Risk':'Ризик','id'=>$row['id'],'code'=>$row['project_code'],'title'=>$row['description'],'status'=>$row['status'],'progress'=>null,'risk_score'=>$row['residual_score']??$row['inherent_score'],'next_review'=>$row['review_at'],'details'=>$row['category'].' · '.($row['project']??'')];}
        foreach($directories as$name=>$rows)$sheets[]=['name'=>mb_substr($name,0,31),'headers'=>$this->localizedHeaders(array_keys($rows[0]),$locale),'rows'=>$rows];
        $sheets[]=['name'=>$locale==='en'?'Live reports':'Извештаи во живо','headers'=>$this->localizedHeaders(array_keys($updates[0]??['id'=>null]),$locale),'rows'=>$updates];
        $this->audit->record($this->userId(),'dashboard.exported','Dashboard',null,[],['format'=>'xlsx','sheets'=>count($sheets),'locale'=>$locale]);
        (new TabularExport())->xlsx('e-kabineti-dashboard-'.date('Ymd-His'),$sheets);
    }

    public function listExport(string $module,string $format): never
    {
        if(!in_array($format,['csv','xlsx'],true))throw new HttpException(404,'Форматот не е поддржан.');
        [$headers,$rows]=$this->exportData($module);if($module==='budget'){unset($headers['owner_directorate_id']);foreach($rows as&$row)unset($row['owner_directorate_id']);unset($row);}$locale=Translator::locale($this->auth->user());$headers=$this->localizedHeaders(array_keys($headers),$locale,$headers);
        $this->audit->record($this->userId(),'list.exported','Report',null,[],['module'=>$module,'format'=>$format,'filters'=>$_GET,'row_count'=>count($rows),'locale'=>$locale]);
        $export=new TabularExport();$filename='e-kabineti-'.$module.'-'.date('Ymd-His');
        if($format==='csv')$export->csv($filename,$headers,$rows);
        $export->xlsx($filename,[['name'=>Translator::text(ucfirst($module),$locale),'headers'=>$headers,'rows'=>$rows]]);
    }

    public function help(?string $module=null): never
    {
        $locale=Translator::locale($this->auth->user());$catalog=HelpCatalog::all($locale);
        if($module===null){$cards='';foreach($catalog as$item)$cards.='<a class="manual-card" href="/help/'.View::e($item['key']).'"><strong>'.View::e($item['title']).'</strong><span>'.View::e($item['purpose']).'</span></a>';$body='<section class="card manual-intro"><h2>'.($locale==='en'?'How to use this manual':'Како се користи овој прирачник').'</h2><p>'.($locale==='en'?'Open a module to understand every field, its relationship to other data and the process from entry to outcome. The same manual is available from each list.':'Отворете модул за да го разберете секое поле, неговата врска со другите податоци и процесот од внесувањето до резултатот. Истиот прирачник се отвора и од секоја листа.').'</p></section><div class="manual-grid">'.$cards.'</div>';$this->view->render('Прирачник на системот',$body);}
        if(!isset($catalog[$module]))throw new HttpException(404,'Модулот од прирачникот не е пронајден.');$item=$catalog[$module];$rows='';foreach($item['fields']as$field)$rows.='<tr><td><strong>'.View::e($field['name']).'</strong></td><td>'.View::e($field['description']).'</td><td><code>'.View::e($field['relation']).'</code></td></tr>';$steps='';foreach($item['flow']as$index=>$step)$steps.='<li><span>'.($index+1).'</span><strong>'.View::e($step).'</strong></li>';
        $body='<p><a class="button button-secondary" href="/help">'.($locale==='en'?'All manuals':'Сите прирачници').'</a></p><section class="card"><p class="lead">'.View::e($item['purpose']).'</p></section><section class="card"><h2>'.($locale==='en'?'Fields and relationships':'Полиња и врски').'</h2><div class="table-wrap"><table><thead><tr><th>'.($locale==='en'?'Field':'Област').'</th><th>'.($locale==='en'?'Meaning and behavior':'Значење и функција').'</th><th>'.($locale==='en'?'Data relationship':'Врска на податоците').'</th></tr></thead><tbody>'.$rows.'</tbody></table></div></section><section class="card"><h2>'.($locale==='en'?'Process diagram':'Дијаграм на процесот').'</h2><ol class="process-diagram" aria-label="'.($locale==='en'?'Process flow':'Тек на процесот').'">'.$steps.'</ol></section>';
        $this->view->render($item['title'].' · '.($locale==='en'?'Manual':'Прирачник'),$body);
    }

    public function projects(): never
    {
        [, $rows]=$this->exportData('projects',true);
        // Count cards (also filters): by status and with late tasks, within the user's scope and the directorate/search filters.
        [$where,$params]=$this->scope->sql($this->userId(),'p.directorate_id','pc');$directorate=$this->request->integer('directorate_id');$q=trim((string)$this->request->input('q',''));
        if($directorate>0){$where.=' AND p.directorate_id=:pcDir';$params['pcDir']=$directorate;}if($q!==''){$where.=' AND '.$this->likeAny(['p.code','p.name','p.objective'],$q,$params,'pcq_');}
        // Derived table: SQL Server refuses an aggregate over a subquery (error 130).
        $c=$this->db->one("SELECT SUM(CASE WHEN x.status='active' THEN 1 ELSE 0 END) active,SUM(CASE WHEN x.status='on_hold' THEN 1 ELSE 0 END) on_hold,SUM(CASE WHEN x.status='completed' THEN 1 ELSE 0 END) completed,SUM(x.late) late,COUNT(*) total FROM (SELECT p.status,CASE WHEN EXISTS(SELECT 1 FROM project_tasks lt WHERE lt.project_id=p.id AND lt.status NOT IN ('done','cancelled') AND lt.due_at<CONVERT(date,SYSUTCDATETIME())) THEN 1 ELSE 0 END late FROM projects p WHERE {$where}) x",$params)?:[];
        $base=array_filter(['directorate_id'=>$directorate?:null,'q'=>$q!==''?$q:null,'view'=>$this->request->input('view')==='cards'?'cards':null]);
        $status=(string)$this->request->input('status','');$late=$this->request->input('late')==='1';
        $card=function(string $label,int $value,array $filter,bool $active,string $class='') use($base): string { return '<a class="stat-filter'.($class!==''?' '.$class:'').($active?' is-active':'').'" href="/projects?'.View::e(http_build_query($active?$base:$base+$filter)).'"'.($active?' aria-current="true"':'').'><span>'.View::e($label).'</span><strong>'.$value.'</strong></a>'; };
        $cards='<nav class="stat-filters" aria-label="Филтрирај според состојбата">'.$card('Активни',(int)($c['active']??0),['status'=>'active'],$status==='active'&&!$late).$card('Со задоцнета задача',(int)($c['late']??0),['late'=>'1'],$late,'stat-filter--danger').$card('На чекање',(int)($c['on_hold']??0),['status'=>'on_hold'],$status==='on_hold'&&!$late).$card('Завршена',(int)($c['completed']??0),['status'=>'completed'],$status==='completed'&&!$late,'stat-filter--success').'</nav>';
        $cardsView=$this->request->input('view')==='cards';$query=$_GET;
        $toggle='<div class="view-toggle" role="group" aria-label="Приказ"><a href="/projects?'.View::e(http_build_query(array_diff_key($query,['view'=>1]))).'"'.(!$cardsView?' class="is-active" aria-current="true"':'').'>Табела</a><a href="/projects?'.View::e(http_build_query(['view'=>'cards']+$query)).'"'.($cardsView?' class="is-active" aria-current="true"':'').'>Мапа</a></div>';
        $mine=$this->request->input('mine')==='1';
        $head='<div class="panel-heading"><h2>'.(int)$this->pagination()->total.' projekte</h2><div class="inline-actions"><a class="chip'.($mine?' is-active':'').'" href="/projects?'.View::e(http_build_query($mine?array_diff_key($query,['mine'=>1]):['mine'=>'1']+$query)).'">Само моите</a>'.$toggle.($this->scope->can($this->userId(),'create','project')?'<a class="button" href="/projects/new">Нов проект</a>':'').'</div></div>';
        $body=$cards.$this->filterBar('projects',['directorate','status','q']).'<section class="card">'.$head.($cardsView?$this->projectCards($rows):$this->projectsListTable($rows)).$this->pager().'</section>';
        $this->view->render('Проекти',$body);
    }

    public function procurementProjects(): never
    {
        $q=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$where=['1=1'];$params=[];
        if($q!==''){$where[]='(pp.procurement_code LIKE :q1 OR pp.contract_code LIKE :q2 OR pp.contract_title LIKE :q3 OR pp.contracting_party LIKE :q4 OR pp.economic_codes LIKE :q5 OR pp.project_codes LIKE :q6)';foreach(range(1,6)as$i)$params['q'.$i]='%'.$q.'%';}
        if($status!==''){$where[]='pp.procurement_status=:status';$params['status']=$status;}
        $rows=$this->pagedQuery("SELECT pp.*,
            COALESCE((SELECT SUM(ee.principal_amount) FROM enforcement_executions ee WHERE ee.procurement_project_id=pp.id),0) execution_principal_amount,
            STUFF((SELECT ', '+p.code+' · '+p.name FROM procurement_project_links ppl JOIN projects p ON p.id=ppl.project_id WHERE ppl.procurement_project_id=pp.id ORDER BY p.code FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,2,'') linked_projects
            FROM procurement_projects pp WHERE ".implode(' AND ',$where).' ORDER BY pp.last_imported_at DESC,pp.procurement_code,pp.contract_code',$params);$pager=$this->pager();
        $statuses=$this->db->all("SELECT DISTINCT procurement_status FROM procurement_projects WHERE NULLIF(procurement_status,'') IS NOT NULL ORDER BY procurement_status");
        $options='<option value="">Сите статуси</option>';foreach($statuses as$item){$value=(string)$item['procurement_status'];$options.='<option value="'.View::e($value).'"'.($status===$value?' selected':'').'>'.View::e($value).'</option>';}
        $table='';foreach($rows as$row){$money=static fn(mixed$v):string=>$v===null||$v===''?'—':number_format((float)$v,2,',','.').' ден.';$table.='<tr><td data-label="Шифра"><strong>'.View::e((string)$row['procurement_code']).'</strong><br><small>'.View::e((string)($row['contract_code']??'')).'</small></td><td data-label="Договори">'.View::e((string)($row['contract_title']??'—')).'<br><small>'.View::e((string)($row['contracting_party']??'')).'</small></td><td data-label="Статус">'.View::e((string)($row['procurement_status']??'—')).'</td><td data-label="Вкупно">'.$money($row['total']).'</td><td data-label="Реализирано">'.$money($row['realized_amount']).'</td><td data-label="Платено">'.$money($row['total_paid_amount']).'</td><td data-label="Главница од извршувањата">'.$money($row['execution_principal_amount']).'</td><td data-label="Шифри">'.View::e((string)($row['economic_codes']??'—')).'<br><small>'.View::e((string)($row['project_codes']??'')).'</small></td><td data-label="Проекти">'.View::e((string)($row['linked_projects']??'Без врска')).'</td><td data-label="Ажурирано">'.View::e(substr((string)$row['last_imported_at'],0,16)).'</td></tr>';}
        if($table==='')$table='<tr><td colspan="10">Не е пронајден ниеден договор за јавна набавка.</td></tr>';
        $body='<form method="get" class="filter-bar"><label>Пребарај<input name="q" value="'.View::e($q).'" placeholder="Шифра, договор, оператор, економска шифра..."></label><label>Статус<select name="status">'.$options.'</select></label><button class="primary">Филтрирај</button><a class="button button-secondary" href="/procurement-projects">Исчисти</a></form><section class="card"><p class="muted">'.$this->pagination()->total.' записи · податоците се ажурираат од увозот на листата на јавни набавки.</p><div class="table-wrap"><table><thead><tr><th>Шифра / договор</th><th>Наслов / оператор</th><th>Статус</th><th>Вкупно</th><th>Реализирано</th><th>Вкупно платено</th><th>Главница од извршувањата</th><th>Економски шифри / шифри на проекти</th><th>Поврзани проекти</th><th>Ажурирано</th></tr></thead><tbody>'.$table.'</tbody></table></div>'.$pager.'</section>';
        $this->view->render('Листа на јавни набавки',$body);
    }

    public function executedCases(): never
    {
        $q=trim((string)($_GET['q']??''));$year=(int)($_GET['year']??0);$status=trim((string)($_GET['status']??''));$where=['1=1'];$params=[];
        if($q!==''){$where[]='(ee.journal_voucher_number LIKE :q1 OR ee.source_document_number LIKE :q2 OR ee.beneficiary LIKE :q3 OR ee.description LIKE :q4 OR bl.code LIKE :q5 OR pp.procurement_code LIKE :q6)';foreach(range(1,6)as$i)$params['q'.$i]='%'.$q.'%';}
        if($year>=2020&&$year<=2100){$where[]='ee.fiscal_year=:year';$params['year']=$year;}if($status!==''){$where[]='ee.classification_status=:status';$params['status']=$status;}
        $rows=$this->pagedQuery("SELECT ee.id,ee.fiscal_year,CONVERT(varchar(10),ee.document_date,23) document_date,ee.journal_voucher_number,ee.source_document_number,ee.beneficiary,bl.code budget_code,d.code directorate_code,ee.debit_amount,ee.credit_amount,ee.net_amount,ee.principal_amount,ee.fine_amount,ee.court_fee_amount,ee.interest_amount,ee.classification_status,pp.procurement_code,pp.contract_code FROM enforcement_executions ee JOIN budget_lines bl ON bl.id=ee.budget_line_id JOIN directorates d ON d.id=bl.directorate_id LEFT JOIN procurement_projects pp ON pp.id=ee.procurement_project_id WHERE ".implode(' AND ',$where).' ORDER BY ee.document_date DESC,ee.id DESC',$params);
        $table='';foreach($rows as$row)$table.='<tr><td><a href="/executed-cases/'.(int)$row['id'].'"><strong>#'.(int)$row['id'].'</strong></a><br><small>'.View::e($row['journal_voucher_number']).'</small></td><td>'.View::e($row['document_date']).'</td><td>'.View::e($row['beneficiary']?:'—').'<br><small>'.View::e($row['source_document_number']?:'').'</small></td><td><strong>'.View::e($row['budget_code']).'</strong><br><small>'.View::e($row['directorate_code']).'</small></td><td>'.View::money($row['debit_amount']).'</td><td>'.View::money($row['credit_amount']).'</td><td>'.View::money($row['net_amount']).'</td><td>'.View::money($row['principal_amount']).' / '.View::money($row['fine_amount']).' / '.View::money($row['court_fee_amount']).' / '.View::money($row['interest_amount']).'</td><td>'.View::e($row['classification_status']).'</td><td>'.View::e(trim(($row['procurement_code']??'').' '.($row['contract_code']??''))?:'—').'</td></tr>';
        if($table==='')$table='<tr><td colspan="10">Нема извршени предмети.</td></tr>';
        $budget=$this->pagedQuery("SELECT ee.fiscal_year,d.code directorate,bl.code,bl.name,bl.total_amount approved_budget,
            COALESCE((SELECT SUM(e.amount) FROM expenditures e JOIN budget_allocations ba ON ba.id=e.budget_allocation_id WHERE ba.budget_line_id=bl.id),0) operational_spent,
            COUNT(*) execution_rows,SUM(ee.debit_amount) debit,SUM(ee.credit_amount) credit,SUM(ee.net_amount) enforcement_net,
            SUM(ee.principal_amount) principal,SUM(ee.fine_amount) fines,SUM(ee.court_fee_amount) court_fees,SUM(ee.interest_amount) interest,
            SUM(CASE WHEN ee.classification_status<>'classified' THEN 1 ELSE 0 END) unclassified_rows,
            bl.total_amount-SUM(ee.net_amount) remaining_after_enforcement,CONVERT(varchar(19),MAX(ee.updated_at),120) last_updated
            FROM enforcement_executions ee JOIN budget_lines bl ON bl.id=ee.budget_line_id JOIN directorates d ON d.id=bl.directorate_id LEFT JOIN procurement_projects pp ON pp.id=ee.procurement_project_id
            WHERE ".implode(' AND ',$where).' GROUP BY ee.fiscal_year,bl.id,d.code,bl.code,bl.name,bl.total_amount ORDER BY ee.fiscal_year DESC,d.code,bl.code',$params,'state');
        $body='<form method="get" class="filter-bar"><label>Пребарај<input name="q" value="'.View::e($q).'" placeholder="Налог, документ, корисник, шифра..."></label><label>Година<input type="number" name="year" min="2020" max="2100" value="'.($year?:'').'"></label><label>Статус<select name="status"><option value="">Сите</option><option value="unclassified"'.($status==='unclassified'?' selected':'').'>Некласифицирано</option><option value="partial"'.($status==='partial'?' selected':'').'>Делумно</option><option value="classified"'.($status==='classified'?' selected':'').'>Класифицирано</option><option value="needs_reclassification"'.($status==='needs_reclassification'?' selected':'').'>Бара прекласификација</option></select></label><button class="primary">Филтрирај</button></form><section class="card"><h2>Извршувања</h2><div class="table-wrap"><table><thead><tr><th>Предмет / налог</th><th>Датум</th><th>Корисник</th><th>Буџетска шифра</th><th>Должи</th><th>Побарува</th><th>Нето</th><th>Главница / казна / такса / камата</th><th>Статус</th><th>Јавни набавки</th></tr></thead><tbody>'.$table.'</tbody></table></div>'.$this->pager().'</section><section class="card"><h2>Буџетска состојба од извршувањата</h2>'.$this->simpleTable($budget,'state').'</section>';
        $this->view->render('Извршени предмети',$body);
    }

    public function executedCase(int $id): never
    {
        $row=$this->db->one('SELECT ee.*,LOWER(sys.fn_varbintohexstr(CONVERT(varbinary(8),ee.row_version))) row_version_token,bl.code budget_code,bl.name budget_name,d.code directorate_code,pp.procurement_code,pp.contract_code FROM enforcement_executions ee JOIN budget_lines bl ON bl.id=ee.budget_line_id JOIN directorates d ON d.id=bl.directorate_id LEFT JOIN procurement_projects pp ON pp.id=ee.procurement_project_id WHERE ee.id=:id',['id'=>$id]);if(!$row)throw new HttpException(404,'Извршениот предмет не е пронајден.');
        $details=[['Област'=>'Налог од дневникот','Вредност'=>$row['journal_voucher_number']],['Област'=>'Изворен документ','Вредност'=>$row['source_document_number']],['Област'=>'Датум','Вредност'=>$row['document_date']],['Област'=>'Корисник','Вредност'=>$row['beneficiary']],['Област'=>'Опис','Вредност'=>$row['description']],['Област'=>'Изворен блок','Вредност'=>$row['coding_block_original']],['Област'=>'Буџетска ставка','Вредност'=>$row['budget_code'].' · '.$row['budget_name']],['Област'=>'Должи / Побарува / Нето','Вредност'=>View::money($row['debit_amount']).' / '.View::money($row['credit_amount']).' / '.View::money($row['net_amount'])],['Област'=>'Статус','Вредност'=>$row['classification_status']]];
        $body='<p><a class="button button-secondary" href="/executed-cases">Назад кон листата</a></p><section class="card"><h2>Предмет #'.$id.'</h2>'.$this->simpleTable($details).'</section>';
        if($this->scope->canManageExecutedCaseFinance($this->userId())){$lines=$this->db->all('SELECT bl.id,bl.code,bl.name,d.code directorate_code FROM budget_lines bl JOIN budget_versions bv ON bv.id=bl.budget_version_id JOIN budget_cycles bc ON bc.id=bv.budget_cycle_id JOIN directorates d ON d.id=bl.directorate_id WHERE bv.is_official=1 AND bc.base_year=:year ORDER BY d.code,bl.code',['year'=>$row['fiscal_year']]);$opts='';foreach($lines as$line)$opts.='<option value="'.(int)$line['id'].'"'.((int)$line['id']===(int)$row['budget_line_id']?' selected':'').'>'.View::e($line['directorate_code'].' · '.$line['code'].' · '.$line['name']).'</option>';$body.='<section class="card"><h2>Финансиска контрола</h2><form method="post" action="/executed-cases/'.$id.'/finance" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="row_version" value="'.View::e($row['row_version_token']).'"><label>Буџетска ставка<select name="budget_line_id" required>'.$opts.'</select></label><label>Должи<input name="debit_amount" value="'.View::e($row['debit_amount']).'" required></label><label>Побарува<input name="credit_amount" value="'.View::e($row['credit_amount']).'" required></label><label class="wide">Причина<textarea name="reason" maxlength="1000" required></textarea></label><button class="primary">Зачувај ја финансиската контрола</button></form></section>';}
        if($this->scope->canManageExecutedCaseLegal($this->userId())){$procurements=$this->db->all('SELECT TOP 2000 id,procurement_code,contract_code,contract_title FROM procurement_projects ORDER BY procurement_code,contract_code');$opts='<option value="">Без врска</option>';foreach($procurements as$p)$opts.='<option value="'.(int)$p['id'].'"'.((int)$p['id']===(int)($row['procurement_project_id']??0)?' selected':'').'>'.View::e($p['procurement_code'].' · '.($p['contract_code']?:$p['contract_title'])).'</option>';$body.='<section class="card"><h2>Правна распределба</h2><form method="post" action="/executed-cases/'.$id.'/legal" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="row_version" value="'.View::e($row['row_version_token']).'"><label>Главница<input name="principal_amount" value="'.View::e($row['principal_amount']).'" required></label><label>Казна<input name="fine_amount" value="'.View::e($row['fine_amount']).'" required></label><label>Судска такса<input name="court_fee_amount" value="'.View::e($row['court_fee_amount']).'" required></label><label>Камата<input name="interest_amount" value="'.View::e($row['interest_amount']).'" required></label><label class="wide">Предмет на набавката<select name="procurement_project_id">'.$opts.'</select></label><button class="primary">Зачувај ја правната распределба</button></form></section>';}
        $this->view->render('Извршен предмет #'.$id,$body);
    }

    public function projectCreate(): never
    {
        if(!$this->scope->can($this->userId(),'create','project'))throw new HttpException(403,'Немате дозвола за создавање проекти.');
        [$dWhere,$dParams]=$this->scope->sql($this->userId(),'id','dir');
        $dirs=$this->db->all("SELECT id,code,name FROM directorates WHERE active=1 AND {$dWhere} ORDER BY name",$dParams);
        $opts='';foreach($dirs as$d)$opts.='<option value="'.(int)$d['id'].'">'.View::e($d['code'].' · '.$d['name']).'</option>';
        $managers=$this->db->all("SELECT DISTINCT u.id,u.name,u.username FROM users u JOIN user_role_scopes urs ON urs.user_id=u.id JOIN roles r ON r.id=urs.role_id WHERE u.status='active' AND COALESCE(r.base_role_code,r.code) IN ('mayor','mayor_admin','deputy_mayor','director','directors_assistant','project_manager','system_admin') AND (urs.valid_from IS NULL OR urs.valid_from<=SYSUTCDATETIME()) AND (urs.valid_to IS NULL OR urs.valid_to>=SYSUTCDATETIME()) ORDER BY u.name");
        $managerOptions='<option value="">Изберете носител / одговорно лице</option>';foreach($managers as$manager)$managerOptions.='<option value="'.(int)$manager['id'].'">'.View::e($manager['name'].' · @'.$manager['username']).'</option>';
        $body='<p><a class="button button-secondary" href="/projects">Назад кон листата на проекти</a></p><section class="card"><h2>Нов проект</h2><form method="post" action="/projects" enctype="multipart/form-data" class="form-grid">'.$this->view->csrf().'<label>Сектор<select name="directorate_id" required>'.$opts.'</select></label><label>Носител / одговорно лице<select name="manager_id" required>'.$managerOptions.'</select></label><label>Шифра<input name="code" maxlength="50" required></label><label>Назив<input name="name" maxlength="250" required></label><label>Почеток<input type="date" name="starts_at"></label><label>Завршување<input type="date" name="ends_at"></label><label>Локација<input name="location_name" maxlength="250"></label><label>Адреса<input name="address" maxlength="500"></label>'.EvidenceUi::geo().'<label class="wide">Цел<textarea name="objective"></textarea></label><label><input type="checkbox" name="has_budget_impact" value="1"> Има буџетско влијание</label>'.'<label>Буџетска категорија на проектот<select name="budget_category" required>'.$this->budgetCategoryOptions('capital_investments').'</select><small class="muted">Проектот се поврзува само со буџетски ставки од оваа категорија, дури и кога ставката е на друг сектор.</small></label>'.$this->initialEvidenceFields().'<button class="primary">Создај го проектот</button></form></section>';
        $this->view->render('Нов проект',$body);
    }

    public function projectTaskCreate(int$id): never
    {
        $project=$this->projectForAction($id);$owners=$this->projectTaskOwners((int)$project['directorate_id']);$options='<option value="">Без одговорно лице</option>';foreach($owners as$owner)$options.='<option value="'.(int)$owner['id'].'">'.View::e($owner['name'].' · @'.$owner['username']).'</option>';
        $body=$this->projectActionHeader($project).'<section class="card"><h2>Нова задача</h2><form method="post" action="/projects/'.$id.'/tasks" enctype="multipart/form-data" class="form-grid">'.$this->view->csrf().'<label>Наслов<input name="title" maxlength="250" required></label><label>Одговорно лице<select name="owner_id">'.$options.'</select></label><label>Датум на почеток<input type="date" name="starts_at"></label><label>Рок<input type="date" name="due_at"></label><label>Тежина во проектот (%)<input name="weight_percent" type="number" min="0" max="100" step="0.01" required></label><label>Напредок (%)<input name="progress" type="number" min="0" max="100" value="0" required></label><label>Статус<select name="status"><option value="not_started">Не е започната</option><option value="in_progress">Во реализација</option><option value="blocked">Блокирано</option><option value="done">Завршена</option><option value="cancelled">Откажано</option></select></label><label class="wide">Следен чекор<textarea name="next_step" maxlength="5000"></textarea></label><label class="wide">Зависности / белешки<textarea name="dependency_notes" maxlength="5000"></textarea></label>'.$this->initialEvidenceFields().'<button class="primary">Создај ја задачата</button></form></section>';
        $this->view->render('Нова задача · '.$project['code'],$body);
