    public function projectBudgetCreate(int$id): never
    {
        $project=$this->projectForAction($id);if(!$this->scope->allowsFinancial($this->userId(),(int)$project['directorate_id']))throw new HttpException(403,'Немате финансиска улога за секторот на проектот.');if(!(bool)$project['has_budget_impact'])$this->view->render('Буџетска врска · '.$project['code'],$this->projectActionHeader($project).'<section class="card"><div class="alert error">Вклучете „Има буџетско влијание“ во Уреди проект пред поврзување со буџетска ставка.</div><a class="button" href="/projects/'.$id.'/edit">Уреди го проектот</a></section>');
        // Finance and the administrator may link lines of any directorate and category; everyone else sees the project's own directorate and category.
        $cross=$this->scope->canLinkAcrossBudget($this->userId());
        $lineFilter=$cross?'1=1':'bl.directorate_id=:owner AND bl.budget_category=:category';$lineParams=$cross?[]:['owner'=>(int)$project['directorate_id'],'category'=>(string)($project['budget_category']??'capital_investments')];
        $lines=$this->db->all("SELECT bl.id,bc.base_year,bl.code,bl.name,bl.budget_category,d.code owner_code,bl.total_amount,bl.total_amount-COALESCE((SELECT SUM(ba.current_amount) FROM budget_allocations ba WHERE ba.budget_line_id=bl.id),0) remaining FROM budget_lines bl JOIN budget_versions bv ON bv.id=bl.budget_version_id JOIN budget_cycles bc ON bc.id=bv.budget_cycle_id JOIN directorates d ON d.id=bl.directorate_id WHERE {$lineFilter} AND bv.is_official=1 AND bl.budget_category IS NOT NULL ORDER BY bc.base_year DESC,d.name,bl.code",$lineParams);$options='';foreach($lines as$line)$options.='<option value="'.(int)$line['id'].'">'.View::e($line['base_year'].' · '.$line['owner_code'].' · '.$line['code'].' · '.$line['name'].' · '.(self::BUDGET_CATEGORIES[$line['budget_category']]??'').' · нераспределени ').View::money($line['remaining']).'</option>';
        $body=$this->projectActionHeader($project).'<section class="card"><h2>Поврзи го проектот со буџетска ставка</h2><p class="muted">'.($cross?'Како Сектор за финансии / Администратор можете да избирате ставки од секој сектор и категорија.':'Се прикажуваат само ставките на секторот на проектот со категорија <strong>'.View::e(self::BUDGET_CATEGORIES[(string)($project['budget_category']??'capital_investments')]??'').'</strong>. Ставките на другите сектори или категории ги поврзува Секторот за финансии или Администраторот.').' За ретроактивен проект можете истовремено да ја создадете и обврската.</p><form method="post" action="/projects/'.$id.'/budget" class="form-grid">'.$this->view->csrf().'<label>Буџетска ставка<select name="budget_line_id" required>'.$options.'</select></label><label>Износ (МКД)<input name="amount" inputmode="decimal" required></label><label><input type="checkbox" name="retroactive" value="1"> Создај ја и ретроактивната обврска</label><label>Референца на обврската<input name="commitment_reference" maxlength="100"></label><label>Добавувач / корисник<input name="supplier" maxlength="250"></label><label>Датум на обврската<input type="date" name="committed_at"></label><button class="primary">Зачувај ја буџетската врска</button></form></section>';
