    public function project(int $id): never
    {
        $project=$this->db->one('SELECT p.*,d.name directorate,u.name manager FROM projects p JOIN directorates d ON d.id=p.directorate_id LEFT JOIN users u ON u.id=p.manager_id WHERE p.id=:id',['id'=>$id]); if(!$project)throw new HttpException(404,'Проектот не е пронајден.'); (new EvidenceAccess($this->db,$this->scope,$this->userId()))->project($id);
        $canEdit=$this->scope->can($this->userId(),'create','project');
        try{(new EvidenceAccess($this->db,$this->scope,$this->userId()))->project($id,true);$canWrite=true;}catch(HttpException){$canWrite=false;}
        $tasks=$this->projectTaskRows($this->db->all('SELECT t.id,t.title,t.owner_id,u.name owner,CONVERT(varchar(10),t.starts_at,23) starts_at,CONVERT(varchar(10),t.due_at,23) due_at,t.status,t.progress,t.weight_percent,CAST(t.weight_percent*t.progress/100.0 AS decimal(7,2)) contribution,t.next_step,t.dependency_notes,LOWER(sys.fn_varbintohexstr(CONVERT(varbinary(8),t.row_version))) row_version_token,(SELECT COUNT(*) FROM attachments a WHERE a.entity_type=\'App\\Models\\ProjectTask\' AND a.entity_id=t.id) documents FROM project_tasks t LEFT JOIN users u ON u.id=t.owner_id WHERE t.project_id=:id ORDER BY CASE WHEN t.status IN (\'done\',\'cancelled\') THEN 1 ELSE 0 END,t.due_at,t.id',['id'=>$id]));
        $counts=['reports'=>(int)$this->db->scalar('SELECT COUNT(*) FROM progress_updates WHERE project_id=:id',['id'=>$id]),'documents'=>(int)$this->db->scalar("SELECT COUNT(*) FROM attachments a LEFT JOIN project_tasks t ON a.entity_type='App\\Models\\ProjectTask' AND t.id=a.entity_id WHERE (a.entity_type='App\\Models\\Project' AND a.entity_id=:id) OR (t.project_id=:taskProject)",['id'=>$id,'taskProject'=>$id]),'risks'=>(int)$this->db->scalar('SELECT COUNT(*) FROM risks WHERE project_id=:id',['id'=>$id])];
        $tab=(string)$this->request->input('tab','tasks');if(!in_array($tab,['tasks','reports','budget','documents','risks','more'],true))$tab='tasks';
        $body=$this->projectHeader($project,$tasks,$canEdit&&$canWrite).$this->projectHistory($project).$this->projectTabs($id,$tab,count($tasks),$counts);
        if($tab==='tasks'){
            $body.='<section class="card project-tab-panel" id="tasks">'.$this->projectTasksPanel($project,$tasks,$canEdit&&$canWrite).'</section>';
            if($canEdit&&$canWrite)$body.=$this->projectTaskModal($project,$tasks);
        }elseif($tab==='reports'){
            $updates=$this->pagedQuery('SELECT pu.*,u.name author,CONVERT(varchar(10),pu.period,23) period FROM progress_updates pu JOIN users u ON u.id=pu.created_by WHERE pu.project_id=:id ORDER BY pu.id DESC',['id'=>$id],'reports');
            $body.='<section class="card project-tab-panel"><div class="panel-heading"><h2>Извештаи за напредок</h2>'.($this->scope->can($this->userId(),'create','project_report')?'<a class="button" href="/projects/'.$id.'/reports/new">Нов извештај</a>':'').'</div>'.$this->updatesHtml($updates).$this->pager('reports').'</section>';
        }elseif($tab==='budget'){
            $projectAllocations=$this->db->all("SELECT ba.id,bc.base_year fiscal_year,bl.code budget_line,bl.name line_name,ba.current_amount,COALESCE((SELECT SUM(c.amount) FROM commitments c WHERE c.budget_allocation_id=ba.id AND c.status='active'),0) committed,COALESCE((SELECT SUM(e.amount) FROM expenditures e WHERE e.budget_allocation_id=ba.id),0) spent FROM budget_allocations ba JOIN budget_lines bl ON bl.id=ba.budget_line_id JOIN budget_versions bv ON bv.id=bl.budget_version_id JOIN budget_cycles bc ON bc.id=bv.budget_cycle_id WHERE ba.project_id=:id ORDER BY bc.base_year DESC,bl.code",['id'=>$id]);
            $link=$this->scope->can($this->userId(),'create','allocation')&&$this->scope->allowsFinancial($this->userId(),(int)$project['directorate_id'])?'<a class="button" href="/projects/'.$id.'/budget/new">Поврзи со буџетска ставка</a>':'';
            $body.='<section class="card project-tab-panel"><div class="panel-heading"><h2>Буџетски ставки на проектот</h2>'.$link.'</div>'.$this->simpleTable($projectAllocations).'</section>';
            $freeBalance=(new BudgetExecution($this->db))->projectSummary($id);
            if($freeBalance){$body.='<section class="card"><h2>Состојба според FreeBalance</h2><p class="muted">'.($projectAllocations?'Проектот има распределби во е-Кабинет, па тие имаат приоритет; FreeBalance се прикажува само за споредба.':'Проектот сѐ уште нема распределби во е-Кабинет; ефективните вредности се земаат од FreeBalance.').'</p><div class="table-wrap"><table><thead><tr><th>Година</th><th>Состојба на</th><th>Ставка</th><th>Распределено</th><th>Реализирано</th><th>Обврски + преземени обврски</th><th>Салдо</th></tr></thead><tbody>';foreach($this->pageOf($freeBalance,'freebalance') as$r)$body.='<tr><td>'.(int)$r['fiscal_year'].'</td><td>'.View::e($r['as_of']).'</td><td>'.(int)$r['lines'].'</td><td>'.View::money($r['allocated']).'</td><td>'.View::money($r['actual']).'</td><td>'.View::money($r['open_commitments']).'</td><td>'.View::money($r['balance']).'</td></tr>';$body.='</tbody></table></div>'.$this->pager('freebalance').'</section>';}
        }elseif($tab==='documents'){
            $attachmentRows=$this->db->all("SELECT a.id,a.title,a.document_type,a.document_date,a.original_name,a.size_bytes,a.mime_type,a.classification,a.scan_status,a.version,a.created_at,CASE WHEN t.id IS NULL THEN 'Projekti' ELSE CONCAT('Task #',t.id,' · ',t.title) END reference FROM attachments a LEFT JOIN project_tasks t ON a.entity_type='App\\Models\\ProjectTask' AND t.id=a.entity_id WHERE (a.entity_type='App\\Models\\Project' AND a.entity_id=:id) OR (t.project_id=:taskProject) ORDER BY a.id DESC",['id'=>$id,'taskProject'=>$id]);
            $photos=$this->db->all('SELECT pp.id,pp.caption,pp.task_id,t.title task_title,a.id attachment_id,a.original_name,a.scan_status FROM project_photos pp JOIN attachments a ON a.id=pp.attachment_id LEFT JOIN project_tasks t ON t.id=pp.task_id WHERE pp.project_id=:id ORDER BY pp.created_at DESC',['id'=>$id]);$photoHtml='<div class="photo-gallery">';foreach($photos as$photo){$photoHtml.='<figure>';if($photo['scan_status']==='clean')$photoHtml.='<a href="/attachments/'.(int)$photo['attachment_id'].'"><img loading="lazy" src="/attachments/'.(int)$photo['attachment_id'].'?inline=1" alt="'.View::e($photo['caption']?:$photo['original_name']).'"></a>';else $photoHtml.='<p>'.View::e($photo['original_name'].' · '.$photo['scan_status']).'</p>';$photoHtml.='<figcaption>'.($photo['task_id']?'<strong>Task #'.(int)$photo['task_id'].' · '.View::e($photo['task_title']).'</strong><br>':'').View::e($photo['caption']).'</figcaption></figure>';}$photoHtml.='</div>';
            $actions=$this->scope->can($this->userId(),'create','attachment')&&$canWrite?'<div class="inline-actions"><a class="button" href="/projects/'.$id.'/documents/new">Додај документи</a><a class="button button-secondary" href="/projects/'.$id.'/photos/new">Додај фотографии</a></div>':'';
            $body.='<section class="card project-tab-panel"><div class="panel-heading"><h2>Документи</h2>'.$actions.'</div>'.$this->attachmentsTable($this->pageOf($attachmentRows,'documents')).$this->pager('documents').'<h2>Галерија на фотографии</h2>'.($photos?$photoHtml:'<p class="muted">Нема фотографии.</p>').'</section>';
        }elseif($tab==='risks'){
            $risks=$this->db->all('SELECT r.id,r.category,r.description,r.inherent_score,r.residual_score,r.status,CONVERT(varchar(10),r.review_at,23) review_at FROM risks r WHERE r.project_id=:id ORDER BY COALESCE(r.residual_score,r.inherent_score) DESC,r.id DESC',['id'=>$id]);
            $body.='<section class="card project-tab-panel"><div class="panel-heading"><h2>Ризици на проектот</h2><a class="button button-secondary" href="/risks/new">Нов ризик</a></div>'.$this->simpleTable($risks).'</section>';
        }else{
            $extras=EvidenceUi::extras($this->db,$this->scope,$this->userId(),$this->view,'App\\Models\\Project',$id,true);
            $body.=$extras!==''?$extras:'<section class="card project-tab-panel"><p class="muted">Немате дејства за споделување за овој проект.</p></section>';
        }
        $body='<p class="back-link"><a href="'.View::e(View::listUrl('/projects','#project-'.$id)).'">← Листа на проекти</a></p>'.$body;
        $this->view->render($project['code'].' · '.$project['name'],$body);
    }

    /** Tasks of a project with their display state: status label, deadline note, lateness. */
    private function projectTaskRows(array $tasks): array
    {
        $today=new \DateTimeImmutable('today');$labels=['not_started'=>'Не е започната','in_progress'=>'Во реализација','blocked'=>'Блокирано','done'=>'Завршена','cancelled'=>'Откажано'];
        foreach($tasks as&$t){
            $closed=in_array($t['status'],['done','cancelled'],true);$t['late']=false;$t['due_note']=$t['status']==='done'?'Завршена':($t['status']==='cancelled'?'Откажано':'Без рок');
            if(!$closed&&$t['due_at']){$days=(int)$today->diff(new \DateTimeImmutable($t['due_at']))->format('%r%a');$t['late']=$days<0;$t['due_note']=$days<0?'доцнење '.(-$days).' дена':($days===0?'sot':'edhe '.$days.' дена');}
            $t['status_label']=$labels[$t['status']]??$t['status'];
        }
        unset($t);
        return$tasks;
    }

    /** Project fields as they are named on the page (audit before/after states use the column names). */
    private const PROJECT_FIELDS=['code'=>'Шифра','name'=>'Назив','manager_id'=>'Носител / одговорно лице','directorate_id'=>'Сектор','objective'=>'Цел','starts_at'=>'Почеток','ends_at'=>'Завршување','status'=>'Статус','has_budget_impact'=>'Буџетско влијание','budget_category'=>'Буџетска категорија','location_name'=>'Локација','address'=>'Адреса','latitude'=>'Географска ширина','longitude'=>'Географска должина','progress'=>'Напредок','physical_progress'=>'Физички напредок','financial_progress'=>'Финансиски напредок',
        'title'=>'Наслов','owner_id'=>'Одговорно лице','due_at'=>'Рок','weight_percent'=>'Тежина (%)','weight'=>'Тежина (%)','next_step'=>'Следен чекор','dependency_notes'=>'Зависности','starts'=>'Почеток','due'=>'Рок','owner'=>'Одговорно лице','notes'=>'Зависности','next'=>'Следен чекор','period'=>'Период','narrative'=>'Опис','blockers'=>'Пречки','user_id'=>'Корисник','access_level'=>'Ниво на пристап'];
    private const STATUS_LABELS=['draft'=>'Нацрт','active'=>'Активно','on_hold'=>'На чекање','completed'=>'Завршена','cancelled'=>'Откажано','not_started'=>'Не е започната','in_progress'=>'Во реализација','blocked'=>'Блокирано','done'=>'Завршена'];
    private const PROJECT_ACTIONS=['project.created'=>'Проектот е создаден','project.imported'=>'Проектот е увезен / ажуриран од увозот','project.updated'=>'Проектот е уреден','project.shared'=>'Проектот е споделен со корисник','project_task.weights_rebalanced'=>'Тежините на задачите се прераспределени','project_task.created'=>'Нова задача','project_task.updated'=>'Задачата е уредена','project.progress_reported'=>'Извештај за напредок'];

    /**
     * "Krijuar më … nga …" and the edit history of a project (collapsed): edits of the project, of its tasks and its
     * progress reports, from the audit log, newest first, with the fields that changed (before → after).
     */
    private function projectHistory(array $project): string
    {
        $id=(int)$project['id'];
        $events=$this->db->all("SELECT TOP 200 a.id,a.action,a.entity_type,a.entity_id,a.before_state,a.after_state,a.reason,CONVERT(varchar(19),a.occurred_at,120) occurred_at,u.name actor
            FROM audit_events a LEFT JOIN users u ON u.id=a.actor_id
            WHERE (a.entity_type IN ('App\\Models\\Project','Project') AND a.entity_id=:id)
               OR (a.entity_type='App\\Models\\ProjectTask' AND a.entity_id IN (SELECT CAST(t.id AS nvarchar(80)) FROM project_tasks t WHERE t.project_id=:taskProject))
               OR (a.entity_type='App\\Models\\ProgressUpdate' AND a.entity_id IN (SELECT CAST(pu.id AS nvarchar(80)) FROM progress_updates pu WHERE pu.project_id=:reportProject))
            ORDER BY a.occurred_at DESC,a.id DESC",['id'=>(string)$id,'taskProject'=>$id,'reportProject'=>$id]);
        $created=null;
        foreach($events as$event)if(in_array($event['action'],['project.created','project.imported'],true)&&$event['entity_type']!=='App\\Models\\ProjectTask')$created=$event;
        $edited=null;
        foreach($events as$event)if($event['action']!=='project.created'){$edited=$event;break;}
        $userIds=[];
        foreach($events as$event)foreach(['before_state','after_state'] as$state){$data=json_decode((string)$event[$state],true);if(is_array($data))foreach(['manager_id','owner_id','owner','user_id'] as$key)if(isset($data[$key])&&is_numeric($data[$key]))$userIds[(int)$data[$key]]=true;}
        $names=[];
        if($userIds){$marks=[];$params=[];foreach(array_keys($userIds) as$i=>$userId){$marks[]=':u'.$i;$params['u'.$i]=$userId;}foreach($this->db->all('SELECT id,name FROM users WHERE id IN ('.implode(',',$marks).')',$params) as$row)$names[(int)$row['id']]=(string)$row['name'];}
        $who=static fn(array $event): string => View::e($event['actor']??'Систем / увоз');
        $when=static fn(string $at): string => View::e(date('d.m.Y H:i',strtotime($at.' UTC')));
        $summary=$created
            ?'Создадено на <strong>'.$when((string)$created['occurred_at']).'</strong> од <strong>'.$who($created).'</strong>'.($created['action']==='project.imported'?' (import)':'')
            :'Создадено на <strong>'.View::e($project['created_at']?date('d.m.Y H:i',strtotime((string)$project['created_at'].' UTC')):'—').'</strong> <span class="muted">(создавачот не е во ревизијата)</span>';
        if($edited)$summary.=' · последна промена на <strong>'.$when((string)$edited['occurred_at']).'</strong> од <strong>'.$who($edited).'</strong>';
        $items='';
        foreach($events as$event){
            $before=json_decode((string)$event['before_state'],true);$after=json_decode((string)$event['after_state'],true);
            $before=is_array($before)?$before:[];$after=is_array($after)?$after:[];
            $changes='';
            foreach($after as$key=>$value){
                if(!isset(self::PROJECT_FIELDS[$key]))continue;
                $old=$before[$key]??null;
                if($event['action']!=='project.created'&&$event['action']!=='project_task.created'&&$event['action']!=='project.progress_reported'&&$before!==[]&&$this->sameValue($old,$value))continue;
                $show=fn($v): string => $this->historyValue((string)$key,$v,$names);
                $changes.='<li><span class="history-field">'.View::e(self::PROJECT_FIELDS[$key]).'</span> '.($before!==[]&&array_key_exists($key,$before)?'<del>'.$show($old).'</del> → ':'').'<ins>'.$show($value).'</ins></li>';
            }
            $what=self::PROJECT_ACTIONS[$event['action']]??$event['action'];
            if($event['entity_type']==='App\\Models\\ProjectTask')$what.=' · '.(string)($after['title']??$before['title']??('#'.$event['entity_id']));
            $items.='<li class="history-event"><div><strong>'.View::e($what).'</strong> <span class="muted">· '.$when((string)$event['occurred_at']).' · '.$who($event).'</span></div>'
                .($changes!==''?'<ul class="history-changes">'.$changes.'</ul>':'')
                .($event['reason']?'<p class="muted">'.View::e((string)$event['reason']).'</p>':'').'</li>';
        }
        return '<details class="card record-history"><summary><span>'.$summary.'</span><span class="record-history__toggle">Историја на промени ('.count($events).(count($events)===200?'+':'').')</span></summary>'
            .($items!==''?'<ol class="history-list">'.$items.'</ol>':'<p class="muted">Нема евидентирани промени.</p>').'</details>';
    }

    private function sameValue(mixed $old, mixed $new): bool
    {
        $norm=static function(mixed $v): string{if(is_bool($v))return$v?'1':'0';$v=trim((string)$v);if(preg_match('/^(\d{4}-\d{2}-\d{2})[ T]00:00:00(\.0+)?$/',$v,$m))return$m[1];if(is_numeric($v))return rtrim(rtrim(number_format((float)$v,6,'.',''),'0'),'.');return$v;};
        return $norm($old)===$norm($new);
    }

    private function historyValue(string $key, mixed $value, array $names): string
    {
        if($value===null||$value==='')return'<span class="muted">—</span>';
        if(in_array($key,['manager_id','owner_id','owner','user_id'],true)&&is_numeric($value))return View::e($names[(int)$value]??('#'.$value));
        if(in_array($key,['has_budget_impact'],true))return $value?'Да':'Не';
        if($key==='status')return View::e(self::STATUS_LABELS[(string)$value]??(string)$value);
        $text=(string)$value;
        if(preg_match('/^(\d{4}-\d{2}-\d{2})([ T]00:00:00(\.0+)?)?$/',$text,$m))return View::e(date('d.m.Y',strtotime($m[1])));
        return View::e(mb_strlen($text)>300?mb_substr($text,0,300).'…':$text);
    }

    private static function shortDate(?string $date): string { return $date?date('d.m.Y',strtotime($date)):'—'; }

    private function projectHeader(array $project,array $tasks,bool $canManageTasks): string
    {
        $id=(int)$project['id'];$late=count(array_filter($tasks,static fn(array$t):bool=>$t['late']));$done=count(array_filter($tasks,static fn(array$t):bool=>$t['status']==='done'));$running=count(array_filter($tasks,static fn(array$t):bool=>in_array($t['status'],['in_progress','blocked'],true)));
        $menu=[];
        if($this->scope->can($this->userId(),'create','allocation')&&$this->scope->allowsFinancial($this->userId(),(int)$project['directorate_id']))$menu[]=['/projects/'.$id.'/budget/new','Поврзи со буџетска ставка'];
        if($this->scope->can($this->userId(),'create','attachment')){$menu[]=['/projects/'.$id.'/documents/new','Додај документи'];$menu[]=['/projects/'.$id.'/photos/new','Додај фотографии'];}
        try{(new EvidenceAccess($this->db,$this->scope,$this->userId()))->project($id,true,true);$menu[]=['/projects/'.$id.'/share','Сподели со други корисници'];}catch(HttpException){}
        $actions='';
        if($canManageTasks)$actions.='<a class="button primary" href="/projects/'.$id.'/tasks/new" data-modal-open="task-modal"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>Нова задача</a>';
        if($this->scope->can($this->userId(),'create','project_report'))$actions.='<a class="button button-secondary" href="/projects/'.$id.'/reports/new">Нов извештај</a>';
        if($this->scope->can($this->userId(),'create','project'))$actions.='<a class="button button-secondary" href="/projects/'.$id.'/edit">Уреди</a>';
        if($menu){$items='';foreach($menu as[$url,$label])$items.='<a href="'.$url.'">'.View::e($label).'</a>';$actions.='<details class="action-menu"><summary class="button button-secondary" aria-label="Повеќе дејства">⋯</summary><div class="action-menu__panel">'.$items.'</div></details>';}
        $location=$project['latitude']!==null?' · <a href="'.View::e('https://www.google.com/maps/search/?api=1&query='.$project['latitude'].','.$project['longitude']).'" target="_blank" rel="noopener">Локација на мапата</a>':'';
        $period=($project['starts_at']||$project['ends_at'])?' · '.self::shortDate($project['starts_at']).' – '.self::shortDate($project['ends_at']):'';
        $deadline='—';$deadlineNote='Без рок';
        if($project['ends_at']){$days=(int)(new \DateTimeImmutable('today'))->diff(new \DateTimeImmutable(substr((string)$project['ends_at'],0,10)))->format('%r%a');$deadline=self::shortDate($project['ends_at']);$deadlineNote=in_array($project['status'],['completed','cancelled'],true)?'Затворен проект':($days<0?'доцнење '.(-$days).' дена':'edhe '.$days.' дена');}
        $progress=(int)$project['progress'];$financial=(float)($project['financial_progress']??0);
        $html='<section class="card project-hero"><div class="project-hero__main"><div class="project-hero__badges"><span class="code-chip">'.View::e($project['code']).'</span>'.$this->badge((string)$project['status']).($late?'<span class="status-badge status-overdue">'.$late.' task'.($late===1?'':'s').' со доцнење</span>':'').'</div>'
            .'<p class="project-hero__meta">'.View::e($project['directorate']).' · Менаџер: '.View::e($project['manager']??'Неопределено').View::e($period).$location.'</p>'.($project['objective']?'<p class="project-hero__objective">'.View::e($project['objective']).'</p>':'').'</div>'
            .($actions!==''?'<div class="project-hero__actions">'.$actions.'</div>':'').'</section>';
        $html.='<section class="kpi-grid" aria-label="Показатели на проектот">'
            .'<div class="kpi"><span class="kpi__label">Напредок (според тежината)</span><strong class="kpi__value">'.$progress.'%</strong><progress class="progress-bar" max="100" value="'.$progress.'" aria-hidden="true"></progress></div>'
            .'<div class="kpi"><span class="kpi__label">Tasks</span><strong class="kpi__value">'.$done.' / '.count($tasks).'</strong><span class="kpi__note">завршени · '.$running.' во реализација</span></div>'
            .'<div class="kpi"><span class="kpi__label">Рок на проектот</span><strong class="kpi__value">'.$deadline.'</strong><span class="kpi__note">'.View::e($deadlineNote).'</span></div>'
            .'<div class="kpi"><span class="kpi__label">Финансиски напредок</span><strong class="kpi__value">'.rtrim(rtrim(number_format($financial,1,'.',''),'0'),'.').'%</strong><progress class="progress-bar progress-bar--primary" max="100" value="'.min(100,max(0,$financial)).'" aria-hidden="true"></progress></div>'
            .'</section>';
        return$html;
    }

    private function projectTabs(int $id,string $active,int $tasks,array $counts): string
    {
        $tabs=['tasks'=>['Tasks',$tasks],'reports'=>['Извештаи',$counts['reports']],'budget'=>['Буџет',null],'documents'=>['Документи и фотографии',$counts['documents']],'risks'=>['Ризици',$counts['risks']],'more'=>['Споделување и врски',null]];
        $html='<nav class="tabs" aria-label="Делови на проектот">';
        foreach($tabs as$key=>[$label,$count])$html.='<a href="/projects/'.$id.'?tab='.$key.'"'.($key===$active?' aria-current="page" class="is-active"':'').'>'.View::e($label).($count!==null?' <span class="tabs__count">'.(int)$count.'</span>':'').'</a>';
        return$html.'</nav>';
    }

    /** Tasks tab: quick filters, search and the full-width table (task column fixed on the left). */
    private function projectTasksPanel(array $project,array $tasks,bool $editable): string
    {
        $id=(int)$project['id'];$filter=(string)$this->request->input('task_status','all');$q=mb_strtolower(trim((string)$this->request->input('task_q','')));
        $groups=['all'=>['Сите',static fn(array$t):bool=>true],'active'=>['Во реализација',static fn(array$t):bool=>in_array($t['status'],['in_progress','blocked'],true)],'late'=>['Со доцнење',static fn(array$t):bool=>$t['late']],'todo'=>['Не е започната',static fn(array$t):bool=>$t['status']==='not_started'],'done'=>['Завршена',static fn(array$t):bool=>$t['status']==='done']];
        if(!isset($groups[$filter]))$filter='all';
        $chips='';foreach($groups as$key=>[$label,$test]){$n=count(array_filter($tasks,$test));$chips.='<a class="chip'.($key===$filter?' is-active':'').'" href="/projects/'.$id.'?'.View::e(http_build_query(['tab'=>'tasks','task_status'=>$key]+($q!==''?['task_q'=>$q]:[]))).'"'.($key===$filter?' aria-current="true"':'').'>'.View::e($label).' <span>'.$n.'</span></a>';}
        $visible=array_filter($tasks,$groups[$filter][1]);
        if($q!=='')$visible=array_filter($visible,static fn(array$t):bool=>str_contains(mb_strtolower($t['title'].' '.($t['owner']??'').' '.($t['next_step']??'')),$q));
        $weight=array_sum(array_map(static fn(array$t):float=>(float)$t['weight_percent'],$tasks));$contribution=array_sum(array_map(static fn(array$t):float=>(float)$t['contribution'],$tasks));
        $html='<div class="table-toolbar"><form method="get" action="/projects/'.$id.'" class="table-toolbar__search"><input type="hidden" name="tab" value="tasks"><input type="hidden" name="task_status" value="'.View::e($filter).'"><label><span class="visually-hidden">Пребарај задача</span><input type="search" name="task_q" value="'.View::e($q).'" placeholder="Пребарај задача или одговорно лице…"></label></form><div class="chips" role="group" aria-label="Филтрирај ги задачите">'.$chips.'</div></div>';
        if(!$tasks)return$html.'<div class="empty-state">Проектот сѐ уште нема задачи.'.($editable?' <a href="/projects/'.$id.'/tasks/new" data-modal-open="task-modal">Додај ја првата задача</a>.':'').'</div>';
        $rows='';
        foreach($this->pageOf($visible,'tasks') as$t){
            $progress=(int)$t['progress'];$data=['id'=>(int)$t['id'],'title'=>$t['title'],'owner_id'=>$t['owner_id']!==null?(int)$t['owner_id']:'','starts_at'=>$t['starts_at']??'','due_at'=>$t['due_at']??'','weight_percent'=>(string)(float)$t['weight_percent'],'progress'=>$progress,'status'=>$t['status'],'next_step'=>$t['next_step']??'','dependency_notes'=>$t['dependency_notes']??'','row_version'=>$t['row_version_token']];
            $actions=$editable?'<a class="icon-button" href="/projects/'.$id.'/tasks/'.(int)$t['id'].'/edit" data-task-edit="'.View::e(json_encode($data,JSON_UNESCAPED_UNICODE)).'" aria-label="Уреди ја задачата '.View::e($t['title']).'"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 20h4L19 9l-4-4L4 16v4z"/></svg></a>':'';
            $rows.='<tr id="task-'.(int)$t['id'].'"'.($t['late']?' class="is-late"':'').'><td><strong>'.View::e($t['title']).'</strong>'.($t['next_step']?'<small class="cell-sub">'.View::e($t['next_step']).'</small>':'').'</td>'
                .'<td class="nowrap">'.($t['owner']?'<span class="avatar" aria-hidden="true">'.View::e(self::initials((string)$t['owner'])).'</span>'.View::e($t['owner']):'<span class="muted">Без одговорно лице</span>').'</td>'
                .'<td class="nowrap num">'.self::shortDate($t['starts_at']).' – '.self::shortDate($t['due_at']).'</td>'
                .'<td class="nowrap"><span class="num">'.self::shortDate($t['due_at']).'</span><small class="cell-sub '.($t['late']?'text-danger':'').'">'.View::e($t['due_note']).'</small></td>'
                .'<td>'.($t['late']?'<span class="status-badge status-overdue">Со доцнење</span>':$this->badge((string)$t['status'])).'</td>'
                .'<td><span class="progress-cell"><progress class="progress-bar'.($t['late']?' progress-bar--late':'').'" max="100" value="'.$progress.'" aria-hidden="true"></progress><span class="num">'.$progress.'%</span></span></td>'
                .'<td class="num right">'.rtrim(rtrim(number_format((float)$t['weight_percent'],2,'.',''),'0'),'.').'%</td>'
                .'<td class="num right">'.number_format((float)$t['contribution'],1).'%</td>'
                .'<td class="num right">'.(int)$t['documents'].'</td>'
                .($editable?'<td class="right">'.$actions.'</td>':'').'</tr>';
        }
        if($rows==='')$rows='<tr><td colspan="'.($editable?10:9).'">Ниедна задача не одговара на филтерот.</td></tr>';
        $html.='<div class="table-wrap table-wrap--wide"><table class="data-table"><thead><tr><th>Task</th><th>Одговорно лице</th><th>Период</th><th>Рок</th><th>Статус</th><th>Напредок</th><th class="right">Тежина</th><th class="right">Придонес</th><th class="right">Dok.</th>'.($editable?'<th class="right">Дејства</th>':'').'</tr></thead><tbody>'.$rows.'</tbody>'
            .'<tfoot><tr><td>Вкупно · '.count($tasks).' tasks</td><td></td><td></td><td></td><td></td><td class="num">'.(int)$project['progress'].'%</td><td class="num right">'.rtrim(rtrim(number_format($weight,2,'.',''),'0'),'.').'%</td><td class="num right">'.number_format($contribution,1).'%</td><td class="num right">'.array_sum(array_column($tasks,'documents')).'</td>'.($editable?'<td></td>':'').'</tr></tfoot></table></div>'.$this->pager('tasks')
            .'<p class="table-hint">Колоната „Задача“ останува фиксирана лево; табелата се движи хоризонтално со ← → или Shift + тркалце на глувчето.</p>';
        if($editable)$html.='<a class="fab" href="/projects/'.$id.'/tasks/new" data-modal-open="task-modal"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>Нова задача</a>';
        return$html;
    }

    private static function initials(string $name): string { $parts=preg_split('/\s+/u',trim($name))?:[];$out='';foreach(array_slice($parts,0,2)as$part)$out.=mb_strtoupper(mb_substr($part,0,1));return$out; }

    private function projectTaskOwners(int $directorateId): array
    {
        return $this->db->all("SELECT DISTINCT u.id,u.name,u.username FROM users u JOIN user_role_scopes urs ON urs.user_id=u.id JOIN roles r ON r.id=urs.role_id WHERE u.status='active' AND (urs.directorate_id=:d OR COALESCE(r.base_role_code,r.code) IN ('mayor','mayor_admin','finance','system_admin')) AND (urs.valid_from IS NULL OR urs.valid_from<=SYSUTCDATETIME()) AND (urs.valid_to IS NULL OR urs.valid_to>=SYSUTCDATETIME()) ORDER BY u.name",['d'=>$directorateId]);
    }

