        $status='';foreach(['not_started'=>'Не е започната','in_progress'=>'Во реализација','blocked'=>'Блокирано','done'=>'Завршена','cancelled'=>'Откажано']as$value=>$label)$status.='<label class="segmented__option"><input type="radio" name="status" value="'.$value.'"'.($value==='not_started'?' checked':'').'><span>'.$label.'</span></label>';
