            .'<form method="post" action="/projects/'.$id.'/tasks" enctype="multipart/form-data" class="modal__form" data-task-form>'.$this->view->csrf().'<input type="hidden" name="row_version" value="" disabled data-task-version><input type="hidden" name="rebalance" value="0" data-task-rebalance><input type="hidden" name="again" value="0" data-task-again-flag>'
            .'<header class="modal__header"><div><p class="eyebrow">'.View::e($project['code'].' · '.$project['name']).'</p><h2 id="task-modal-title" data-task-title>Нова задача</h2></div><button type="button" class="icon-button" data-modal-close aria-label="Затвори"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button></header>'
            .'<div class="modal__body form-grid">'
            .'<label class="wide">Наслов на задачата<input name="title" maxlength="250" required autofocus></label>'
            .'<label>Одговорно лице<select name="owner_id">'.$owners.'</select></label>'
            .'<fieldset class="segmented"><legend>Статус</legend><div class="segmented__options">'.$status.'</div></fieldset>'
            .'<label>Датум на почеток<input type="date" name="starts_at"></label>'
            .'<label>Рок<input type="date" name="due_at"><small class="field-hint" data-due-hint>'.($deadline?'Рок на проектот: '.self::shortDate($deadline).' (задачата не смее да го надмине)':'').'</small></label>'
            .'<div class="wide weight-box" data-weight-box><div class="weight-box__row"><label>Тежина во проектот (%)<input name="weight_percent" type="number" min="0" max="100" step="0.01" value="0" required data-weight-input></label><div class="weight-box__meter"><p class="weight-box__status" data-weight-status></p><span class="weight-meter" data-weight-meter aria-hidden="true"></span></div><button type="button" class="button button-secondary" data-weight-rebalance hidden>Прераспредели пропорционално</button></div><p class="field-hint" data-weight-help>Тежината на сите задачи мора да изнесува вкупно до 100%.</p></div>'
            .'<label>Напредок (%)<span class="range-field"><input type="range" name="progress" min="0" max="100" step="5" value="0" data-progress-input><output data-progress-output>0%</output></span></label>'
            .'<label>Зависности / белешки<input name="dependency_notes" maxlength="5000" placeholder="на пр. Почнува по канализацијата"></label>'
            .'<label class="wide">Следен чекор<textarea name="next_step" maxlength="5000" rows="2"></textarea></label>'
            .'<div class="wide" data-task-documents>'.EvidenceUi::dropzone('documents[]',true,false,'Опционално · PDF, фотографија, Word, Excel · до '.$this->effectiveUploadMb().' MB','Документи и фотографии').'</div>'
            .'</div>'
            .'<footer class="modal__footer"><span class="muted modal__keys">Esc затвора · Ctrl + Enter зачувува</span><div class="inline-actions"><button type="button" class="button button-secondary" data-modal-close>Откажи</button><button type="button" class="button button-secondary" data-task-again>Зачувај и додај друга</button><button type="submit" class="primary" data-task-submit>Создај ја задачата</button></div></footer>'
            .'</form></dialog>';
    }

    public function cases(): never
    {
        [$where,$params]=$this->scope->sql($this->userId(),'cd.directorate_id','case');
        $rows=$this->db->all("SELECT DISTINCT c.id,c.case_number,c.case_type,c.subject,c.status,c.priority,CONVERT(varchar(10),c.opened_at,23) opened_at,d.name originating_directorate,u.name responsible_user,(SELECT COUNT(*) FROM case_directorates x WHERE x.case_id=c.id) directorate_count,(SELECT COUNT(*) FROM case_tasks t WHERE t.case_id=c.id AND t.status<>'completed') open_tasks,(SELECT TOP 1 td.code FROM case_forwardings f JOIN directorates td ON td.id=f.to_directorate_id WHERE f.case_id=c.id ORDER BY f.forwarded_at DESC,f.id DESC) forwarded_to,(SELECT TOP 1 f.status FROM case_forwardings f WHERE f.case_id=c.id ORDER BY f.forwarded_at DESC,f.id DESC) forward_status,(SELECT TOP 1 f.to_directorate_id FROM case_forwardings f WHERE f.case_id=c.id ORDER BY f.forwarded_at DESC,f.id DESC) forward_to_id FROM administrative_cases c JOIN directorates d ON d.id=c.originating_directorate_id LEFT JOIN users u ON u.id=c.responsible_user_id JOIN case_directorates cd ON cd.case_id=c.id WHERE ({$where}) OR EXISTS(SELECT 1 FROM case_user_access cua WHERE cua.case_id=c.id AND cua.user_id=:caseUser) ORDER BY opened_at DESC",$params+['caseUser'=>$this->userId()]);
        $rows=array_filter($rows,function(array $row): bool{try{(new EvidenceAccess($this->db,$this->scope,$this->userId()))->caseFile((int)$row['id']);return true;}catch(HttpException){return false;}});
        // Forwarded cases: the latest forwarding of each case; "pending" = waiting for receipt by one of my directorates.
        $pendingForMe=fn(array $row): bool => $row['forward_status']==='forwarded'&&$this->scope->allowsDirectorate($this->userId(),(int)$row['forward_to_id']);
        $pending=count(array_filter($rows,$pendingForMe));$forwarded=(string)$this->request->input('forwarded','');
        if($forwarded==='pending')$rows=array_filter($rows,$pendingForMe);elseif($forwarded==='all')$rows=array_filter($rows,static fn(array $row): bool => $row['forwarded_to']!==null);
        $filterOptions='';foreach([''=>'Сите предмети','all'=>'Препратени со пропратен акт','pending'=>'Препратени до мојот сектор, чекаат прием']as$value=>$label)$filterOptions.='<option value="'.$value.'"'.($forwarded===$value?' selected':'').'>'.$label.'</option>';
        $body=($pending?'<section class="card notice"><p><strong>'.$pending.' предмети</strong> препратени до вашиот сектор чекаат потврда за прием. <a href="/cases?forwarded=pending">Прикажи ги</a></p></section>':'').'<form method="get" action="/cases" class="filter-bar"><label>Препраќање<select name="forwarded">'.$filterOptions.'</select></label><button class="primary">Филтрирај</button></form>';
        $body.='<section class="card"><div class="table-wrap"><table><thead><tr><th>Nr.</th><th>Вид / предмет</th><th>Сектор</th><th>Статус</th><th>Приоритет</th><th>Отворени задачи</th><th>Препраќање</th></tr></thead><tbody>';
        foreach($this->pageOf($rows) as$row){$forward=$row['forwarded_to']===null?'—':'→ '.View::e($row['forwarded_to']).'<br><small>'.($row['forward_status']==='received'?'Примени':'Чека прием').'</small>';$body.='<tr><td><a href="/cases/'.(int)$row['id'].'">'.View::e($row['case_number']).'</a></td><td><strong>'.View::e($row['subject']).'</strong><br><small>'.View::e($row['case_type']).'</small></td><td>'.View::e($row['originating_directorate']).' · '.(int)$row['directorate_count'].' drejtori</td><td>'.View::e($row['status']).'</td><td>'.View::e($row['priority']).'</td><td>'.(int)$row['open_tasks'].'</td><td>'.$forward.'</td></tr>';}
        $body.='</tbody></table></div>'.$this->pager().'</section>';
        $this->view->render('Управни предмети',$body);
    }

    public function legalOffice(): never
    {
        $q=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$phase=trim((string)($_GET['phase']??''));$params=[];$where=['c.is_legal=1',$this->legalConfidentialityFilter('c',$params)];
        if($q!==''){$where[]='(c.case_number LIKE :q1 OR c.external_reference LIKE :q2 OR c.court_reference LIKE :q3 OR c.subject LIKE :q4 OR c.authority_name LIKE :q5 OR EXISTS(SELECT 1 FROM legal_case_parties lcp WHERE lcp.case_id=c.id AND lcp.party_name LIKE :q6) OR pp.procurement_code LIKE :q7 OR bl.code LIKE :q8)';foreach(range(1,8)as$i)$params['q'.$i]='%'.$q.'%';}
        if(in_array($status,['new','active','suspended','closed','archived'],true)){$where[]='c.status=:status';$params['status']=$status;}
        if(in_array($phase,['first_instance','appeal','revision','retrial','enforcement'],true)){$where[]='c.procedural_phase=:phase';$params['phase']=$phase;}
        $rows=$this->pagedQuery("SELECT c.id,c.internal_sequence,c.case_number,c.external_reference,c.case_type,c.subject,c.status,c.procedural_phase,c.priority,c.claimed_amount,c.realized_amount,c.currency,CONVERT(varchar(10),c.opened_at,23) opened_at,d.code directorate_code,u.name responsible,du.name deputy,pp.procurement_code,pp.contract_code,bl.code budget_code,(SELECT COUNT(*) FROM case_tasks t WHERE t.case_id=c.id AND t.task_type='deadline' AND t.status<>'completed' AND t.due_at<CONVERT(date,SYSUTCDATETIME())) overdue_deadlines FROM administrative_cases c JOIN directorates d ON d.id=c.originating_directorate_id LEFT JOIN users u ON u.id=c.responsible_user_id LEFT JOIN users du ON du.id=c.deputy_user_id LEFT JOIN procurement_projects pp ON pp.id=c.procurement_project_id LEFT JOIN budget_lines bl ON bl.id=c.budget_line_id WHERE ".implode(' AND ',$where).' ORDER BY CASE c.status WHEN \'new\' THEN 0 WHEN \'active\' THEN 1 WHEN \'suspended\' THEN 2 ELSE 3 END,c.updated_at DESC,c.id DESC',$params);
        $metrics=$this->db->one("SELECT COUNT(*) total_cases,SUM(CASE WHEN status IN ('new','active','suspended') THEN 1 ELSE 0 END) active_cases,COALESCE(SUM(claimed_amount),0) claimed,COALESCE(SUM(realized_amount),0) realized FROM administrative_cases WHERE is_legal=1")?:[];// aggregate counts and amounts include all files; details are filtered
        $upcoming=(int)$this->db->scalar("SELECT COUNT(*) FROM case_tasks t JOIN administrative_cases c ON c.id=t.case_id WHERE c.is_legal=1 AND t.task_type='deadline' AND t.status<>'completed' AND t.due_at BETWEEN CONVERT(date,SYSUTCDATETIME()) AND DATEADD(day,30,CONVERT(date,SYSUTCDATETIME()))");
        $table='';foreach($rows as$row)$table.='<tr><td><a href="/legal-office/cases/'.(int)$row['id'].'"><strong>ZL-'.str_pad((string)$row['internal_sequence'],6,'0',STR_PAD_LEFT).'</strong></a><br><small>'.View::e($row['case_number']).'</small></td><td><strong>'.View::e($row['subject']).'</strong><br><small>'.View::e(($row['case_type']?:'—').' · '.($row['external_reference']?:'Без референца')).'</small></td><td>'.View::e($row['directorate_code']).'</td><td>'.View::e($row['procedural_phase']?:'—').'<br><small>'.View::e($row['status']).'</small></td><td>'.View::e($row['responsible']?:'Неопределено').'<br><small>'.View::e($row['deputy']?:'').'</small></td><td>'.View::e(trim(($row['procurement_code']??'').' '.($row['contract_code']??''))?:'—').'<br><small>'.View::e($row['budget_code']?:'').'</small></td><td>'.View::money($row['claimed_amount']??0).'<br><small>Реализирано '.View::money($row['realized_amount']??0).'</small></td><td>'.((int)$row['overdue_deadlines']>0?'<span class="status-badge status-blocked">'.(int)$row['overdue_deadlines'].' изминати</span>':'—').'</td></tr>';
        if($table==='')$table='<tr><td colspan="8">Не е пронајден ниеден правен предмет.</td></tr>';
        $actions=$this->scope->canWorkLegalOffice($this->userId())?'<a class="button primary" href="/legal-office/cases/new">Нов предмет</a> ':'';$actions.='<a class="button button-secondary" href="/legal-office/reports">Извештаи</a> <a class="button button-secondary" href="/legal-office/work-reports">Работни извештаи (увоз)</a>';if($this->scope->canManageLegalOffice($this->userId()))$actions.=' <a class="button button-secondary" href="/legal-office/users">Корисници на Службата</a>';
        $body='<section class="card"><div class="project-action-bar">'.$actions.'</div><div class="metrics"><div class="metric"><span>Вкупно</span><strong>'.(int)($metrics['total_cases']??0).'</strong></div><div class="metric"><span>Активни</span><strong>'.(int)($metrics['active_cases']??0).'</strong></div><div class="metric"><span>Рокови во 30 дена</span><strong>'.$upcoming.'</strong></div><div class="metric"><span>Барана вредност</span><strong>'.View::money($metrics['claimed']??0).'</strong></div></div></section><form method="get" class="filter-bar"><label>Пребарај<input name="q" value="'.View::e($q).'" placeholder="Број, странка, суд, набавка, шифра..."></label><label>Статус<select name="status">'.$this->legalOptions([''=>'Сите','new'=>'Нов','active'=>'Активни','suspended'=>'Запрен','closed'=>'Затворен','archived'=>'Архивиран'],$status).'</select></label><label>Фаза<select name="phase">'.$this->legalOptions([''=>'Сите','first_instance'=>'Прв степен','appeal'=>'Жалба','revision'=>'Ревизија','retrial'=>'Повторно судење','enforcement'=>'Извршување'],$phase).'</select></label><button class="primary">Филтрирај</button></form><section class="card"><div class="table-wrap"><table><thead><tr><th>Внатрешен бр.</th><th>Предмет</th><th>Сектор</th><th>Фаза / статус</th><th>Одговорно лице</th><th>Набавка / буџет</th><th>Износи</th><th>Рокови</th></tr></thead><tbody>'.$table.'</tbody></table></div>'.$this->pager().'</section>';
        $this->view->render('Правна служба',$body);
    }

