        $documents=$this->db->all("SELECT id,title,document_type,document_date,classification,original_name,scan_status,version,created_at FROM attachments WHERE entity_type='AdministrativeCase' AND entity_id=:id ORDER BY id DESC",['id'=>$id]);
        $executions=$this->db->all('SELECT ee.id,ee.document_date,ee.journal_voucher_number,ee.beneficiary,ee.net_amount,ee.classification_status,bl.code budget_code FROM enforcement_executions ee JOIN budget_lines bl ON bl.id=ee.budget_line_id WHERE ee.administrative_case_id=:id ORDER BY ee.document_date DESC,ee.id DESC',['id'=>$id]);
        $assignments=$this->db->all('SELECT a.valid_from,a.valid_to,a.reason,u.name responsible,du.name deputy,au.name assigned_by FROM legal_case_assignments a JOIN users u ON u.id=a.responsible_user_id LEFT JOIN users du ON du.id=a.deputy_user_id JOIN users au ON au.id=a.assigned_by WHERE a.case_id=:id ORDER BY a.id DESC',['id'=>$id]);
        $info=[['Област'=>'Внатрешен број','Вредност'=>'ZL-'.str_pad((string)$case['internal_sequence'],6,'0',STR_PAD_LEFT)],['Област'=>'GUID','Вредност'=>$case['case_uuid']],['Област'=>'Надворешна референца','Вредност'=>$case['external_reference']],['Област'=>'Архивски број','Вредност'=>$case['protocol_number']],['Област'=>'Суд / орган','Вредност'=>$case['authority_name']],['Област'=>'Судски број','Вредност'=>$case['court_reference']],['Област'=>'Сектор','Вредност'=>$case['directorate_code'].' · '.$case['directorate_name']],['Област'=>'Одговорно лице / заменик','Вредност'=>($case['responsible']?:'—').' / '.($case['deputy']?:'—')],['Област'=>'Набавка / договор','Вредност'=>trim(($case['procurement_code']??'').' '.($case['contract_code']??''))],['Област'=>'Буџетска шифра','Вредност'=>trim(($case['budget_code']??'').' '.($case['budget_name']??''))],['Област'=>'Барано / признато / реализирано','Вредност'=>View::money($case['claimed_amount']??0).' / '.View::money($case['recognized_amount']??0).' / '.View::money($case['realized_amount']??0)]];
