<input name="cost_amount" value="0"></label><label>Реализирано<input name="realized_amount" value="0"></label><label>Јавни набавки<select name="procurement_project_id"><option value="">Без врска</option>'.$this->legalProcurementOptions().'</select></label><label>Буџетска ставка<select name="budget_line_id"><option value="">Без врска</option>'.$this->legalBudgetOptions().'</select></label><label class="wide">Исход<textarea name="outcome" maxlength="2000"></textarea></label><button class="primary">Додај постапка</button></form>';}$body.='</section>';
        $procedureOptions='<option value="">Без постапка</option>';foreach($procedures as$p)$procedureOptions.='<option value="'.(int)$p['id'].'">'.View::e('#'.$p['id'].' · '.$p['procedure_type'].' · '.$p['external_reference']).'</option>';
        $body.='<section class="card"><h2>Рочишта</h2>'.$this->simpleTable($hearings);if($work){foreach($hearings as$h)$body.='<form method="post" action="/legal-office/cases/'.$id.'/hearings/'.(int)$h['id'].'/status" class="form-grid compact">'.$this->view->csrf().'<strong>Рочиште #'.(int)$h['id'].'</strong><label>Статус<select name="status">'.$this->legalOptions(['scheduled'=>'Планирано','held'=>'Одржано','postponed'=>'Одложено','cancelled'=>'Откажано'],(string)$h['status']).'</select></label><label>Белешка<textarea name="notes" maxlength="2000"></textarea></label><button>Зачувај го статусот</button></form>';$body.='<form method="post" action="/legal-office/cases/'.$id.'/hearings" class="form-grid">'.$this->view->csrf().'<label>Постапка<select name="procedure_id">'.$procedureOptions.'</select></label><label>Датум и час<input type="datetime-local" name="scheduled_at" required></label><label>Суд/орган<input name="authority_name" maxlength="250" required></label><label>Место/начин<input name="venue_mode" maxlength="250"></label><label>Одговорно лице<select name="responsible_user_id"><option value="">Неопределено</option>'.$this->legalStaffOptions().'</select></label><label>Статус<select name="status">'.$this->legalOptions(['scheduled'=>'Планирано','held'=>'Одржано','postponed'=>'Одложено','cancelled'=>'Откажано'],'').'</select></label><label class="wide">Белешки<textarea name="notes" maxlength="2000"></textarea></label><button class="primary">Додај рочиште</button></form>';}$body.='</section>';
        $body.='<section class="card"><h2>Рокови</h2>'.$this->simpleTable($deadlines);if($work){foreach($deadlines as$t)$body.='<form method="post" action="/legal-office/cases/'.$id.'/deadlines/'.(int)$t['id'].'/status" class="form-grid compact">'.$this->view->csrf().'<strong>Рок #'.(int)$t['id'].'</strong><label>Статус<select name="status">'.$this->legalOptions(['open'=>'Отворен','in_progress'=>'Во работа','blocked'=>'Блокиран','completed'=>'Завршен'],(string)$t['status']).'</select></label><label>Документирачка белешка<textarea name="completion_note" maxlength="2000"></textarea></label><button>Зачувај го статусот</button></form>';$body.='<form method="post" action="/legal-office/cases/'.$id.'/deadlines" class="form-grid">'.$this->view->csrf().'<label>Дејство<input name="title" maxlength="250" required></label><label>Одговорно лице<select name="assigned_to" required>'.$this->legalStaffOptions().'</select></label><label>Почетен датум<input type="date" name="starts_at"></label><label>Потврден рок<input type="date" name="due_at" required></label><label class="wide">Правна основа<textarea name="legal_basis" maxlength="1000" required></textarea></label><button class="primary">Додај рок</button></form>';}$body.='</section>';
        $body.='<section class="card"><h2>Документи</h2>'.$this->simpleTable($documents);if($work)$body.='<form method="post" action="/attachments" enctype="multipart/form-data" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="entity_type" value="case"><input type="hidden" name="entity_id" value="'.$id.'">'.EvidenceUi::documentFields(['court_document','ruling','legal_opinion','enforcement_decision','decision','correspondence','other']).EvidenceUi::classificationField().EvidenceUi::dropzone('files[]',true,true,'Можете да изберете повеќе датотеки одеднаш · до '.$this->effectiveUploadMb().' MB').'<button class="primary">Прикачи го документот</button></form>';$body.='</section>';
