    /** SQL predicate enforcing legal file confidentiality (same rule as EvidenceAccess::caseFile). */
    private function legalConfidentialityFilter(string $alias,array &$params): string
    {
        $user=$this->userId();
        if($this->scope->canManageLegalOffice($user))return'1=1';
        $params['confidential_user_a']=$user;$params['confidential_user_b']=$user;
        $restricted="({$alias}.confidentiality<>N'restricted' OR {$alias}.responsible_user_id=:confidential_user_a OR {$alias}.deputy_user_id=:confidential_user_b)";
        return $this->scope->canWorkLegalOffice($user)?$restricted:"({$alias}.confidentiality=N'internal' OR {$alias}.responsible_user_id=:confidential_user_a OR {$alias}.deputy_user_id=:confidential_user_b)";
    }

    public function legalOfficeReport(bool $xlsx=false): never
    {
        $confidentialParams=[];$visible=$this->legalConfidentialityFilter('c',$confidentialParams);
        $registry=$this->db->all("SELECT c.internal_sequence,c.case_number,c.external_reference,c.case_type,c.subject,d.code directorate,c.authority_name,c.court_reference,c.procedural_phase,c.status,u.name responsible,c.financial_direction,c.claimed_amount,c.recognized_amount,c.realized_amount,c.currency,CONVERT(varchar(10),c.opened_at,23) opened_at FROM administrative_cases c JOIN directorates d ON d.id=c.originating_directorate_id LEFT JOIN users u ON u.id=c.responsible_user_id WHERE c.is_legal=1 AND {$visible} ORDER BY c.internal_sequence",$confidentialParams);
        $deadlines=$this->db->all("SELECT c.case_number,c.subject,t.title,u.name responsible,t.starts_at,t.due_at,t.status,t.legal_basis,CASE WHEN t.status<>'completed' AND t.due_at<CONVERT(date,SYSUTCDATETIME()) THEN N'Изминат' WHEN t.due_at<=DATEADD(day,7,CONVERT(date,SYSUTCDATETIME())) THEN N'Во рок од 7 дена' WHEN t.due_at<=DATEADD(day,30,CONVERT(date,SYSUTCDATETIME())) THEN N'Во рок од 30 дена' ELSE N'Подоцна' END urgency FROM case_tasks t JOIN administrative_cases c ON c.id=t.case_id LEFT JOIN users u ON u.id=t.assigned_to WHERE c.is_legal=1 AND t.task_type='deadline' AND {$visible} ORDER BY t.due_at",$confidentialParams);
        $financial=$this->db->all("SELECT c.case_number,c.subject,c.financial_direction,c.claimed_amount,c.recognized_amount,c.realized_amount,COALESCE(c.recognized_amount,c.claimed_amount,0)-COALESCE(c.realized_amount,0) remaining,c.currency,pp.procurement_code,pp.contract_code,bl.code budget_code FROM administrative_cases c LEFT JOIN procurement_projects pp ON pp.id=c.procurement_project_id LEFT JOIN budget_lines bl ON bl.id=c.budget_line_id WHERE c.is_legal=1 AND {$visible} ORDER BY c.case_number",$confidentialParams);
        if($xlsx)(new TabularExport())->xlsx('raporti-zyra-ligjore-'.date('Y-m-d'),[['name'=>'Регистар','headers'=>$this->headersFromRows($registry),'rows'=>$registry],['name'=>'Рокови','headers'=>$this->headersFromRows($deadlines),'rows'=>$deadlines],['name'=>'Финансиска состојба','headers'=>$this->headersFromRows($financial),'rows'=>$financial]]);
        $body='<p><a class="button button-secondary" href="/legal-office">Назад</a> <a class="button primary" href="/legal-office/reports.xlsx">Извези во Excel</a></p><p class="muted">За PDF користете ја функцијата Печати на прелистувачот.</p><section class="card"><h2>Регистар на предмети</h2>'.$this->simpleTable($registry).'</section><section class="card"><h2>Рокови</h2>'.$this->simpleTable($deadlines).'</section><section class="card"><h2>Состојба за наплата/плаќање</h2>'.$this->simpleTable($financial).'</section>';
        $this->view->render('Извештаи на Правната служба',$body);
    }

