ect></label><label>Финансиска насока<select name="financial_direction"><option value="">Без насока</option>'.$this->legalOptions(['receivable'=>'За наплата од Општината','payable'=>'За плаќање од Општината'],(string)($row['financial_direction']??'')).'</select></label><label>Барана сума<input name="claimed_amount" value="'.$v('claimed_amount').'" placeholder="0.00"></label><label>Призната сума<input name="recognized_amount" value="'.$v('recognized_amount').'" placeholder="0.00"></label><label>Реализирана сума<input name="realized_amount" value="'.$v('realized_amount').'" placeholder="0.00"></label><label>Доверливост<select name="confidentiality">'.$this->legalOptions(['internal'=>'Internal','confidential'=>'Доверливо','restricted'=>'Ограничен'],(string)($row['confidentiality']??'internal')).'</select></label><label class="wide">Исход<textarea name="outcome" maxlength="2000">'.$v('outcome').'</textarea></label>';
