    public function caseView(int $id): never
    {
        $case=$this->db->one('SELECT c.*,LOWER(sys.fn_varbintohexstr(CONVERT(varbinary(8),c.row_version))) row_version_token,d.name originating_directorate,u.name responsible_user FROM administrative_cases c JOIN directorates d ON d.id=c.originating_directorate_id LEFT JOIN users u ON u.id=c.responsible_user_id WHERE c.id=:id',['id'=>$id]);if(!$case)throw new HttpException(404,'Предметот не е пронајден.');
        (new EvidenceAccess($this->db,$this->scope,$this->userId()))->caseFile($id);
        $dirs=$this->db->all('SELECT cd.*,d.code,d.name,u.name responsible FROM case_directorates cd JOIN directorates d ON d.id=cd.directorate_id LEFT JOIN users u ON u.id=cd.responsible_user_id WHERE cd.case_id=:id ORDER BY cd.id',['id'=>$id]);$tasks=$this->db->all('SELECT t.*,u.name assigned FROM case_tasks t LEFT JOIN users u ON u.id=t.assigned_to WHERE t.case_id=:id ORDER BY t.due_at,t.id',['id'=>$id]);$actions=$this->db->all('SELECT ca.*,u.name performed FROM case_actions ca JOIN users u ON u.id=ca.performed_by WHERE ca.case_id=:id ORDER BY ca.action_date DESC,ca.id DESC',['id'=>$id]);
        $acts=$this->db->all('SELECT id,act_number,act_type,act_date,effective_date,status,description,latitude,longitude,google_maps_url FROM administrative_acts WHERE case_id=:id ORDER BY act_date,id',['id'=>$id]);$caseAttachments=$this->db->all("SELECT id,original_name,mime_type,scan_status,document_type,title FROM attachments WHERE entity_type='AdministrativeCase' AND entity_id=:id ORDER BY id DESC",['id'=>$id]);$forwarding=$this->caseForwardingSection($case);
        $roles=$this->scope->roles($this->userId());$canAgenda=array_intersect(['mayor','director'],$roles)!==[]&&$this->scope->canManageMayorAgenda($this->userId(),(int)$case['originating_directorate_id']);
        $agendaForm='';if($canAgenda){$inAgenda=(bool)$this->db->scalar("SELECT TOP 1 1 FROM mayor_agenda_items WHERE item_type='case' AND case_id=:id AND status='open'",['id'=>$id]);$agendaForm='<section class="card"><h2>Агенда на Градоначалникот</h2><form method="post" action="/cases/'.$id.'/mayor-agenda">'.$this->view->csrf().'<input type="hidden" name="action" value="'.($inAgenda?'remove':'add').'"><button class="button '.($inAgenda?'button-secondary':'primary').'">'.($inAgenda?'Отстрани од тековната агенда':'Избери за агендата на Градоначалникот').'</button></form></section>';}
        if($this->scope->isMayor($this->userId())){$body='<section class="card"><h2>'.View::e($case['case_number'].' · '.$case['subject']).'</h2><p>'.View::e($case['description']).'</p><p>Статус: <strong>'.View::e($case['status']).'</strong> · Приоритет: <strong>'.View::e($case['priority']).'</strong> · Отворен на '.View::e($case['opened_at']).'</p></section>'.$agendaForm.'<section class="card"><h2>Вклучени сектори</h2>'.$this->simpleTable($dirs).'</section>'.$forwarding.'<section class="card"><h2>Документи</h2>'.$this->simpleTable($caseAttachments).'</section><section class="card"><h2>Управни акти</h2>'.$this->simpleTable($acts).'</section><section class="card"><h2>Задачи по предметот</h2>'.$this->simpleTable($tasks).'</section><section class="card"><h2>Хронологија</h2>'.$this->simpleTable($actions).'</section>';$this->view->render('Предмет '.$case['case_number'],$body);}
        $body='<section class="card"><h2>'.View::e($case['case_number'].' · '.$case['subject']).'</h2><p>'.View::e($case['description']).'</p><p>Статус: <strong>'.View::e($case['status']).'</strong> · Приоритет: <strong>'.View::e($case['priority']).'</strong> · Отворен на '.View::e($case['opened_at']).'</p></section><section class="card"><h2>Вклучени сектори</h2>'.$this->simpleTable($dirs).'<form method="post" action="/cases/'.$id.'/directorates" class="form-grid">'.$this->view->csrf().'<label>Сектор<select name="directorate_id" required>'.$this->directorateOptions(true).'</select></label><label>Врска<select name="relationship_type"><option>RELATED</option><option>ACTION_REQUIRED</option><option>INFORMED</option><option>REVIEWER</option><option>EXECUTOR</option></select></label><label>Рок<input type="date" name="due_at"></label><button class="primary">Сподели со секторот</button></form></section>'.$forwarding.'<section class="card"><h2>Документи</h2>'.$this->simpleTable($caseAttachments).'<form method="post" action="/attachments" enctype="multipart/form-data" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="entity_type" value="case"><input type="hidden" name="entity_id" value="'.$id.'">'.EvidenceUi::documentFields().EvidenceUi::classificationField().EvidenceUi::dropzone('files[]',true,true,'Можете да изберете повеќе датотеки одеднаш · до '.$this->effectiveUploadMb().' MB').'<button class="primary">Прикачи документи</button></form></section><section class="card"><h2>Управни акти</h2>'.$this->simpleTable($acts).'<form method="post" action="/cases/'.$id.'/acts" class="form-grid">'.$this->view->csrf().'<label>Број на актот<input name="act_number" maxlength="100" required></label><label>Вид<input name="act_type" maxlength="60" required></label><label>Датум<input type="date" name="act_date" required></label><label>Датум на влегување во сила<input type="date" name="effective_date"></label><label>Скениран документ (ID)<input type="number" min="1" name="attachment_id"></label><label>Претходен акт (ID, опционално)<input type="number" min="1" name="parent_act_id"></label><label>Врска<select name="relation_type"><option value="amends">Менува</option><option value="replaces">Заменува</option><option value="revokes">Укинува</option><option value="implements">Спроведува</option></select></label>'.EvidenceUi::geo().'<label class="wide">Опис<textarea name="description" required></textarea></label><button class="primary">Евидентирај го актот</button></form></section><section class="card"><h2>Задачи по предметот</h2>'.$this->simpleTable($tasks).'<form method="post" action="/cases/'.$id.'/tasks" class="form-grid">'.$this->view->csrf().'<label>Наслов<input name="title" maxlength="250" required></label><label>Одговорно лице<input type="number" name="assigned_to" min="1"></label><label>Рок<input type="date" name="due_at" required></label><label>Матична задача (опционално)<input type="number" min="1" name="parent_task_id"></label><label class="wide">Опис<textarea name="description"></textarea></label><button class="primary">Додај задача</button></form></section><section class="card"><h2>Хронологија</h2>'.$this->simpleTable($actions).'<form method="post" action="/cases/'.$id.'/actions" class="form-grid">'.$this->view->csrf().'<label>Вид<input name="action_type" maxlength="50" required></label><label>Нов статус<input name="new_status" maxlength="30"></label><label class="wide">Што се случи?<textarea name="description" required></textarea></label><button class="primary">Евидентирај го дејството</button></form></section>';
        $body=preg_replace('#</section>#',$this->caseEditSection($case).'</section>',$body,1)??$body;
        $body=$agendaForm.$body;$body.=EvidenceUi::extras($this->db,$this->scope,$this->userId(),$this->view,'AdministrativeCase',$id);$this->view->render('Предмет '.$case['case_number'],$body);
    }

    /** Case statuses shown in the edit form (closed and archived set the closing date). */
    private const CASE_STATUSES=['open'=>'Отворен','in_progress'=>'Во обработка','suspended'=>'Запрен','closed'=>'Затворен','archived'=>'Архивиран'];

    /** Collapsible edit form of an administrative case, for those who may write to it (not the Mayor: read only). */
    private function caseEditSection(array $case): string
    {
        if((bool)($case['is_legal']??false))return $this->scope->canAccessLegalOffice($this->userId())?'<p class="muted">Ова е предмет на Правната служба; се уредува во <a href="/legal-office/cases/'.(int)$case['id'].'">правно досие</a>.</p>':'';
        try{(new EvidenceAccess($this->db,$this->scope,$this->userId()))->caseFile((int)$case['id'],true);}catch(HttpException){return '';}
        if(!$this->scope->can($this->userId(),'create','case'))return '';
        $id=(int)$case['id'];$v=static fn(string$key):string=>View::e($case[$key]??'');
        $statuses='';foreach(self::CASE_STATUSES as$value=>$label)$statuses.='<option value="'.$value.'"'.((string)$case['status']===$value?' selected':'').'>'.View::e($label).'</option>';
        if(!isset(self::CASE_STATUSES[(string)$case['status']]))$statuses='<option value="'.$v('status').'" selected>'.$v('status').'</option>'.$statuses;
        $priorities='';foreach(['normal'=>'Normal','high'=>'Висок','critical'=>'Критичен'] as$value=>$label)$priorities.='<option value="'.$value.'"'.((string)$case['priority']===$value?' selected':'').'>'.$label.'</option>';
        return '<details class="case-edit"><summary class="button button-secondary">Уреди го предметот</summary><form method="post" action="/cases/'.$id.'/update" class="form-grid">'.$this->view->csrf()
            .'<input type="hidden" name="row_version" value="'.$v('row_version_token').'">'
            .'<label>Број на предмет<input name="case_number" maxlength="80" required value="'.$v('case_number').'"></label>'
            .'<label>Вид<input name="case_type" maxlength="80" required value="'.$v('case_type').'"></label>'
            .'<label>Статус<select name="status" required>'.$statuses.'</select></label>'
            .'<label>Приоритет<select name="priority" required>'.$priorities.'</select></label>'
            .'<label class="wide">Субјект<input name="subject" maxlength="250" required value="'.$v('subject').'"></label>'
            .'<label class="wide">Опис<textarea name="description" maxlength="20000">'.$v('description').'</textarea></label>'
            .'<label class="wide">Причина за промената<textarea name="reason" maxlength="1000" required></textarea></label>'
            .'<div class="form-actions"><button class="primary">Зачувај ги промените</button></div></form></details>';
    }

    /**
     * Forwardings of an administrative case with a cover letter (aktpërcjellës): history, receipt confirmation for the
     * receiving directorate, and the form for those who hold the case in one of their directorates.
     */
    private function caseForwardingSection(array $case): string
    {
        $id=(int)$case['id'];
        $rows=$this->db->all("SELECT f.id,f.cover_letter_number,CONVERT(varchar(10),f.forwarded_on,23) forwarded_on,f.reason,f.attachment_id,f.status,f.to_directorate_id,fd.code from_code,fd.name from_name,td.code to_code,td.name to_name,u.name forwarded_by,ru.name received_by,CONVERT(varchar(16),f.received_at,120) received_at FROM case_forwardings f JOIN directorates fd ON fd.id=f.from_directorate_id JOIN directorates td ON td.id=f.to_directorate_id JOIN users u ON u.id=f.forwarded_by LEFT JOIN users ru ON ru.id=f.received_by WHERE f.case_id=:id ORDER BY f.forwarded_at DESC,f.id DESC",['id'=>$id]);
        $mayor=$this->scope->isMayor($this->userId());
        $table='';
        foreach($this->pageOf($rows,'forwardings') as$r){
            $received=$r['status']==='received';
            $action=!$received&&!$mayor&&$this->scope->allowsDirectorate($this->userId(),(int)$r['to_directorate_id'])?'<form method="post" action="/cases/'.$id.'/forwardings/'.(int)$r['id'].'/receive">'.$this->view->csrf().'<button class="button button-secondary">Потврди го приемот</button></form>':'';
            $letter=$r['attachment_id']?' · <a href="/attachments/'.(int)$r['attachment_id'].'">пропратниот акт</a>':'';
            $table.='<tr><td>'.View::e($r['forwarded_on']).'</td><td><strong>'.View::e($r['cover_letter_number']).'</strong>'.$letter.'</td><td>'.View::e($r['from_code']).' → <strong>'.View::e($r['to_code']).'</strong><br><small>'.View::e($r['to_name']).'</small></td><td>'.View::e($r['reason']??'').'</td><td>'.View::e($r['forwarded_by']).'</td><td>'.($received?'<span class="status-badge status-active">Примени</span><br><small>'.View::e(($r['received_by']??'').' · '.($r['received_at']??'')).'</small>':'<span class="status-badge status-draft">Чека прием</span>').$action.'</td></tr>';
        }
        $html='<section class="card" id="forwarding"><h2>Препраќање со пропратен акт</h2>';
        $html.=$rows?'<div class="table-wrap"><table><thead><tr><th>Датум</th><th>Пропратен акт бр.</th><th>Од → до</th><th>Причина</th><th>Препратил</th><th>Прием</th></tr></thead><tbody>'.$table.'</tbody></table></div>'.$this->pager('forwardings'):'<p class="muted">Предметот не е препратен до други сектори.</p>';
        if(!$mayor&&!(bool)($case['is_legal']??false)&&$this->scope->can($this->userId(),'create','case')){
            $held=array_map('intval',array_column($this->db->all('SELECT directorate_id FROM case_directorates WHERE case_id=:c',['c'=>$id]),'directorate_id'));$held[]=(int)$case['originating_directorate_id'];
            $own=array_values(array_filter(array_unique($held),fn(int $d): bool => $this->scope->allowsDirectorate($this->userId(),$d)));
            if($own){
                $marks=[];$params=[];foreach($own as$i=>$d){$marks[]=':d'.$i;$params['d'.$i]=$d;}
                $fromOptions='';foreach($this->db->all('SELECT id,code,name FROM directorates WHERE id IN ('.implode(',',$marks).') ORDER BY name',$params)as$d)$fromOptions.='<option value="'.(int)$d['id'].'"'.((int)$d['id']===(int)$case['originating_directorate_id']?' selected':'').'>'.View::e($d['code'].' · '.$d['name']).'</option>';
                $toOptions='<option value="">Изберете сектор што прима</option>';foreach($this->db->all('SELECT id,code,name FROM directorates WHERE active=1 ORDER BY name')as$d)$toOptions.='<option value="'.(int)$d['id'].'">'.View::e($d['code'].' · '.$d['name']).'</option>';
                $html.='<h3>Препрати до друг сектор</h3><p class="muted">Секторот што прима добива пристап до предметот, а неговиот раководител се известува. Препраќањата автоматски се бројат во неделниот извештај за услугите.</p><form method="post" action="/cases/'.$id.'/forward" enctype="multipart/form-data" class="form-grid">'.$this->view->csrf().'<label>Од секторот<select name="from_directorate_id" required>'.$fromOptions.'</select></label><label>До секторот<select name="to_directorate_id" required>'.$toOptions.'</select></label><label>Пропратен акт бр.<input name="cover_letter_number" maxlength="100" required></label><label>Датум на препраќање<input type="date" name="forwarded_on" value="'.date('Y-m-d').'" required></label><label class="wide">Причина / белешка<textarea name="reason" maxlength="2000"></textarea></label>'.EvidenceUi::dropzone('cover_letter',false,false,'Опционално · до '.$this->effectiveUploadMb().' MB','Скениран пропратен акт').'<button class="primary">Препрати го предметот</button></form>';
            }
        }
        return$html.'</section>';
    }

    private function directorateOptions(bool $all=false): string { [$where,$params]=$this->scope->sql($this->userId(),'id','caseDir');$rows=$this->db->all('SELECT id,code,name FROM directorates WHERE active=1'.($all?'':' AND '.$where).' ORDER BY name',$all?[]:$params);$html='';foreach($rows as$row)$html.='<option value="'.(int)$row['id'].'">'.View::e($row['code'].' · '.$row['name']).'</option>';return$html; }

    public function taskEdit(int $projectId,int $taskId): never
    {
        $project=$this->find('projects',$projectId);if(!$this->scope->allowsDirectorate($this->userId(),(int)$project['directorate_id']))throw new HttpException(403,'Надвор од вашиот опсег.');$task=$this->db->one('SELECT *,LOWER(sys.fn_varbintohexstr(CONVERT(varbinary(8),row_version))) row_version_token FROM project_tasks WHERE id=:id AND project_id=:project',['id'=>$taskId,'project'=>$projectId]);if(!$task)throw new HttpException(404,'Задачата не е пронајдена.');
        $owners=$this->db->all("SELECT DISTINCT u.id,u.name,u.username FROM users u JOIN user_role_scopes urs ON urs.user_id=u.id JOIN roles r ON r.id=urs.role_id WHERE u.status='active' AND (urs.directorate_id=:d OR COALESCE(r.base_role_code,r.code) IN ('mayor','mayor_admin','finance','system_admin')) AND (urs.valid_from IS NULL OR urs.valid_from<=SYSUTCDATETIME()) AND (urs.valid_to IS NULL OR urs.valid_to>=SYSUTCDATETIME()) ORDER BY u.name",['d'=>(int)$project['directorate_id']]);$ownerOptions='<option value="">Без одговорно лице</option>';foreach($owners as$owner)$ownerOptions.='<option value="'.(int)$owner['id'].'"'.((int)$task['owner_id']===(int)$owner['id']?' selected':'').'>'.View::e($owner['name'].' · @'.$owner['username']).'</option>';
        $statusOptions='';foreach(['not_started'=>'Не е започната','in_progress'=>'Во реализација','blocked'=>'Блокирано','done'=>'Завршена','cancelled'=>'Откажано']as$value=>$label)$statusOptions.='<option value="'.$value.'"'.($task['status']===$value?' selected':'').'>'.$label.'</option>';
        $body='<section class="card"><form method="post" action="/projects/'.$projectId.'/tasks/'.$taskId.'" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="row_version" value="'.View::e($task['row_version_token']).'"><label>Наслов<input name="title" maxlength="250" value="'.View::e($task['title']).'" required></label><label>Одговорно лице<select name="owner_id">'.$ownerOptions.'</select></label><label>Датум на почеток<input type="date" name="starts_at" value="'.View::e($task['starts_at']).'"></label><label>Рок<input type="date" name="due_at" value="'.View::e($task['due_at']).'"></label><label>Тежина во проектот (%)<input name="weight_percent" type="number" min="0" max="100" step="0.01" value="'.View::e($task['weight_percent']).'" required></label><label>Напредок (%)<input name="progress" type="number" min="0" max="100" value="'.(int)$task['progress'].'" required></label><label>Статус<select name="status">'.$statusOptions.'</select></label><label class="wide">Следен чекор<textarea name="next_step" maxlength="5000">'.View::e($task['next_step']).'</textarea></label><label class="wide">Зависности / белешки<textarea name="dependency_notes" maxlength="5000">'.View::e($task['dependency_notes']).'</textarea></label><div><button class="primary">Зачувај ја задачата</button> <a class="button button-secondary" href="/projects/'.$projectId.'">Откажи</a></div></form></section>';
        $this->view->render('Уредување на задачата',$body);
    }

    public function projectEdit(int $id): never
    {
        $project=$this->db->one('SELECT p.id,p.directorate_id,p.code,p.name,p.manager_id,p.objective,p.location_name,p.address,p.latitude,p.longitude,p.google_maps_url,CONVERT(varchar(10),p.starts_at,23) starts_at,CONVERT(varchar(10),p.ends_at,23) ends_at,p.status,p.has_budget_impact,p.budget_category,p.progress,LOWER(sys.fn_varbintohexstr(CONVERT(varbinary(8),p.row_version))) row_version_token,d.name directorate FROM projects p JOIN directorates d ON d.id=p.directorate_id WHERE p.id=:id',['id'=>$id]);
        if(!$project)throw new HttpException(404,'Проектот не е пронајден.');
        (new EvidenceAccess($this->db,$this->scope,$this->userId()))->project($id,true);
        $managers=$this->db->all("SELECT DISTINCT u.id,u.name,u.username FROM users u LEFT JOIN user_role_scopes urs ON urs.user_id=u.id LEFT JOIN roles r ON r.id=urs.role_id WHERE u.status='active' AND (u.id=:current_manager OR (r.code IN ('mayor','mayor_admin','deputy_mayor','director','directors_assistant','project_manager','system_admin') AND (urs.directorate_id=:d OR COALESCE(r.base_role_code,r.code) IN ('mayor','mayor_admin','system_admin')) AND (urs.valid_from IS NULL OR urs.valid_from<=SYSUTCDATETIME()) AND (urs.valid_to IS NULL OR urs.valid_to>=SYSUTCDATETIME()))) ORDER BY u.name",['d'=>(int)$project['directorate_id'],'current_manager'=>$project['manager_id']!==null?(int)$project['manager_id']:0]);
        $managerOptions='';foreach($managers as$manager)$managerOptions.='<option value="'.(int)$manager['id'].'"'.((int)$project['manager_id']===(int)$manager['id']?' selected':'').'>'.View::e($manager['name'].' · @'.$manager['username']).'</option>';
        $statuses=['draft'=>'Нацрт','active'=>'Активно','on_hold'=>'На чекање','completed'=>'Завршена','cancelled'=>'Откажано'];if(!isset($statuses[$project['status']]))$statuses[$project['status']]=(string)$project['status'];$statusOptions='';foreach($statuses as$value=>$label)$statusOptions.='<option value="'.View::e($value).'"'.($project['status']===$value?' selected':'').'>'.View::e($label).'</option>';
        $body=$this->projectActionHeader($project).$this->projectActions($project).'<section class="card"><p class="muted">Секторот и напредокот не се менуваат тука. Напредокот се ажурира само со нов извештај.</p><form method="post" action="/projects/'.$id.'" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="row_version" value="'.View::e($project['row_version_token']).'"><label>Сектор<input value="'.View::e($project['directorate']).'" disabled></label><label>Шифра<input name="code" maxlength="50" value="'.View::e($project['code']).'" required></label><label>Назив<input name="name" maxlength="250" value="'.View::e($project['name']).'" required></label><label>Статус<select name="status" required>'.$statusOptions.'</select></label><label>Носител / одговорно лице<select name="manager_id" required>'.$managerOptions.'</select></label><label>Почеток<input type="date" name="starts_at" value="'.View::e($project['starts_at']).'"></label><label>Завршување<input type="date" name="ends_at" value="'.View::e($project['ends_at']).'"></label><label>Локација<input name="location_name" maxlength="250" value="'.View::e($project['location_name']).'"></label><label>Адреса<input name="address" maxlength="500" value="'.View::e($project['address']).'"></label>'.EvidenceUi::geo($project).'<label class="wide">Цел<textarea name="objective" maxlength="10000">'.View::e($project['objective']).'</textarea></label><label><input type="checkbox" name="has_budget_impact" value="1"'.((bool)$project['has_budget_impact']?' checked':'').'> Има буџетско влијание</label>'.'<label>Буџетска категорија на проектот<select name="budget_category" required>'.$this->budgetCategoryOptions((string)($project['budget_category']??'capital_investments')).'</select><small class="muted">Проектот се поврзува само со буџетски ставки од оваа категорија, дури и кога ставката е на друг сектор.</small></label>'.'<div><button class="primary">Зачувај ги промените</button> <a class="button button-secondary" href="/projects/'.$id.'">Откажи</a></div></form></section>';
        $this->view->render('Уредување на проектот',$body);
    }

    public function liveReports(): never
    {
        $after=max(0,$this->request->integer('after')); [$where,$params]=$this->scope->sql($this->userId(),'p.directorate_id','live'); $params['after']=$after;
        $rows=$this->db->all("SELECT TOP 50 pu.id,pu.project_id,p.code project_code,p.name project_name,d.code directorate,pu.progress,pu.narrative,pu.blockers,pu.next_step,u.name author,CONVERT(varchar(10),pu.period,23) period,CONVERT(varchar(33),pu.created_at,127) created_at FROM progress_updates pu JOIN projects p ON p.id=pu.project_id JOIN directorates d ON d.id=p.directorate_id JOIN users u ON u.id=pu.created_by WHERE pu.id>:after AND {$where} ORDER BY pu.id",$params);
        foreach($rows as &$row)$row['url']='/projects/'.(int)$row['project_id'];
        $this->json(['data'=>$rows,'last_id'=>(int)($rows[count($rows)-1]['id']??$after),'server_time'=>gmdate('c')]);
    }

    public function budget(): never
    {
        [$where,$params]=$this->scope->budgetLineSql($this->userId(),'bl','report','b');
        if(($year=$this->request->integer('year'))>0){$where.=' AND ba.fiscal_year=:year';$params['year']=$year;}
        $rows=$this->pagedQuery("SELECT ba.id,ba.fiscal_year,ba.period,bl.code line_code,bl.name line_name,d.name directorate,p.name project,ba.planned_amount,ba.current_amount,ba.forecast_amount,COALESCE((SELECT SUM(r.amount) FROM reservations r WHERE r.budget_allocation_id=ba.id AND r.status='active'),0) reserved,COALESCE((SELECT SUM(c.amount) FROM commitments c WHERE c.budget_allocation_id=ba.id AND c.status='active'),0) committed,COALESCE((SELECT SUM(e.amount) FROM expenditures e WHERE e.budget_allocation_id=ba.id),0) spent FROM budget_allocations ba JOIN budget_lines bl ON bl.id=ba.budget_line_id JOIN directorates d ON d.id=bl.directorate_id LEFT JOIN projects p ON p.id=ba.project_id WHERE {$where} ORDER BY ba.fiscal_year DESC,bl.code",$params,'alloc');
        [, $official]=$this->exportData('budget',true);
        $importLink=($this->scope->isMayor($this->userId())?'':'<p><a class="button" href="/imports/annual-budget">Увези го годишниот буџет</a> <a class="button button-secondary" href="/budget/freebalance">Извршување според FreeBalance</a></p>');
        $body=$importLink.'<section class="card"><h2>Буџет одобрен од Советот на општината</h2>'.$this->approvedBudgetTable($official,!$this->scope->isMayor($this->userId())&&$this->scope->can($this->userId(),'create','allocation')).$this->pager().'</section><section class="card"><h2>Распределби по проекти</h2>'.$this->simpleTable($rows,'alloc').'</section>';
        $body=$this->filterBar('budget',['directorate','year','category','q']).$body;
        $this->view->render('Буџет',$body);
    }

    public function financialList(string $type): never
    {
        [$where,$params]=$this->scope->budgetLineSql($this->userId(),'bl','report','financiallist');
        if($type==='allocations'){
            $rows=$this->db->all("SELECT ba.id,ba.fiscal_year,ba.period,d.code directorate,bl.code budget_line,bl.name budget_name,p.code project_code,p.name project,ba.planned_amount,ba.current_amount,ba.forecast_amount FROM budget_allocations ba JOIN budget_lines bl ON bl.id=ba.budget_line_id JOIN directorates d ON d.id=bl.directorate_id LEFT JOIN projects p ON p.id=ba.project_id WHERE {$where} ORDER BY ba.fiscal_year DESC,ba.id DESC",$params);
            $rows=array_map(static fn(array $r): array => $r+['source'=>'e-Kabineti','source_as_of'=>null],$rows);
            foreach($this->freeBalanceLineRows('fbAllocations') as$f)$rows[]=['id'=>null,'fiscal_year'=>$f['fiscal_year'],'period'=>null,'directorate'=>$f['directorate_code'],'budget_line'=>$f['budget_line_code'],'budget_name'=>$f['budget_line'],'project_code'=>$f['project_code'],'project'=>null,'planned_amount'=>null,'current_amount'=>$f['allocated'],'forecast_amount'=>null,'source'=>'Import FreeBalance','source_as_of'=>$f['as_of']];
            $title='Табела на распределби';
        }elseif($type==='commitments'){
            $rows=$this->db->all("SELECT c.id,c.reference,c.supplier,c.amount,CONVERT(varchar(10),c.committed_at,23) committed_at,c.status,d.code directorate,bl.code budget_line,p.code project_code,p.name project FROM commitments c JOIN budget_allocations ba ON ba.id=c.budget_allocation_id JOIN budget_lines bl ON bl.id=ba.budget_line_id JOIN directorates d ON d.id=bl.directorate_id LEFT JOIN projects p ON p.id=ba.project_id WHERE {$where} ORDER BY c.committed_at DESC,c.id DESC",$params);
            $rows=array_map(static fn(array $r): array => $r+['source'=>'e-Kabineti','source_as_of'=>null],$rows);
            foreach($this->freeBalanceLineRows('fbCommitments') as$f)if((float)$f['committed']!=0.0)$rows[]=['id'=>null,'reference'=>null,'supplier'=>null,'amount'=>$f['committed'],'committed_at'=>$f['as_of'],'status'=>'importuar','directorate'=>$f['directorate_code'],'budget_line'=>$f['budget_line_code'],'project_code'=>$f['project_code'],'project'=>null,'source'=>'Import FreeBalance','source_as_of'=>$f['as_of']];
            $title='Табела на преземени обврски';
        }elseif($type==='expenditures'){
            $rows=$this->db->all("SELECT e.id,e.source_reference,e.amount,CONVERT(varchar(10),e.accounting_date,23) accounting_date,d.code directorate,bl.code budget_line,p.code project_code,p.name project,c.reference commitment_reference,CASE WHEN EXISTS (SELECT 1 FROM audit_events ae WHERE ae.action='expenditure.imported' AND ae.entity_id=CONVERT(nvarchar(80),e.id)) THEN 'Import (shpenzime)' ELSE 'e-Kabineti' END source,CAST(NULL AS varchar(10)) source_as_of FROM expenditures e JOIN budget_allocations ba ON ba.id=e.budget_allocation_id JOIN budget_lines bl ON bl.id=ba.budget_line_id JOIN directorates d ON d.id=bl.directorate_id LEFT JOIN projects p ON p.id=ba.project_id LEFT JOIN commitments c ON c.id=e.commitment_id WHERE {$where} ORDER BY e.accounting_date DESC,e.id DESC",$params);
            foreach($this->freeBalanceLineRows('fbExpenditures') as$f)if((float)$f['spent']!=0.0)$rows[]=['id'=>null,'source_reference'=>null,'amount'=>$f['spent'],'accounting_date'=>$f['as_of'],'directorate'=>$f['directorate_code'],'budget_line'=>$f['budget_line_code'],'project_code'=>$f['project_code'],'project'=>null,'commitment_reference'=>null,'source'=>'Import FreeBalance','source_as_of'=>$f['as_of']];
            $title='Листа на расходи';
        }else throw new HttpException(404,'Финансиската листа не е пронајдена.');
        $note='<p class="muted">Извор: <strong>е-Кабинет</strong> = евидентирано во е-Кабинет (проектите); <strong>Import</strong> = од увоз. Ставките без податоци во е-Кабинет ги земаат бројките од увезениот FreeBalance извештај.</p>';
        $this->view->render($title,'<section class="card">'.$note.$this->simpleTable($rows).'</section>');
    }

    /**
     * Budget execution for Finance and the administrator: every row gets a project picker. Allocation rows change the
     * allocation's project; FreeBalance rows link the budget line to the project without changing the imported figures.
     */
    private function executionProjectTable(array $rows): string
    {
        if(!$rows)return'<p class="muted">Нема податоци.</p>';
        $projects=$this->db->all("SELECT p.id,p.code,p.name,d.code directorate_code FROM projects p JOIN directorates d ON d.id=p.directorate_id WHERE p.status NOT IN ('cancelled') ORDER BY p.code,p.name");
        $label=static fn(array $p): string => '#'.$p['id'].' · '.$p['code'].' · '.$p['name'].' · '.$p['directorate_code'];
        $list='<datalist id="execution-projects">';foreach($projects as$p)$list.='<option value="'.View::e($label($p)).'"></option>';$list.='</datalist>';
        $html='<p class="muted">Како Сектор за финансии / Администратор можете да изберете проект за секој ред. Кај распределбите се менува проектот на распределбата; кај редовите „Увоз FreeBalance“ проектот се поврзува со буџетската ставка, а бројките остануваат од FreeBalance. Празното поле ја отстранува врската.</p>'.$list.'<div class="table-wrap"><table><thead><tr><th>Година</th><th>Сектор</th><th>Буџетска ставка</th><th>Проект</th><th>Распределено</th><th>Преземено</th><th>Потрошено</th><th>Слободни</th><th>Извор</th><th>Изберете проект</th></tr></thead><tbody>';
        foreach($rows as$r){
            $isAllocation=$r['allocation_id']!==null;$id=(int)($isAllocation?$r['allocation_id']:($r['budget_line_id']??0));if($id===0)continue;
            $current='';foreach($projects as$p)if((string)$p['code']===(string)($r['project_code']??'')&&(string)$p['name']===(string)($r['project']??'')){$current=$label($p);break;}
            $form='<form method="post" action="/execution/'.($isAllocation?'allocations':'lines').'/'.$id.'/project" class="inline-form">'.$this->view->csrf().'<input name="project" list="execution-projects" value="'.View::e($current).'" placeholder="Пребарај шифра или назив на проект" aria-label="Проект"><button class="button button-secondary">Зачувај</button></form>';
            $html.='<tr><td>'.(int)$r['fiscal_year'].'</td><td>'.View::e($r['directorate_code']).'</td><td><strong>'.View::e($r['budget_line_code']).'</strong><br><small>'.View::e($r['budget_line']).'</small></td><td>'.View::e(trim(($r['project_code']??'').' '.($r['project']??''))?:'—').'</td><td>'.View::money($r['current_amount']).'</td><td>'.View::money($r['committed']).'</td><td>'.View::money($r['spent']).'</td><td>'.View::money($r['available']).'</td><td>'.View::e($r['source']).($r['source_as_of']?'<br><small>'.View::e($r['source_as_of']).'</small>':'').'</td><td>'.$form.'</td></tr>';
        }
        return$html.'</tbody></table></div>';
    }

    /** Only the approved budget table (Budget → Tabela e buxhetit). */
    public function budgetTable(): never
    {
        [, $official]=$this->exportData('budget',true);
        $editable=!$this->scope->isMayor($this->userId())&&$this->scope->can($this->userId(),'create','allocation');
        $body=$this->filterBar('budget',['directorate','year','category','q']).'<section class="card">'.$this->approvedBudgetTable($official,$editable).$this->pager().'</section>';
        $this->view->render('Табела на буџетот',$body);
    }

    /** Budget lines whose figures come from the imported FreeBalance report (no allocations, commitments or expenditures in e-Kabineti). */
    private function freeBalanceLineRows(string $prefix, int $year = 0, int $directorate = 0, string $q = ''): array
    {
        [$where,$params]=$this->scope->budgetLineSql($this->userId(),'bl','report',$prefix);
        if($directorate>0){$where.=" AND bl.directorate_id=:{$prefix}Dir";$params[$prefix.'Dir']=$directorate;}
        if($year>0){$where.=" AND bc.base_year=:{$prefix}Year";$params[$prefix.'Year']=$year;}
        if($q!==''){$where.=' AND '.$this->likeAny(['bl.code','bl.name','d.name'],$q,$params,$prefix.'Q');}
        return $this->db->all("SELECT bl.id budget_line_id,bc.base_year fiscal_year,d.code directorate_code,d.name directorate,bl.code budget_line_code,bl.name budget_line,COALESCE(lp.code,bl.project_code) project_code,lp.name project_name,bl.linked_project_id,fb.allocated,fb.committed,fb.spent,fb.balance,fb.as_of FROM budget_lines bl JOIN budget_versions bv ON bv.id=bl.budget_version_id JOIN budget_cycles bc ON bc.id=bv.budget_cycle_id JOIN directorates d ON d.id=bl.directorate_id LEFT JOIN projects lp ON lp.id=bl.linked_project_id".BudgetExecution::LINE_FIGURES_APPLY." WHERE bv.is_official=1 AND fb.n>0 AND ia.v=0 AND ir.v=0 AND ic.v=0 AND ie.v=0 AND {$where} ORDER BY bc.base_year DESC,d.name,bl.code",$params);
    }

