    public function allocationCreate(): never
    {
        [$lineWhere,$lineParams]=$this->scope->budgetLineSql($this->userId(),'bl','select','allocationline');$lines=$this->db->all("SELECT bl.id,bc.base_year,bl.code,bl.name,bl.budget_category,d.code directorate_code,bl.total_amount,bl.total_amount-COALESCE((SELECT SUM(ba.current_amount) FROM budget_allocations ba WHERE ba.budget_line_id=bl.id),0) remaining FROM budget_lines bl JOIN budget_versions bv ON bv.id=bl.budget_version_id JOIN budget_cycles bc ON bc.id=bv.budget_cycle_id JOIN directorates d ON d.id=bl.directorate_id WHERE bv.is_official=1 AND bl.budget_category IS NOT NULL AND {$lineWhere} ORDER BY bc.base_year DESC,d.name,bl.code",$lineParams);
        [$projectWhere,$projectParams]=$this->scope->sql($this->userId(),'p.directorate_id','allocationproject');$projects=$this->db->all("SELECT p.id,p.code,p.name,p.budget_category,d.code directorate_code,d.name directorate,p.status FROM projects p JOIN directorates d ON d.id=p.directorate_id WHERE p.status NOT IN ('cancelled','completed') AND {$projectWhere} ORDER BY p.name",$projectParams);
        $linePicker=$this->searchPicker('budget_line_id','Пребарај по шифра или назив на буџетската ставка',$lines,static fn(array$line):string=>$line['base_year'].' · '.$line['code'].' · '.$line['name'].' · '.$line['directorate_code'].' · '.(self::BUDGET_CATEGORIES[$line['budget_category']]??'').' · Остаток '.View::money($line['remaining']));
        $projectPicker=$this->searchPicker('project_id','Пребарај по назив, шифра или сектор на проектот',$projects,static fn(array$project):string=>$project['code'].' · '.$project['name'].' · '.$project['directorate_code'].' · '.(self::BUDGET_CATEGORIES[$project['budget_category']??'']??'').' · '.$project['status']);
        $body='<section class="card"><h2>Нова распределба</h2><form method="post" action="/budget/allocations" class="form-grid">'.$this->view->csrf().'<div class="wide">'.$linePicker.'</div><div class="wide">'.$projectPicker.'</div><label>Година<input type="number" name="fiscal_year" min="2020" max="2100" required></label><label>Период<input type="number" name="period" min="0" max="12" value="0" required></label><label>Планирано<input name="planned_amount" inputmode="decimal" required></label><label>Тековно<input name="current_amount" inputmode="decimal" required></label><label>Проекција<input name="forecast_amount" inputmode="decimal"></label><div><button class="primary">Зачувај ја распределбата</button> <a class="button button-secondary" href="/budget">Откажи</a></div></form></section>';
        $this->view->render('Нова распределба',$body);
    }

    public function budgetLineEdit(int$id): never
    {
        $line=$this->db->one('SELECT bl.*,CONVERT(varchar(23),bl.updated_at,121) updated_at_token,bc.base_year,d.name directorate,COALESCE((SELECT SUM(ba.current_amount) FROM budget_allocations ba WHERE ba.budget_line_id=bl.id),0) allocated FROM budget_lines bl JOIN budget_versions bv ON bv.id=bl.budget_version_id JOIN budget_cycles bc ON bc.id=bv.budget_cycle_id JOIN directorates d ON d.id=bl.directorate_id WHERE bl.id=:id AND bv.is_official=1 AND bl.budget_category IS NOT NULL',['id'=>$id]);if(!$line)throw new HttpException(404,'Одобрената буџетска ставка не е пронајдена.');if(!$this->scope->allowsFinancial($this->userId(),(int)$line['directorate_id']))throw new HttpException(403,'Немате финансиска улога за овој сектор.');$categories=['goods_services'=>'Стоки и услуги','capital_investments'=>'Капитални инвестиции','wages'=>'Плата','subsidies'=>'Субвенции','utilities'=>'Комунални трошоци'];$categoryOptions='';foreach($categories as$value=>$label)$categoryOptions.='<option value="'.$value.'"'.($line['budget_category']===$value?' selected':'').'>'.$label.'</option>';
        $body='<section class="card"><p>Година: <strong>'.(int)$line['base_year'].'</strong> · Сектор сопственик: <strong>'.View::e($line['directorate']).'</strong> · Моментално распределено: <strong>'.View::money($line['allocated']).'</strong></p><form method="post" action="/budget/lines/'.$id.'" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="updated_at" value="'.View::e($line['updated_at_token']).'"><label>Шифра на проектот / ID<input name="project_code" maxlength="60" value="'.View::e($line['code']).'" required></label><label>Назив / опис<input name="name" maxlength="250" value="'.View::e($line['name']).'" required></label><label>Категорија<select name="budget_category">'.$categoryOptions.'</select></label><label>Сопствени приходи (МКД)<input name="own_revenue" inputmode="decimal" value="'.View::e($line['own_revenue']).'" required></label><label>Блок дотација (МКД)<input name="government_grant" inputmode="decimal" value="'.View::e($line['government_grant']).'" required></label><label>Блок дотација за здравство (МКД)<input name="health_grant" inputmode="decimal" value="'.View::e($line['health_grant']).'" required></label><label>Блок дотација за образование (МКД)<input name="education_grant" inputmode="decimal" value="'.View::e($line['education_grant']).'" required></label><label>Финансирање од задолжување (МКД)<input name="loan_financing" inputmode="decimal" value="'.View::e($line['loan_financing']).'" required></label><label>Пренесени сопствени приходи — извор 22 (МКД)<input name="carryover_revenue" inputmode="decimal" value="'.View::e($line['carryover_revenue'] ?? 0).'" required></label><div><button class="primary">Зачувај ја ставката</button> <a class="button button-secondary" href="/budget">Откажи</a></div></form></section>';
        $codeHistory=$this->db->all('SELECT CONVERT(varchar(16),c.changed_at,120) changed_at,c.old_code,c.new_code,c.matched_by,u.name changed_by FROM budget_line_code_changes c LEFT JOIN users u ON u.id=c.changed_by WHERE c.budget_line_id=:line ORDER BY c.id DESC',['line'=>$id]);
        if($codeHistory)$body.='<section class="card"><h2>Историја на шифрите</h2>'.$this->simpleTable($codeHistory).'</section>';
        $accessRows=$this->db->all('SELECT directorate_id,can_select,can_report FROM budget_line_directorate_access WHERE budget_line_id=:line',['line'=>$id]);$access=[];foreach($accessRows as$row)$access[(int)$row['directorate_id']]=$row;
        $directorates=$this->db->all('SELECT id,code,name FROM directorates WHERE active=1 AND id<>:owner ORDER BY name',['owner'=>(int)$line['directorate_id']]);$matrix='';foreach($directorates as$directorate){$grant=$access[(int)$directorate['id']]??[];$matrix.='<tr><td><strong>'.View::e($directorate['code']).'</strong><br><small>'.View::e($directorate['name']).'</small></td><td><label><input type="checkbox" name="select_directorate_ids[]" value="'.(int)$directorate['id'].'"'.(!empty($grant['can_select'])?' checked':'').'> Може да ја избере за распределба и извршување</label></td><td><label><input type="checkbox" name="report_directorate_ids[]" value="'.(int)$directorate['id'].'"'.(!empty($grant['can_report'])?' checked':'').'> Може да ја гледа и да известува</label></td></tr>';}
        $body.='<section class="card"><h2>Пристап од другите сектори</h2><p class="muted">Секторот сопственик ја задржува контролата врз ставката. Определете одделно кои сектори можат да ја изберат за своите проекти и кои можат да ја вклучат во извештаите.</p><form method="post" action="/budget/lines/'.$id.'/access">'.$this->view->csrf().'<div class="table-wrap"><table><thead><tr><th>Сектор</th><th>Избор</th><th>Известување</th></tr></thead><tbody>'.($matrix?:'<tr><td colspan="3">Нема други активни сектори.</td></tr>').'</tbody></table></div><p><button class="primary">Зачувај го пристапот на секторите</button></p></form></section>';
        $this->view->render('Уредување на буџетската ставка',$body);
    }

    public function freeBalance(): never
    {
        $execution=new BudgetExecution($this->db);$years=$execution->years();$canManage=$this->scope->canImportBudgetExecution($this->userId());
        $year=$this->request->integer('year');if(!in_array($year,$years,true))$year=$years[0]??(int)date('Y');
        $filters=['directorate_id'=>$this->request->integer('directorate_id')];foreach(['fund','program','economic','source','q']as$key)$filters[$key]=mb_substr(trim((string)$this->request->input($key,'')),0,100);
        if(!in_array($filters['source'],['','project','freebalance'],true))$filters['source']='';
        $data=$execution->effective($this->scope,$this->userId(),$year,$filters);$t=$data['totals'];
        $options=static function(array$rows,string$selected):string{$html='<option value="">Сите</option>';foreach($rows as$row)$html.='<option value="'.View::e($row['code']).'"'.((string)$row['code']===$selected?' selected':'').'>'.View::e($row['code'].' '.$row['name']).'</option>';return$html;};
        $distinct=fn(string$column):array=>$this->db->all("SELECT {$column}_code code,MAX({$column}_name) name FROM budget_execution_lines WHERE fiscal_year=:year GROUP BY {$column}_code ORDER BY {$column}_code",['year'=>$year]);
        $directorates=$this->db->all('SELECT id,name FROM directorates WHERE active=1 ORDER BY name');$directorateOptions='<option value="0">Сите</option>';foreach($directorates as$d)$directorateOptions.='<option value="'.(int)$d['id'].'"'.((int)$d['id']===$filters['directorate_id']?' selected':'').'>'.View::e($d['name']).'</option>';
        $yearOptions='';foreach($years?:[$year]as$y)$yearOptions.='<option value="'.$y.'"'.($y===$year?' selected':'').'>'.$y.'</option>';
        $body='<section class="card"><p>Извор: извештајот <strong>FreeBalance Summary Report</strong>'.($data['as_of']?' со состојба на <strong>'.View::e($data['as_of']).'</strong>':'').'. Правило: кога ставката припаѓа на проект што има распределби во е-Кабинет за годината, се прикажуваат вредностите на проектот (распределби, преземени обврски, расходи евидентирани во е-Кабинет), а FreeBalance останува референца за споредба.</p>'.($canManage?'<p><a class="button" href="/imports/freebalance-summary">Увези го FreeBalance извештајот</a></p>':'').'</section>';
        $body.='<section class="card"><div class="metrics"><div class="metric"><span>Распределено</span><strong>'.View::money($t['allocated']).'</strong></div><div class="metric"><span>Реализирано (потрошено)</span><strong>'.View::money($t['actual']).'</strong></div><div class="metric"><span>Обврски + преземени обврски</span><strong>'.View::money($t['open']).'</strong></div><div class="metric"><span>Расположиво салдо</span><strong>'.View::money($t['balance']).'</strong></div><div class="metric"><span>Проекти со приоритет</span><strong>'.(int)$t['project_rows'].'</strong></div><div class="metric"><span>Разлики со FreeBalance</span><strong>'.(int)$t['differences'].'</strong></div></div></section>';
        $body.='<form method="get" action="/budget/freebalance" class="card form-grid"><label>Година<select name="year">'.$yearOptions.'</select></label><label>Сектор<select name="directorate_id">'.$directorateOptions.'</select></label><label>Извор на финансирање<select name="fund">'.$options($distinct('fund'),$filters['fund']).'</select></label><label>Програма<select name="program">'.$options($distinct('program'),$filters['program']).'</select></label><label>Економска категорија<select name="economic">'.$options($distinct('economic'),$filters['economic']).'</select></label><label>Извор на податоците<select name="source"><option value="">Сите</option><option value="project"'.($filters['source']==='project'?' selected':'').'>Проект (е-Кабинет)</option><option value="freebalance"'.($filters['source']==='freebalance'?' selected':'').'>FreeBalance</option></select></label><label>Пребарај<input type="search" name="q" value="'.View::e($filters['q']).'" placeholder="Шифра или назив на проектот"></label><button class="primary">Филтрирај</button></form>';
        $body.='<section class="card"><h2>Ставки ('.count($data['rows']).')</h2>'.$this->freeBalanceTable($this->pageOf($data['rows'])).$this->pager().'</section>';
        if($canManage)$body.=$this->freeBalanceProgramForm($directorates);
        $this->view->render('Извршување според FreeBalance',$body);
    }

    private function freeBalanceTable(array $rows): string
    {
        if(!$rows)return'<p class="muted">Нема FreeBalance ставки за овој филтер. Увезете го извештајот или проверете ја врската на програмите со секторите.</p>';
        $html='<div class="table-wrap"><table><thead><tr><th>Извор на податоците</th><th>Сектор</th><th>Програма</th><th>Извор на финансирање</th><th>Економска категорија</th><th>Проект</th><th>Распределено</th><th>Реализирано</th><th>Обврски + преземени обврски</th><th>Салдо</th><th>FreeBalance (референца)</th></tr></thead><tbody>';
        foreach($rows as$r){
            $project=$r['project_id']?'<a href="/projects/'.(int)$r['project_id'].'"><strong>'.View::e($r['project_code']).'</strong></a>':'<strong>'.View::e($r['project_code']).'</strong>';
            $reference=$r['source']==='project'?View::money($r['freebalance']['allocated']).' / '.View::money($r['freebalance']['actual']).' / '.View::money($r['freebalance']['balance']).($r['difference']?' <span class="status-badge status-high">Разлика</span>':' <span class="status-badge status-valid">Се совпаѓа</span>').'<br><small>распределено / реализирано / салдо · '.(int)$r['lines'].' linja</small>':'—';
            $html.='<tr><td><span class="status-badge status-'.($r['source']==='project'?'active':'draft').'">'.($r['source']==='project'?'Проект (е-Кабинет)':'FreeBalance').'</span></td><td>'.View::e($r['directorate']??'Без сектор').'</td><td>'.View::e($r['program']).'</td><td>'.View::e($r['fund']).'</td><td>'.View::e($r['economic']).'</td><td>'.$project.'<br><small>'.View::e($r['project_name']).($r['function']!==''?' · '.View::e($r['function']):'').'</small></td><td>'.View::money($r['allocated']).'</td><td>'.View::money($r['actual']).'</td><td>'.View::money($r['open']).'</td><td>'.View::money($r['balance']).'</td><td>'.$reference.'</td></tr>';
        }
        return$html.'</tbody></table></div>';
    }

    private function freeBalanceProgramForm(array $directorates): string
    {
        $programs=$this->db->all('SELECT m.program_code,m.program_name,m.directorate_id,(SELECT COUNT(*) FROM budget_execution_lines bel WHERE bel.program_code=m.program_code AND bel.in_latest_report=1) lines FROM freebalance_program_directorates m ORDER BY CASE WHEN m.directorate_id IS NULL THEN 0 ELSE 1 END,m.program_code');
        if(!$programs)return'';
        $html='<section class="card" id="programs"><h2>Врска на FreeBalance програмите со секторите</h2><p class="muted">Програмата (PCLASS) го определува секторот што ја гледа ставката. Програмите без сектор ги гледаат само улогите со глобален пристап. Називот на програмата не е доволен за автоматско поврзување (на пр. 16306 и 92030 и двете се викаат „АДМИНИСТРАЦИЈА“), затоа поврзувањето се прави тука еднаш.</p><form method="post" action="/budget/freebalance/programs">'.$this->view->csrf().'<div class="table-wrap"><table><thead><tr><th>Шифра</th><th>Програма</th><th>Ставка</th><th>Сектор</th></tr></thead><tbody>';
        foreach($programs as$p){$select='<select name="directorate['.View::e($p['program_code']).']"><option value="0">— Без сектор —</option>';foreach($directorates as$d)$select.='<option value="'.(int)$d['id'].'"'.((int)$d['id']===(int)($p['directorate_id']??0)?' selected':'').'>'.View::e($d['name']).'</option>';$html.='<tr><td><strong>'.View::e($p['program_code']).'</strong></td><td>'.View::e($p['program_name']).'</td><td>'.(int)$p['lines'].'</td><td>'.$select.'</select></td></tr>';}
        return$html.'</tbody></table></div><button class="primary">Зачувај ги врските</button></form></section>';
    }

    private function approvedBudgetPreviewSummary(array $summary): string
    {
        $p=$summary['plan']??[];$t=$summary['totals']??[];
        $html='<div class="metrics"><div class="metric"><span>Вкупно одобрено</span><strong>'.View::money($t['total']??0).'</strong></div><div class="metric"><span>Нови ставки</span><strong>'.(int)($p['create']??0).'</strong></div><div class="metric"><span>Ставки што се ажурираат</span><strong>'.(int)($p['update']??0).'</strong></div><div class="metric"><span>Шифри што се менуваат</span><strong>'.(int)($p['code_changes']??0).'</strong></div><div class="metric"><span>Без промена</span><strong>'.(int)($p['unchanged']??0).'</strong></div><div class="metric"><span>Постојни надвор од буџетот</span><strong>'.(int)($p['orphans']??0).'</strong></div></div>';
        $html.='<p>Дотација (10) '.View::money($t['government_grant']??0).' · THV (21) '.View::money($t['own_revenue']??0).' · Пренесени СП (22) '.View::money($t['carryover_revenue']??0).' · Задолжување (04/06) '.View::money($t['loan_financing']??0).' · Реализација до '.View::e($summary['options']['as_of_date']??'—').'</p>';
        $labels=['wages'=>'Плати','goods_services'=>'Стоки и услуги','utilities'=>'Комунални услуги','subsidies'=>'Субвенции','capital'=>'Капитални','reserve'=>'Резерва','court'=>'00040 Судски одлуки'];
        $rows='';foreach($summary['controls']??[] as$c){if($c['expected']==='0.0000'&&$c['computed']==='0.0000')continue;$rows.='<tr><td>'.View::e($labels[$c['category']]??$c['category']).'</td><td>'.View::e($c['fund']).'</td><td>'.View::money($c['expected']).'</td><td>'.View::money($c['computed']).'</td><td><span class="status-badge status-'.($c['ok']?'valid':'invalid').'">'.($c['ok']?'Се совпаѓа':'Не се совпаѓа').'</span></td></tr>';}
        $html.='<h3>Проверка со листот „вкупно“</h3><div class="table-wrap"><table><thead><tr><th>Категорија</th><th>Извор</th><th>Според вкупно</th><th>Според ставките</th><th>Статус</th></tr></thead><tbody>'.$rows.'</tbody></table></div>';
        $warningLabels=['program_conflict'=>'Проектот се наоѓа под различни програми; се избира прикажаната програма','court_code_unknown'=>'Шифрата во листот 00040 не се наоѓа во капиталните','court_amount_differs'=>'Збирот на судските одлуки се разликува од листот 10 капитални','reserve_total_differs'=>'Збирот на резервите се разликува од листот РЕЗЕРВА','donations_not_itemised'=>'Донациите (31–99) се даваат само како збир и не се увезуваат како ставки'];
        if($summary['warnings']??[]){$html.='<h3>Забелешки за податоците од работната книга</h3><ul>';foreach($summary['warnings'] as$w)$html.='<li><strong>'.View::e($warningLabels[$w['code']]??$w['code']).'</strong>: '.View::e($w['detail']).' <small class="muted">('.View::e($w['sheet']).($w['row']?' rreshti '.(int)$w['row']:'').')</small></li>';$html.='</ul>';}
        if((int)($summary['invalid']??0)>0)$html.='<div class="card" style="border-color:var(--c-warning-line)"><h3>'.(int)$summary['invalid'].' редови со грешки</h3><p>Видете ја колоната <strong>Грешки</strong> во табелата подолу. Можете да ги поправите и повторно да ја прикачите датотеката, или при потврдата да изберете „Објави ги валидните редови и прескокни ги редовите со грешки“: тогаш нивните ставки во базата остануваат какви што се.</p><ul><li><strong>Ставка со распределби не може да премине во друг сектор</strong>: постојната ставка припаѓа на друг сектор и има распределби. Проверете ги буџетските шифри на секторите (Сектори → Уреди) или врската на програмата.</li><li><strong>Новиот збир е помал од распределбите</strong>: намалете ги распределбите на ставката или поправете го буџетот.</li><li><strong>Новата шифра се судира</strong>: друга ставка на секторот веќе ја има оваа шифра. Уредете ја или поставете ја на нула таа ставка.</li><li><strong>Распределба на дотациите за образование/здравство</strong>: постојната ставка има дотација за образование/здравство поголема од новата дотација; поправете ја во Уредување на ставката.</li></ul></div>';
        if($summary['unmapped_programs']??[])$html.='<p><strong>Програми без сектор:</strong> '.View::e(implode(', ',$summary['unmapped_programs'])).'. Поврзете ги во <a href="/budget/freebalance#programs">Буџет → Според FreeBalance → Врска на програмите</a> и повторно прикачете ја датотеката.</p>';
        if($summary['orphans']??[]){$o='';foreach($summary['orphans'] as$r)$o.='<tr><td><a href="/budget/lines/'.(int)$r['id'].'/edit">'.View::e($r['code']).'</a></td><td>'.View::e($r['name']).'</td><td>'.View::e($r['directorate']??'').'</td><td>'.View::e($r['budget_category']??'').'</td><td>'.View::money($r['total']).'</td><td>'.View::money($r['allocated']).'</td></tr>';$html.='<h3>Постојни ставки што не се наоѓаат во одобрениот буџет</h3><div class="table-wrap"><table><thead><tr><th>Шифра</th><th>Назив</th><th>Сектор</th><th>Категорија</th><th>Вкупно</th><th>Распределено</th></tr></thead><tbody>'.$o.'</tbody></table></div>';}
        return$html;
    }

    private function freeBalancePreviewSummary(array $summary): string
