        $html.='<p>Контролен збир на датотеката: распределено '.View::money($c['allocated']??0).' · реализирано '.View::money($c['actual']??0).' · салдо '.View::money($c['balance']??0).'.</p>';
        if($unmapped){$html.='<p><strong>Програми без сектор ('.count($unmapped).'):</strong> '.View::e(implode(' · ',array_map(static fn($code,$name)=>$code.' '.$name,array_keys($unmapped),$unmapped))).'. Увозот е дозволен; по објавувањето поврзете ги во <a href="/budget/freebalance#programs">Извршување според FreeBalance</a>.</p>';}
        return$html;
    }

