        $commitmentPicker=$this->searchPicker('commitment_id','Пребарај обврска по референца, шифра или проект',$commitments,static fn(array$row):string=>$row['reference'].' · '.$row['budget_line_code'].' · '.($row['project_name']??'Без проект').' · '.$row['directorate_code'].' · '.View::money($row['amount']));
