    public function riskCreate(): never
    {
        [$dWhere,$dParams]=$this->scope->sql($this->userId(),'id','rd');$dirs=$this->db->all("SELECT id,code,name FROM directorates WHERE {$dWhere} ORDER BY name",$dParams);$opts='';foreach($dirs as $d)$opts.='<option value="'.(int)$d['id'].'">'.View::e($d['code'].' · '.$d['name']).'</option>';
        [$projectWhere,$projectParams]=$this->scope->sql($this->userId(),'p.directorate_id','riskproject');$projects=$this->db->all("SELECT p.id,p.directorate_id,p.code,p.name,p.objective,p.status,d.code directorate_code FROM projects p JOIN directorates d ON d.id=p.directorate_id WHERE {$projectWhere} ORDER BY d.name,p.code",$projectParams);$projectOptions='<option value="">Без поврзан проект</option>';foreach($projects as$project){$summary=trim((string)$project['objective']);if($summary!=='')$summary=' · '.mb_strimwidth($summary,0,90,'…');$projectOptions.='<option value="'.(int)$project['id'].'" data-directorate="'.(int)$project['directorate_id'].'">'.View::e('#'.$project['id'].' · '.$project['directorate_code'].' · '.$project['code'].' · '.$project['name'].' · '.$project['status'].$summary).'</option>';}
        $body='<section class="card"><p><a href="/risks">← Назад кон регистарот на ризици</a></p><h2>Нов ризик</h2><p class="muted">Најпрво изберете го секторот. Листата на проекти ги прикажува ID-то, шифрата, називот, статусот и дел од целта.</p><form method="post" action="/risks" class="form-grid" data-risk-form>'.$this->view->csrf().'<label>Сектор<select name="directorate_id" data-risk-directorate required>'.$opts.'</select></label><label>Поврзан проект<select name="project_id" data-risk-project>'.$projectOptions.'</select></label><label>Категорија<select name="category" required>'.$this->riskCategoryOptions().'</select></label><label class="wide">Опис на ризикот<textarea name="description" maxlength="10000" required></textarea></label><label>Причина<textarea name="cause" maxlength="10000"></textarea></label><label>Последица<textarea name="consequence" maxlength="10000"></textarea></label><label>Почетна веројатност 1-5<input type="number" name="probability" min="1" max="5" required></label><label>Почетно влијание 1-5<input type="number" name="impact" min="1" max="5" required></label><label>Главна стратегија<select name="response"><option value="avoid">Избегнување</option><option value="reduce">Намалување</option><option value="transfer">Пренесување</option><option value="accept">Контролирано прифаќање</option></select></label><label>Преглед<input type="date" name="review_at"></label><button class="primary">Евидентирај го ризикот</button></form></section>';
        $this->view->render('Нов ризик',$body,['script'=>'<script src="/assets/risk-form.js?v=28" defer></script>']);
    }

    public function riskEdit(int $id): never
    {
        $risk=$this->db->one('SELECT r.*,CONVERT(varchar(23),r.updated_at,121) updated_at_token,d.code directorate_code,d.name directorate,p.code project_code,p.name project_name,p.status project_status FROM risks r JOIN directorates d ON d.id=r.directorate_id LEFT JOIN projects p ON p.id=r.project_id WHERE r.id=:id',['id'=>$id]);
        if(!$risk)throw new HttpException(404,'Ризикот не е пронајден.');
        if(!$this->scope->allowsDirectorate($this->userId(),(int)$risk['directorate_id']))throw new HttpException(403,'Надвор од вашиот опсег.');
        $responseOptions='';foreach(['avoid'=>'Избегни','reduce'=>'Намали','transfer'=>'Префрли','accept'=>'Прифати']as$value=>$label)$responseOptions.='<option value="'.$value.'"'.($risk['response']===$value?' selected':'').'>'.$label.'</option>';
        $statuses=['open'=>'Отворен','monitoring'=>'Во следење','mitigated'=>'Ублажено','closed'=>'Затворен'];if(!isset($statuses[$risk['status']]))$statuses[$risk['status']]=(string)$risk['status'];$statusOptions='';foreach($statuses as$value=>$label)$statusOptions.='<option value="'.View::e($value).'"'.($risk['status']===$value?' selected':'').'>'.View::e($label).'</option>';
        $projects=$this->db->all('SELECT id,code,name,objective,status FROM projects WHERE directorate_id=:directorate ORDER BY code',['directorate'=>(int)$risk['directorate_id']]);$projectOptions='<option value="">Без поврзан проект</option>';foreach($projects as$project){$summary=trim((string)$project['objective']);if($summary!=='')$summary=' · '.mb_strimwidth($summary,0,90,'…');$projectOptions.='<option value="'.(int)$project['id'].'"'.((int)$risk['project_id']===(int)$project['id']?' selected':'').'>'.View::e('#'.$project['id'].' · '.$project['code'].' · '.$project['name'].' · '.$project['status'].$summary).'</option>';}
        $score='<div class="metrics"><div class="metric"><span>Почетен ризик</span><strong>'.(int)$risk['probability'].'×'.(int)$risk['impact'].' = '.(int)$risk['inherent_score'].'</strong></div><div class="metric"><span>Резидуален ризик</span><strong>'.(int)($risk['residual_probability']??$risk['probability']).'×'.(int)($risk['residual_impact']??$risk['impact']).' = '.(int)($risk['residual_score']??$risk['inherent_score']).'</strong></div></div>';
        $body='<section class="card"><p>Сектор: <strong>'.View::e($risk['directorate_code'].' · '.$risk['directorate']).'</strong></p>'.$score.'<form method="post" action="/risks/'.$id.'" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="updated_at" value="'.View::e($risk['updated_at_token']).'"><label>Поврзан проект<select name="project_id">'.$projectOptions.'</select></label><label>Категорија<select name="category" required>'.$this->riskCategoryOptions((string)$risk['category']).'</select></label><label>Статус<select name="status">'.$statusOptions.'</select></label><label class="wide">Опис<textarea name="description" maxlength="10000" required>'.View::e($risk['description']).'</textarea></label><label>Причина<textarea name="cause" maxlength="10000">'.View::e($risk['cause']).'</textarea></label><label>Последица<textarea name="consequence" maxlength="10000">'.View::e($risk['consequence']).'</textarea></label><label>Почетна веројатност 1-5<input type="number" name="probability" min="1" max="5" value="'.(int)$risk['probability'].'" required></label><label>Почетно влијание 1-5<input type="number" name="impact" min="1" max="5" value="'.(int)$risk['impact'].'" required></label><label>Главна стратегија<select name="response">'.$responseOptions.'</select></label><label>Преглед<input type="date" name="review_at" value="'.View::e($risk['review_at']).'"></label><div><button class="primary">Зачувај ги промените</button> <a class="button button-secondary" href="/risks">Откажи</a></div></form></section>';
        $measures=$this->db->all('SELECT ra.id,ra.measure_type,ra.action,u.name owner,CONVERT(varchar(10),ra.due_at,23) due_at,ra.cost,ra.status,ra.probability_reduction,ra.impact_reduction,ra.evidence,CONVERT(varchar(19),ra.completed_at,120) completed_at FROM risk_actions ra LEFT JOIN users u ON u.id=ra.owner_id WHERE ra.risk_id=:risk ORDER BY CASE ra.status WHEN :completed THEN 2 WHEN :cancelled THEN 3 ELSE 1 END,ra.due_at,ra.id',['risk'=>$id,'completed'=>'completed','cancelled'=>'cancelled']);$body.='<section class="card"><h2>Превентивни мерки и мерки за намалување</h2>'.$this->riskMeasuresTable($this->pageOf($measures,'measures'),$id).$this->pager('measures').'</section>';
        $owners=$this->db->all("SELECT DISTINCT u.id,u.name,u.username FROM users u JOIN user_role_scopes urs ON urs.user_id=u.id JOIN roles ro ON ro.id=urs.role_id WHERE u.status='active' AND (urs.directorate_id=:directorate OR ro.code IN ('mayor','mayor_admin','system_admin')) AND (urs.valid_from IS NULL OR urs.valid_from<=SYSUTCDATETIME()) AND (urs.valid_to IS NULL OR urs.valid_to>=SYSUTCDATETIME()) ORDER BY u.name",['directorate'=>(int)$risk['directorate_id']]);$ownerOptions='<option value="">Без одговорно лице</option>';foreach($owners as$owner)$ownerOptions.='<option value="'.(int)$owner['id'].'">'.View::e($owner['name'].' · @'.$owner['username']).'</option>';
        $body.='<section class="card"><h2>Додај мерка</h2><p class="muted">Наведеното намалување се применува во резидуалниот резултат само кога мерката е означена „Завршена“. Мора да се намали барем веројатноста или влијанието.</p><form method="post" action="/risks/'.$id.'/measures" class="form-grid">'.$this->view->csrf().'<label>Вид<select name="measure_type">'.$this->measureTypeOptions().'</select></label><label>Одговорно лице<select name="owner_id">'.$ownerOptions.'</select></label><label class="wide">Мерка / дејство<textarea name="action" maxlength="10000" required></textarea></label><label>Рок<input type="date" name="due_at"></label><label>Предвидена цена (МКД)<input name="cost" inputmode="decimal"></label><label>Статус<select name="status">'.$this->measureStatusOptions().'</select></label><label>Намалување на веројатноста<input type="number" name="probability_reduction" min="0" max="4" value="0" required></label><label>Намалување на влијанието<input type="number" name="impact_reduction" min="0" max="4" value="0" required></label><label class="wide">Доказ / резултат<textarea name="evidence" maxlength="10000"></textarea></label><button class="primary">Додај ја мерката</button></form></section>';
        $this->view->render('Уредување на ризик #'.$id,$body);
    }

    public function riskMeasureEdit(int $riskId,int $measureId): never
    {
        $measure=$this->db->one('SELECT ra.*,LOWER(sys.fn_varbintohexstr(CONVERT(varbinary(8),ra.row_version))) row_version_token,CONVERT(varchar(10),ra.due_at,23) due_at_value,r.directorate_id,r.category,r.description FROM risk_actions ra JOIN risks r ON r.id=ra.risk_id WHERE ra.id=:id AND ra.risk_id=:risk',['id'=>$measureId,'risk'=>$riskId]);if(!$measure)throw new HttpException(404,'Мерката не е пронајдена.');if(!$this->scope->allowsDirectorate($this->userId(),(int)$measure['directorate_id']))throw new HttpException(403,'Надвор од вашиот опсег.');
        $owners=$this->db->all("SELECT DISTINCT u.id,u.name,u.username FROM users u JOIN user_role_scopes urs ON urs.user_id=u.id JOIN roles ro ON ro.id=urs.role_id WHERE u.status='active' AND (urs.directorate_id=:directorate OR ro.code IN ('mayor','mayor_admin','system_admin')) AND (urs.valid_from IS NULL OR urs.valid_from<=SYSUTCDATETIME()) AND (urs.valid_to IS NULL OR urs.valid_to>=SYSUTCDATETIME()) ORDER BY u.name",['directorate'=>(int)$measure['directorate_id']]);$ownerOptions='<option value="">Без одговорно лице</option>';foreach($owners as$owner)$ownerOptions.='<option value="'.(int)$owner['id'].'"'.((int)$measure['owner_id']===(int)$owner['id']?' selected':'').'>'.View::e($owner['name'].' · @'.$owner['username']).'</option>';
        $body='<section class="card"><p><strong>Ризик #'.$riskId.' · '.View::e($this->riskCategoryLabel((string)$measure['category'])).'</strong></p><p>'.View::e($measure['description']).'</p><form method="post" action="/risks/'.$riskId.'/measures/'.$measureId.'" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="row_version" value="'.View::e($measure['row_version_token']).'"><label>Вид<select name="measure_type">'.$this->measureTypeOptions((string)$measure['measure_type']).'</select></label><label>Одговорно лице<select name="owner_id">'.$ownerOptions.'</select></label><label class="wide">Мерка / дејство<textarea name="action" maxlength="10000" required>'.View::e($measure['action']).'</textarea></label><label>Рок<input type="date" name="due_at" value="'.View::e($measure['due_at_value']).'"></label><label>Трошок (МКД)<input name="cost" inputmode="decimal" value="'.View::e($measure['cost']).'"></label><label>Статус<select name="status">'.$this->measureStatusOptions((string)$measure['status']).'</select></label><label>Намалување на веројатноста<input type="number" name="probability_reduction" min="0" max="4" value="'.(int)$measure['probability_reduction'].'" required></label><label>Намалување на влијанието<input type="number" name="impact_reduction" min="0" max="4" value="'.(int)$measure['impact_reduction'].'" required></label><label class="wide">Доказ / резултат<textarea name="evidence" maxlength="10000">'.View::e($measure['evidence']).'</textarea></label><div><button class="primary">Зачувај ја мерката</button> <a class="button button-secondary" href="/risks/'.$riskId.'/edit">Откажи</a></div></form></section>';$this->view->render('Уредување на мерка #'.$measureId,$body);
    }

    public function inspectionReports(bool $csv=false): never
    {
        $reporting=new InspectionReporting($this->db);$directorate=$reporting->directorate();
        if(!$directorate)throw new HttpException(503,'Секторот за инспекциски надзор не е пронајден. Создадете го или активирајте го со шифрата INS.');
        $rows=$this->db->all('SELECT ir.*,u.name submitted_by_name FROM inspection_reports ir JOIN users u ON u.id=ir.submitted_by WHERE ir.directorate_id=:directorate ORDER BY ir.period_end DESC,ir.id DESC',['directorate'=>(int)$directorate['id']]);
        if($csv){$export=[];foreach($rows as$row){$item=['period_start'=>$row['period_start'],'period_end'=>$row['period_end']];foreach(InspectionReporting::METRICS as$key=>$labels)$item[$key]=$row[$key];$item['mobility_annual_plan']=$row['mobility_annual_plan'];$item['notes']=$row['notes'];$item['submitted_by']=$row['submitted_by_name'];$export[]=$item;}$headers=['period_start'=>'Период од','period_end'=>'Период до'];foreach(InspectionReporting::METRICS as$key=>$labels)$headers[$key]=$labels[0].' - '.$labels[1];$headers+=['mobility_annual_plan'=>'Годишен план на одделението за мобилност','notes'=>'Белешки','submitted_by'=>'Пријавено од'];$this->audit->record($this->userId(),'inspection_report.exported','InspectionReport',null,[],['row_count'=>count($export)]);(new TabularExport())->csv('raportimi-inspeksionit-'.date('Ymd-His'),$headers,$export);}
        $canSubmit=$this->scope->canSubmitInspectionReporting($this->userId(),(int)$directorate['id']);$body='<section class="card"><div class="toolbar"><div><h2>'.View::e($directorate['name']).'</h2><p class="muted">Показателите што се бараат во документот „Измени“. Секој ред претставува еден период на известување.</p></div><a class="button" href="/reports/inspection.csv">Извези CSV</a></div></section>';
        if($canSubmit){$groups=[];foreach(InspectionReporting::METRICS as$key=>$labels)$groups[$labels[0]][]=['key'=>$key,'label'=>$labels[1]];$fields='';foreach($groups as$group=>$metrics){$fields.='<fieldset class="wide"><legend>'.View::e($group).'</legend><div class="form-grid">';foreach($metrics as$metric)$fields.='<label>'.View::e($metric['label']).'<input type="number" name="'.View::e($metric['key']).'" min="0" max="2147483647" value="0" required></label>';$fields.='</div></fieldset>';}$body.='<section class="card"><h2>Нов извештај</h2><form method="post" action="/reports/inspection" class="form-grid">'.$this->view->csrf().'<label>Период од<input type="date" name="period_start" required></label><label>Период до<input type="date" name="period_end" required></label>'.$fields.'<fieldset class="wide"><legend>Одделение: Комунален ред</legend><label class="wide">Презентација на годишниот план на одделението за мобилност<textarea name="mobility_annual_plan" maxlength="4000" required></textarea></label></fieldset><label class="wide">Белешки<textarea name="notes" maxlength="4000"></textarea></label><button class="primary">Зачувај го извештајот</button></form></section>';}
        $table='';foreach($this->pageOf($rows) as$row){$total=0;foreach(array_keys(InspectionReporting::METRICS) as$key)$total+=(int)$row[$key];$table.='<tr><td>'.View::e($row['period_start']).' – '.View::e($row['period_end']).'</td><td>'.number_format($total,0,',','.').'</td><td>'.View::e($row['mobility_annual_plan']).'</td><td>'.View::e($row['submitted_by_name']).'</td><td>'.View::e($row['submitted_at']).'</td></tr>';}$body.='<section class="card"><h2>Историја</h2><div class="table-wrap"><table><thead><tr><th>Период</th><th>Збир на показателите</th><th>Годишен план</th><th>Пријавено од</th><th>Датум</th></tr></thead><tbody>'.($table?:'<tr><td colspan="5">Нема зачувани извештаи.</td></tr>').'</tbody></table></div>'.$this->pager().'</section>';$this->view->render('Известување на Секторот за инспекциски надзор',$body);
    }

    public function report(bool $csv=false): never
    {
