    }

    public function imports(?string $section = null): never
    {
        [, $rows] = $this->exportData('imports',true);
        $max = $this->effectiveUploadMb();
        $procurementImport = '<section class="card" id="procurement-projects"><h2>Неделна листа на јавни набавки</h2><p>Прифаќа CSV, XLSX или XLS. Единствен идентификатор е <strong>Шифра на набавката</strong>. Редовите без шифра се прескокнуваат; повторниот увоз не создава дупликати и ги ревидира само изменетите полиња.</p><p><a href="/imports/template.xlsx?type='.ImportWorkflow::PROCUREMENT_PROJECTS.'">Преземи Excel нацрт-образец</a> · <a href="/imports/template.csv?type='.ImportWorkflow::PROCUREMENT_PROJECTS.'">Преземи CSV нацрт-образец</a></p><form method="post" action="/imports/preview" enctype="multipart/form-data">'.$this->view->csrf().'<input type="hidden" name="import_type" value="'.ImportWorkflow::PROCUREMENT_PROJECTS.'"><label>Неделна листа<input type="file" name="file" accept=".csv,.xlsx,.xls" required></label><button class="primary">Валидирај ја листата на јавни набавки</button></form></section>';
        $cards = ['procurement-projects'=>$procurementImport];
