        if($this->scope->canImportBudgetExecution($this->userId()))$cards['approved-budget']='<section class="card" id="approved-budget"><h2>Буџет одобрен од Советот (БУЏЕТ И РЕАЛИЗАЦИЈА)</h2><p>Прикачете ја работната книга со листовите GRANT, 10 kapitalet, 21, 21 kapitalet, 22, 06, 04, 00040, REZERVA и totali. Секоја категорија и извор (10 Дотации, 21 СП, 22 пренесени СП, 04/06 задолжување) се проверува со листот <strong>totali</strong>. Прегледот покажува кои постојни буџетски ставки се ажурираат, на кои им се менува шифрата според структурата на FreeBalance, кои се создаваат и кои постојни ставки не се наоѓаат во одобрениот буџет. Ништо не се менува пред потврдата.</p><form method="post" action="/imports/preview" enctype="multipart/form-data" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="import_type" value="'.ImportWorkflow::APPROVED_BUDGET.'"><label>Фискална година<input type="number" name="fiscal_year" min="2020" max="2100" value="'.date('Y').'" required></label><label>Состојба на реализацијата на (опционално; во спротивно се чита од листот totali)<input type="date" name="as_of_date"></label><label>XLSX работна книга<input type="file" name="file" accept=".xlsx" required></label><button class="primary">Валидирај го одобрениот буџет</button></form></section>';
        if($this->scope->canImportBudgetExecution($this->userId()))$cards['freebalance-summary']='<section class="card" id="freebalance-summary"><h2>FreeBalance извештај (Summary Report)</h2><p>Прикачете го извозот <strong>FreeBalanceSummaryReport</strong> (на пр. Raporti_21.10.2026.XLSX). За секоја ставка се чуваат: распределениот износ, реализираното (платените расходи), обврските, преземените обврски и расположивото салдо. Збировите се проверуваат со меѓузбировите и со „Вкупно“. Кога ставката е поврзана со проект што има распределби во е-Кабинет, вредностите на проектот имаат приоритет.</p><form method="post" action="/imports/preview" enctype="multipart/form-data" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="import_type" value="'.ImportWorkflow::FREEBALANCE_SUMMARY.'"><label>Состојба на извештајот на<input type="date" name="as_of_date" value="'.date('Y-m-d').'" required></label><label>XLSX извештај<input type="file" name="file" accept=".xlsx,.xls" required></label><button class="primary">Валидирај го FreeBalance извештајот</button></form><p><a href="/budget/freebalance">Отвори го извршувањето според FreeBalance</a></p></section>';

        $cards['annual-budget'] = '<section class="card" id="annual-budget"><h2>Увези го годишниот буџет</h2><p>Го прифаќа моделот Budzhet_Bitola_2026_Import.xlsx со сите категории и петте извори на финансирање. Секторите се поврзуваат според Drejtoria_Kod; ID_Importit се чува за ревизија; Drejtoria_ID не се користи за поврзување. Повторниот увоз ја ажурира истата шифра во рамките на секторот и годината. Ставките што недостасуваат во датотеката не се бришат.</p><form method="post" action="/imports/preview" enctype="multipart/form-data" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="import_type" value="annual_budget"><label>Фискална година<input type="number" name="fiscal_year" min="2020" max="2100" value="'.date('Y').'" required></label><label>Excel или CSV<input type="file" name="file" accept=".xlsx,.csv" required></label><button class="primary">Валидирај го годишниот буџет</button></form></section>';

        $cards['capital-investments'] = '<section class="card" id="capital-investments"><h2>Капитални инвестиции</h2><p class="muted">Директно ги прифаќа колоните: Шифра на проектот, Капитални, Буџет, Остаток, СЕКТОР. Остатокот се чува како информативна состојба; оперативната расположивост и понатаму се пресметува од трансакциите.</p>'
            .'<p><a href="/imports/template.xlsx?type=capital_investment_budget">Преземи Excel образец</a> · <a href="/imports/template.csv?type=capital_investment_budget">Преземи CSV образец</a></p>'
            .'<form method="post" action="/imports/preview" enctype="multipart/form-data" class="form-grid">'.$this->view->csrf()
            .'<input type="hidden" name="import_type" value="'.ImportWorkflow::CAPITAL_BUDGET.'">'
            .'<label>Фискална година<input type="number" name="fiscal_year" min="2020" max="2100" value="'.date('Y').'" required></label>'
            .'<label>Состојба на остатокот на<input type="date" name="as_of_date" value="'.date('Y-m-d').'" required></label>'
            .'<label>Извор за колоната Буџет<select name="default_funding_source" required><option value="">Изберете извор</option><option value="own_revenue">Сопствени приходи</option><option value="government_grant">Блок дотација</option><option value="health_grant">Блок дотација за здравство</option><option value="education_grant">Блок дотација за образование</option></select></label>'
            .'<label>Excel или CSV<input type="file" name="file" accept=".csv,.xlsx" required></label><button class="primary">Валидирај ги капиталните инвестиции</button></form></section>';
        $cards['budget-expenditures'] = '<section class="card" id="budget-expenditures"><h2>Буџетски расходи</h2><p class="muted">Секој ред се поврзува со активна обврска преку единствена референца. Изворната референца на фактурата или налогот за плаќање не смее да се повторува.</p>'
            .'<p><a href="/imports/template.xlsx?type=budget_expenditures">Преземи Excel образец</a> · <a href="/imports/template.csv?type=budget_expenditures">Преземи CSV образец</a></p>'
            .'<form method="post" action="/imports/preview" enctype="multipart/form-data">'.$this->view->csrf()
            .'<input type="hidden" name="import_type" value="'.ImportWorkflow::EXPENDITURES.'"><label>Excel или CSV<input type="file" name="file" accept=".csv,.xlsx" required></label><button class="primary">Валидирај ги расходите</button></form></section>';

        $cards['projects'] = '<section class="card" id="projects"><h2>Постоечки увоз на проекти</h2><p><a href="/imports/template.xlsx?type=projects">Преземи Excel образец</a> · <a href="/imports/template.csv?type=projects">Преземи CSV образец</a></p><form method="post" action="/imports/preview" enctype="multipart/form-data">'.$this->view->csrf().'<input type="hidden" name="import_type" value="'.ImportWorkflow::PROJECTS.'"><label>CSV или XLSX<input type="file" name="file" accept=".csv,.xlsx" required></label><button class="primary">Валидирај ги проектите</button></form></section>';

        // Every import has its own sub-page (/imports/<section>); /imports is the overview with the history.
        if ($section !== null) {
            if (!isset(ImportWorkflow::SECTIONS[$section])) throw new HttpException(404, 'Увозот не е пронајден.');
            if (!isset($cards[$section])) throw new HttpException(403, 'Немате пристап до овој увоз.');
            $body = $cards[$section].($section === 'freebalance-summary' || $section === 'approved-budget' ? '' : '<p class="muted">Ефективен лимит за прикачување: <strong>'.$max.' MB</strong>.</p>');
        } else {
            $links = '';
            foreach (ImportWorkflow::SECTIONS as $slug => $label) if (isset($cards[$slug])) $links .= '<li><a href="/imports/'.$slug.'">'.View::e($label).'</a></li>';
            $body = $this->filterBar('imports', ['status','q']).$intro.'<section class="card"><h2>Видови увози</h2><ul>'.$links.'</ul></section>';
        }

        $batchId = trim((string) $this->request->input('batch_id', ''));
        if ($batchId !== '' && preg_match('/^[0-9a-f-]{36}$/i', $batchId)) {
            $batch = $this->db->one('SELECT ib.*,u.name created_by_name FROM import_batches ib LEFT JOIN users u ON u.id=ib.created_by WHERE ib.id=:id', ['id'=>$batchId]);
            if ($batch) {
                $previewRows = $this->db->all('SELECT external_row_key,status,payload,errors FROM import_rows WHERE import_batch_id=:id ORDER BY id', ['id'=>$batchId]);
                $summary = json_decode((string) ($batch['summary'] ?? '{}'), true) ?: [];
                $body .= '<section class="card"><h2>Преглед на пакетот</h2><p><strong>'.View::e($batch['id']).'</strong> · '.View::e($batch['type']).' · <span class="status-badge status-'.View::e($batch['status']).'">'.View::e($batch['status']).'</span></p>'
                    .'<div class="metrics"><div class="metric"><span>Валидни редови</span><strong>'.(int) ($summary['valid'] ?? 0).'</strong></div><div class="metric"><span>Редови со грешки</span><strong>'.(int) ($summary['invalid'] ?? 0).'</strong></div><div class="metric"><span>Вкупно буџетирано</span><strong>'.View::money($summary['totals']['budgeted'] ?? 0).'</strong></div><div class="metric"><span>Вкупно расходи / нето</span><strong>'.View::money($summary['totals']['net'] ?? $summary['totals']['expenditures'] ?? 0).'</strong></div></div>'
                    .match((string)$batch['type']){ImportWorkflow::FREEBALANCE_SUMMARY=>$this->freeBalancePreviewSummary($summary),ImportWorkflow::APPROVED_BUDGET=>$this->approvedBudgetPreviewSummary($summary),default=>''}
                    .$this->importPreviewTable($this->pageOf($previewRows,'preview')).$this->pager('preview');
                if((string)$batch['type']===ImportWorkflow::ENFORCEMENT_EXECUTIONS)$body.='<p><a class="button button-secondary" href="/imports/'.View::e($batchId).'/enforcement-result.xlsx">Преземи Excel со резултатите</a></p>';
                $batchErrors=json_decode((string)($batch['errors'] ?? '[]'),true) ?: [];
                if ($batchErrors && !$previewRows) $body.=$this->simpleTable($batchErrors);
                if ($batch['status'] === 'ready') {
                    $skip=(string)$batch['type']===ImportWorkflow::APPROVED_BUDGET&&(int)($summary['invalid']??0)>0?'<p><label><input type="checkbox" name="skip_invalid" value="1" required> Објави ги валидните редови и прескокни ги '.(int)$summary['invalid'].' редовите со грешки (нивните ставки во базата остануваат непроменети)</label></p>':'';
                    $retire=(string)$batch['type']===ImportWorkflow::APPROVED_BUDGET&&(int)($summary['plan']['orphans']??0)>0?'<p><label><input type="checkbox" name="retire_orphans" value="1"> Постави на нула постојните ставки што не се во одобрениот буџет и немаат распределби ('.(int)$summary['plan']['orphans'].' ставки; оние со распределби остануваат непроменети)</label></p>':'';
                    $body .= '<form method="post" action="/imports/confirm" data-confirm="Да се објават ли сите валидни редови од овој пакет? Дејството не може да се врати.">'.$this->view->csrf().$skip.$retire.'<input type="hidden" name="batch_id" value="'.View::e($batchId).'"><p><strong>Потврдата ги објавува сите редови во една трансакција.</strong></p><button class="primary">Потврди и објави го пакетот</button></form>';
                }
                if($this->scope->isSystemAdmin($this->userId())&&(string)$batch['status']!=='posted')$body.='<form method="post" action="/imports/'.View::e($batchId).'/delete" data-confirm="Да се избрише ли овој необјавен пакет и прикачената датотека?">'.$this->view->csrf().'<button class="button button-secondary">Избриши го овој пакет</button></form>';
                $body .= '</section>';
            }
        }
        if($section===null&&$this->scope->isSystemAdmin($this->userId()))$body.='<section class="card" id="cleanup"><h2>Исчисти ја историјата на увозите</h2><p class="muted">Само за Администраторот на системот. Се бришат необјавените пакети (преглед или со грешки) заедно со редовите и прикачените датотеки. Со втората опција се бришат и објавените пакети; оние поврзани со увезени податоци (FreeBalance, извршувања, историја на шифри) се чуваат и од нив се отстрануваат само привремените редови. Објавените податоци и ревизијата не се допираат.</p><form method="post" action="/imports/cleanup" class="form-grid" data-confirm="Да се исчисти ли историјата на увозите? Дејството не може да се врати.">'.$this->view->csrf().'<label>Постари од (денови; 0 = сите)<input type="number" name="older_than_days" min="0" max="3650" value="0" required></label><label><input type="checkbox" name="include_posted" value="1"> Вклучи ги и објавените пакети</label><label>Напишете ИСЧИСТИ за потврда<input name="confirm_text" pattern="PASTRO" required autocomplete="off"></label><button class="primary">Исчисти ја историјата</button></form></section>';
        if($section===null)$body .= '<section class="card"><h2>Историја на увозите</h2>'.$this->simpleTable($rows,'').'</section>';
        $this->view->render($section===null?'Увози':ImportWorkflow::SECTIONS[$section], $body);
    }

    public function enforcementImportResult(string $batchId): never
    {
        if(!$this->scope->canImportExecutedCases($this->userId()))throw new HttpException(403,'Само Финансии можат да го преземат резултатот од увозот.');
        $batch=$this->db->one('SELECT * FROM import_batches WHERE id=:id AND type=:type',['id'=>$batchId,'type'=>ImportWorkflow::ENFORCEMENT_EXECUTIONS]);if(!$batch)throw new HttpException(404,'Пакетот на извршувања не е пронајден.');
        $rows=$this->db->all('SELECT id,external_row_key,status,payload,errors FROM import_rows WHERE import_batch_id=:id ORDER BY id',['id'=>$batchId]);$linked=[];$unimported=[];
        foreach($rows as$row){$payload=json_decode((string)$row['payload'],true)?:[];$errors=json_decode((string)($row['errors']??'[]'),true)?:[];$item=['source_row_number'=>$payload['source_row_number']??'','journal_voucher_number'=>$payload['journal_voucher_number']??'','source_document_number'=>$payload['source_document_number']??'','beneficiary'=>$payload['beneficiary']??'','description'=>$payload['description']??'','coding_block_original'=>$payload['coding_block_original']??'','extracted_budget_code'=>$payload['extracted_budget_code']??'','debit_amount'=>(float)($payload['debit_amount']??0),'credit_amount'=>(float)($payload['credit_amount']??0),'net_amount'=>(float)($payload['debit_amount']??0)-(float)($payload['credit_amount']??0),'result'=>$row['status'],'reason'=>implode('; ',array_map(static fn(array$e):string=>(string)($e['code']??''),$errors)),'batch_id'=>$batchId,'external_row_key'=>$payload['external_row_key']??''];if($row['status']==='invalid')$unimported[]=$item;else$linked[]=$item;}
        $summary=json_decode((string)($batch['summary']??'{}'),true)?:[];$summaryRows=[];foreach(['valid','invalid','unchanged','header_row'] as$key)$summaryRows[]=['metric'=>$key,'value'=>$summary[$key]??0];foreach(($summary['options']??[])as$key=>$value)$summaryRows[]=['metric'=>$key,'value'=>$value];foreach(($summary['totals']??[])as$key=>$value)$summaryRows[]=['metric'=>$key,'value'=>$value];
        $headers=['source_row_number'=>'Изворен ред','journal_voucher_number'=>'Налог од дневникот','source_document_number'=>'Изворен документ','beneficiary'=>'Корисник','description'=>'Опис','coding_block_original'=>'Изворен блок','extracted_budget_code'=>'Поврзана шифра','debit_amount'=>'Должи','credit_amount'=>'Побарува','net_amount'=>'Нето','result'=>'Исход','reason'=>'Причина','batch_id'=>'Batch','external_row_key'=>'Единствен клуч'];
        $this->audit->record($this->userId(),'enforcement_import.result_exported','ImportBatch',$batchId,[],['linked'=>count($linked),'unimported'=>count($unimported)]);
        (new TabularExport())->xlsx('rezultati-permbarimeve-'.$batchId,[['name'=>'Сумарија','headers'=>['metric'=>'Показател','value'=>'Вредност'],'rows'=>$summaryRows],['name'=>'Поврзани','headers'=>$headers,'rows'=>$linked],['name'=>'Неувезени','headers'=>$headers,'rows'=>$unimported]]);
    }

