    public function mayorAgendaDirectorates(): never
    {
        if(!$this->scope->canAccessMayorAgenda($this->userId()))throw new HttpException(403,'Немате дозвола за агендата на Градоначалникот.');
        $ids=$this->scope->mayorAgendaDirectorateIds($this->userId());$params=[];$where='1=1';
        if($ids!==null){$marks=[];foreach($ids as$i=>$directorateId){$key='agenda'.$i;$marks[]=':'.$key;$params[$key]=$directorateId;}$where=$marks?'d.id IN ('.implode(',',$marks).')':'1=0';}
        $rows=$this->db->all("SELECT d.id,d.code,d.name,d.active,(SELECT COUNT(*) FROM projects p WHERE p.directorate_id=d.id) project_count,(SELECT COUNT(*) FROM risks r WHERE r.directorate_id=d.id) risk_count,(SELECT COUNT(*) FROM mayor_agenda_items mai WHERE mai.directorate_id=d.id AND mai.status='open') agenda_count FROM directorates d WHERE {$where} ORDER BY d.active DESC,d.name",$params);
        $cards='';foreach($rows as$row)$cards.='<a class="manual-card" href="/directorates/'.(int)$row['id'].'"><strong>'.View::e($row['code'].' · '.$row['name']).'</strong><span>'.(int)$row['project_count'].' проекти · '.(int)$row['risk_count'].' ризици · '.(int)$row['agenda_count'].' на агендата'.((bool)$row['active']?'':' · Неактивни').'</span></a>';
        if($cards==='')$cards='<p class="muted">Немате определен сектор за управување со агендата.</p>';
        $body='<section class="card"><h2>Избор на проекти за агендата со Градоначалникот</h2><p class="muted">Изберете сектор за да ги означите проектите и ризиците за кои треба да се дискутира. Раководителот на секторот има пристап само до својот сектор; Администраторот на Градоначалникот, Градоначалникот и Администраторот на системот имаат глобален приказ.</p></section><div class="manual-grid">'.$cards.'</div>';
        $this->view->render('Агенда на Градоначалникот',$body);
    }

