    public function directorate(int $id): never
    {
        $directorate=$this->db->one('SELECT id,code,name,active FROM directorates WHERE id=:id',['id'=>$id]);
        if(!$directorate)throw new HttpException(404,'Секторот не е пронајден.');
        $projects=$this->db->all('SELECT id,code,name,status,progress,CONVERT(varchar(10),starts_at,23) starts_at,CONVERT(varchar(10),ends_at,23) ends_at FROM projects WHERE directorate_id=:id ORDER BY CASE status WHEN :active THEN 0 WHEN :hold THEN 1 ELSE 2 END,updated_at DESC',['id'=>$id,'active'=>'active','hold'=>'on_hold']);
        $procurements=$this->db->all('SELECT TOP 500 id,procurement_code,contract_code,procurement_name FROM procurement_projects ORDER BY updated_at DESC');
        $risks=$this->db->all('SELECT r.id,r.category,r.description,r.inherent_score,r.residual_score,r.status,CONVERT(varchar(10),r.review_at,23) review_at,r.project_id,p.code project_code,p.name project_name,p.status project_status FROM risks r LEFT JOIN projects p ON p.id=r.project_id WHERE r.directorate_id=:id ORDER BY COALESCE(r.residual_score,r.inherent_score) DESC,r.id DESC',['id'=>$id]);
        $selected=$this->db->all("SELECT item_type,project_id,risk_id FROM mayor_agenda_items WHERE directorate_id=:id AND status='open' AND item_type IN ('project','risk')",['id'=>$id]);
        $selectedProjects=[];$selectedRisks=[];foreach($selected as$item){if($item['item_type']==='project')$selectedProjects[(int)$item['project_id']]=true;else$selectedRisks[(int)$item['risk_id']]=true;}

        $projectRows='';foreach($projects as$project)$projectRows.='<tr><td><input type="checkbox" name="project_ids[]" value="'.(int)$project['id'].'"'.(isset($selectedProjects[(int)$project['id']])?' checked':'').' aria-label="Избери го проектот '.View::e($project['code']).'"></td><td><a href="/projects/'.(int)$project['id'].'"><strong>'.View::e($project['code']).'</strong> · '.View::e($project['name']).'</a></td><td>'.View::e($project['status']).'</td><td>'.(int)$project['progress'].'%</td><td>'.View::e($project['starts_at']).' – '.View::e($project['ends_at']).'</td></tr>';
        if($projectRows==='')$projectRows='<tr><td colspan="5" class="muted">Овој сектор нема проекти.</td></tr>';
        $riskRows='';foreach($risks as$risk){$project=$risk['project_id']?'<a href="/projects/'.(int)$risk['project_id'].'"><strong>#'.(int)$risk['project_id'].' · '.View::e($risk['project_code']).'</strong><br>'.View::e($risk['project_name']).'<br><small>'.View::e($risk['project_status']).'</small></a>':'<span class="muted">Без поврзан проект</span>';$riskRows.='<tr><td><input type="checkbox" name="risk_ids[]" value="'.(int)$risk['id'].'"'.(isset($selectedRisks[(int)$risk['id']])?' checked':'').' aria-label="Избери го ризикот #'.(int)$risk['id'].'"></td><td><strong>#'.(int)$risk['id'].' · '.View::e($this->riskCategoryLabel((string)$risk['category'])).'</strong><br><small>'.View::e($risk['description']).'</small></td><td>'.$project.'</td><td>'.(int)$risk['inherent_score'].' → '.(int)($risk['residual_score']??$risk['inherent_score']).'</td><td>'.View::e($risk['status']).'</td><td>'.View::e($risk['review_at']).'</td></tr>';}
        if($riskRows==='')$riskRows='<tr><td colspan="6" class="muted">Овој сектор нема ризици.</td></tr>';

        $selection='<section class="card"><h2>Избери за дискусија или внимание на Градоначалникот</h2><p class="muted">Означете ги проектите и ризиците што треба да се прикажат на панелот. Отстранувањето на ознаката ги отстранува од активната агенда, но историјата се чува.</p><form method="post" action="/directorates/'.$id.'/mayor-agenda/selection">'.$this->view->csrf().'<h3>Проекти на секторот</h3><div class="table-wrap"><table><thead><tr><th>Избери</th><th>Проект</th><th>Статус</th><th>Напредок</th><th>Период</th></tr></thead><tbody>'.$projectRows.'</tbody></table></div><h3>Ризици на секторот</h3><div class="table-wrap"><table><thead><tr><th>Избери</th><th>Ризик</th><th>Поврзан проект</th><th>Почетен → Резидуален</th><th>Статус</th><th>Преглед</th></tr></thead><tbody>'.$riskRows.'</tbody></table></div><button class="primary">Зачувај го изборот</button></form></section>';

        $topicForm='<section class="card"><h2>Посебна тема за дискусија</h2><form method="post" action="/directorates/'.$id.'/mayor-agenda/topics" class="form-grid">'.$this->view->csrf().'<label>Наслов<input name="topic_title" maxlength="250" required></label><label>Приоритет<select name="priority"><option value="normal">Normal</option><option value="high">Висок</option><option value="critical">Критичен</option></select></label><label>Предложен датум<input type="date" name="discussion_date"></label><label class="wide">Појаснување / точка за дискусија<textarea name="topic_details" maxlength="10000"></textarea></label><button class="primary">Додај тема</button></form></section>';
        $agenda=$this->mayorAgendaRows($id,false);
        $current='<section class="card"><h2>Тековна агенда на секторот</h2>'.$this->mayorAgendaTable($this->pageOf($agenda,'agenda'),true,$id).$this->pager('agenda').'</section>';
        $procurementOptions='<option value="">Изберете запис</option>';foreach($procurements as$item)$procurementOptions.='<option value="'.(int)$item['id'].'">'.View::e($item['procurement_code'].' · '.($item['procurement_name']?:$item['contract_code'])).'</option>';
        $projectOptions='<option value="">Изберете проект</option>';foreach($projects as$item)$projectOptions.='<option value="'.(int)$item['id'].'">'.View::e($item['code'].' · '.$item['name']).'</option>';
        $linked=$this->db->all('SELECT pp.procurement_code,pp.procurement_name,p.id project_id,p.code project_code,p.name project_name FROM procurement_project_links ppl JOIN procurement_projects pp ON pp.id=ppl.procurement_project_id JOIN projects p ON p.id=ppl.project_id WHERE p.directorate_id=:id ORDER BY ppl.linked_at DESC',['id'=>$id]);
        $procurementLinks='<section class="card"><h2>Поврзи го проектот со листата на јавни набавки</h2><form method="post" action="/directorates/'.$id.'/procurement-projects/link" class="form-grid">'.$this->view->csrf().'<label>Запис од јавната набавка<select name="procurement_project_id" required>'.$procurementOptions.'</select></label><label>Проект на секторот<select name="project_id" required>'.$projectOptions.'</select></label><button class="primary">Создај врска</button></form>'.($linked?$this->simpleTable($linked):'<p class="muted">Сѐ уште нема врски.</p>').'</section>';
        $backHref=$this->scope->canManageDirectorates($this->userId())?'/directorates':'/mayor-agenda';
        $backLabel=$this->scope->canManageDirectorates($this->userId())?'Назад кон секторите':'Назад кон агендата';
        $heading='<section class="card"><p><strong>'.View::e($directorate['code'].' · '.$directorate['name']).'</strong> · '.((bool)$directorate['active']?'Активни':'Неактивни').'</p><p><a class="button button-secondary" href="'.$backHref.'">'.$backLabel.'</a></p></section>';
        $this->view->render('Проекти и агенда на секторот',$heading.$procurementLinks.$selection.$topicForm.$current);
    }

    public function mayorAgendaEdit(int $directorateId,int $itemId): never
    {
        $item=$this->db->one("SELECT mai.*,LOWER(sys.fn_varbintohexstr(CONVERT(varbinary(8),mai.row_version))) row_version_token,d.code directorate_code,d.name directorate,p.code project_code,p.name project_name,r.category risk_category FROM mayor_agenda_items mai JOIN directorates d ON d.id=mai.directorate_id LEFT JOIN projects p ON p.id=mai.project_id LEFT JOIN risks r ON r.id=mai.risk_id WHERE mai.id=:id AND mai.directorate_id=:directorate AND mai.status='open'",['id'=>$itemId,'directorate'=>$directorateId]);if(!$item)throw new HttpException(404,'Активната точка од агендата не е пронајдена.');
        $labels=['project'=>'Проект '.$item['project_code'].' · '.$item['project_name'],'risk'=>'Ризик #'.$item['risk_id'].' · '.$item['risk_category'],'topic'=>'Посебна тема'];$priorityOptions='';foreach(['normal'=>'Normal','high'=>'Висок','critical'=>'Критичен']as$value=>$label)$priorityOptions.='<option value="'.$value.'"'.($item['priority']===$value?' selected':'').'>'.$label.'</option>';
        $titleField=$item['item_type']==='topic'?'<label>Наслов<input name="topic_title" maxlength="250" value="'.View::e($item['topic_title']).'" required></label>':'<p class="wide"><strong>'.View::e($labels[$item['item_type']]??$item['item_type']).'</strong></p>';
        $body='<section class="card"><p>Сектор: <strong>'.View::e($item['directorate_code'].' · '.$item['directorate']).'</strong></p><form method="post" action="/directorates/'.$directorateId.'/mayor-agenda/'.$itemId.'" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="row_version" value="'.View::e($item['row_version_token']).'">'.$titleField.'<label>Приоритет<select name="priority">'.$priorityOptions.'</select></label><label>Предложен датум<input type="date" name="discussion_date" value="'.View::e($item['discussion_date']).'"></label><label class="wide">Појаснување / точка за дискусија<textarea name="topic_details" maxlength="10000">'.View::e($item['topic_details']).'</textarea></label><div><button class="primary">Зачувај ги промените</button> <a class="button button-secondary" href="/directorates/'.$directorateId.'">Откажи</a></div></form></section>';$this->view->render('Уредување на агендата на Градоначалникот',$body);
    }

    public function directorateEdit(int $id): never
    {
        if(!$this->scope->canManageDirectorates($this->userId()))throw new HttpException(403,'Само Администраторот на системот и Градоначалникот можат да ги администрираат секторите.');
        $directorate=$this->db->one('SELECT id,code,name,active,budget_codes,CONVERT(varchar(23),updated_at,121) updated_at_token FROM directorates WHERE id=:id',['id'=>$id]);if(!$directorate)throw new HttpException(404,'Секторот не е пронајден.');
