        $body='<section class="card"><p class="muted">Деактивирањето го отстранува секторот од новите обрасци, но не ги брише проектите, буџетот или историјата.</p><form method="post" action="/directorates/'.$id.'" class="form-grid">'.$this->view->csrf().'<input type="hidden" name="updated_at" value="'.View::e($directorate['updated_at_token']).'"><label>Единствена шифра<input name="code" minlength="2" maxlength="30" pattern="[A-Za-z0-9][A-Za-z0-9_-]{1,29}" value="'.View::e($directorate['code']).'" required></label><label>Назив<input name="name" minlength="3" maxlength="200" value="'.View::e($directorate['name']).'" required></label><label>Статус<select name="active">'.$statusOptions.'</select></label><label class="wide">Буџетски шифри (програмите во FreeBalance / одобрениот буџет)<input name="budget_codes" maxlength="200" value="'.View::e($directorate['budget_codes']??'').'" placeholder="p.sh. 92030, 92310, 93150, 94350"><small class="muted">FreeBalance ставките и ставките од одобрениот буџет со овие шифри на програми му припаѓаат на овој сектор. Една шифра може да припаѓа само на еден сектор.</small></label><div><button class="primary">Зачувај ги промените</button> <a class="button button-secondary" href="/directorates">Откажи</a></div></form></section>';
        $this->view->render('Уредување на секторот',$body);
    }

    public function users(): never
    {
        $userWhere='1=1';$userParams=[];$userStatus=trim((string)$this->request->input('status',''));$userSearch=trim((string)$this->request->input('q',''));if($userStatus!==''){$userWhere.=' AND status=:status';$userParams['status']=$userStatus;}if($userSearch!==''){$userWhere.=' AND (name LIKE :q_name OR username LIKE :q_username OR email LIKE :q_email)';$like='%'.$userSearch.'%';$userParams['q_name']=$like;$userParams['q_username']=$like;$userParams['q_email']=$like;}$users=$this->pagedQuery("SELECT id,name,username,email,status,email_verified_at,last_login_at,created_at FROM users WHERE {$userWhere} ORDER BY id DESC",$userParams);
