        $directorateOptions='<option value="">Глобален пристап / без сектор</option>';foreach($directorates as$d)$directorateOptions.='<option value="'.(int)$d['id'].'">'.View::e($d['code'].' · '.$d['name']).'</option>';
        $body='<section class="card"><h2>Регистрирај нов корисник</h2><form method="post" action="/users" class="form-grid">'.$this->view->csrf().'<label>Име и презиме<input name="name" maxlength="255" required></label><label>Username<input name="username" minlength="3" maxlength="100" pattern="[a-zA-Z0-9._-]+" required></label><label>Email<input type="email" name="email" maxlength="255" required></label><label>Почетна лозинка<input type="password" name="password" minlength="14" required autocomplete="new-password"></label><label>Повторете ја лозинката<input type="password" name="password_confirmation" minlength="14" required autocomplete="new-password"></label><label>Улога<select name="role_id" required>'.$roleOptions.'</select></label><label>Сектор<select name="directorate_id">'.$directorateOptions.'</select></label><label>Статус<select name="status"><option value="active">Активно</option><option value="disabled">Неактивно</option></select></label><button class="primary">Создај корисник</button></form></section><section class="card"><h2>Корисници и пристап</h2><div class="table-wrap"><table><thead><tr><th>Корисник</th><th>Контакт</th><th>Статус</th><th>Улога и сектор</th><th>Дејства</th></tr></thead><tbody>';
        $roleLabels=[];if($users){$params=[];$marks=[];foreach($users as$i=>$u){$marks[]=':u'.$i;$params['u'.$i]=(int)$u['id'];}foreach($this->db->all('SELECT urs.user_id,r.name role_name,d.code directorate FROM user_role_scopes urs JOIN roles r ON r.id=urs.role_id LEFT JOIN directorates d ON d.id=urs.directorate_id WHERE urs.user_id IN ('.implode(',',$marks).') AND (urs.valid_to IS NULL OR urs.valid_to>=SYSUTCDATETIME()) ORDER BY r.name',$params)as$a)$roleLabels[(int)$a['user_id']][]=$a['role_name'].($a['directorate']?' · '.$a['directorate']:'');}
        foreach($users as$u){
            $labels=$roleLabels[(int)$u['id']]??[];
            $status=(string)$u['status'];$body.='<tr><td data-label="Корисник"><strong>'.View::e($u['name']).'</strong><br><span class="meta">@'.View::e($u['username']).'</span></td><td data-label="Контакт">'.View::e($u['email']).'</td><td data-label="Статус"><span class="status-badge status-'.View::e($status).'">'.View::e($status).'</span></td><td data-label="Улога и сектор">'.View::e($labels?implode(', ',$labels):'Без улога — на чекање').'</td><td data-label="Дејства"><div class="user-actions"><a class="button button-secondary" href="/users/'.(int)$u['id'].'/edit">Уреди</a>'.((int)$u['id']!==$this->userId()?'<form method="post" action="/users/access">'.$this->view->csrf().'<input type="hidden" name="user_id" value="'.(int)$u['id'].'"><input type="hidden" name="status" value="'.($status==='active'?'disabled':'active').'"><button class="button button-secondary" type="submit">'.($status==='active'?'Деактивирај':'Активирај').'</button></form>':'').'<form method="post" action="/users/'.(int)$u['id'].'/delete" data-confirm="Да се избрише ли корисникот '.View::e($u['username']).'? Корисниците со историја можат само да се деактивираат.">'.$this->view->csrf().'<button class="button button-danger" type="submit">Избриши</button></form></div></td></tr>';
        }
        $body.=($users?'':'<tr><td colspan="5">Не е пронајден ниеден корисник.</td></tr>').'</tbody></table></div>'.$this->pager().'</section>';
        $body=$this->filterBar('users',['status','q']).$body;
        $this->view->render('Управување со корисници',$body);
    }

    public function aiTechnicalAssistant(): never
    {
        $client=new OpenAIResponsesClient(OpenAIConfig::fromApplication($this->config));
        $rows=$this->db->all("SELECT TOP 50 p.*,requester.name requested_by_name,reviewer.name reviewed_by_name,CONVERT(varchar(19),p.created_at,120) created_at_display,CONVERT(varchar(19),p.reviewed_at,120) reviewed_at_display FROM ai_technical_proposals p JOIN users requester ON requester.id=p.requested_by LEFT JOIN users reviewer ON reviewer.id=p.reviewed_by ORDER BY p.id DESC");
        $body='<section class="card"><h2>Техничка анализа</h2><p class="muted">Асистентот ја чита само санираната дијагностика. Тој може да предложи ограничено дејство; ниедно дејство не се извршува без одобрение од Администраторот на системот.</p>';
        if(!$client->isConfigured())$body.='<div class="alert error" role="alert">OpenAI не е активен или OPENAI_API_KEY недостасува.</div>';
        $body.='<form method="post" action="/ai-technical-assistant/proposals" class="form-grid">'.$this->view->csrf().'<label class="wide">Што треба да провери асистентот?<textarea name="request_text" maxlength="2000" required placeholder="На пр. провери го распоредувачот, миграциите и последните грешки"></textarea></label><div><button class="primary" type="submit"'.($client->isConfigured()?'':' disabled').'>Создај предлог</button></div></form></section>';
        foreach($rows as$row){$proposal=json_decode((string)$row['proposal_json'],true);$proposal=is_array($proposal)?$proposal:[];$result=json_decode((string)($row['execution_result']??''),true);$findings='';foreach((array)($proposal['findings']??[])as$item)$findings.='<li>'.View::e($item).'</li>';$checks='';foreach((array)($proposal['verification_steps']??[])as$item)$checks.='<li>'.View::e($item).'</li>';
            $body.='<section class="card"><header><h2>Предлог #'.(int)$row['id'].' · '.View::e($row['status']).'</h2><p class="muted">'.View::e($row['created_at_display']).' · '.View::e($row['requested_by_name']).'</p></header><p><strong>Барање:</strong> '.View::e($row['request_text']).'</p><p>'.View::e($proposal['summary']??'').'</p><p><strong>Дозволено дејство:</strong> '.View::e($row['action_key']).' · <strong>Ризик:</strong> '.View::e($row['risk_level']).'</p><p><strong>Интервенција:</strong> '.View::e($proposal['proposed_intervention']??'').'</p>'.($findings!==''?'<h3>Наоди</h3><ul>'.$findings.'</ul>':'').($checks!==''?'<h3>Проверка по дејството</h3><ul>'.$checks.'</ul>':'');
            if($row['status']==='proposed')$body.='<div class="grid"><form method="post" action="/ai-technical-assistant/proposals/'.(int)$row['id'].'/approve" class="form-grid">'.$this->view->csrf().'<label class="wide">Причина за одобрување<textarea name="review_reason" maxlength="2000" required></textarea></label><button class="primary" type="submit">Одобри и изврши</button></form><form method="post" action="/ai-technical-assistant/proposals/'.(int)$row['id'].'/reject" class="form-grid">'.$this->view->csrf().'<label class="wide">Причина за одбивање<textarea name="review_reason" maxlength="2000" required></textarea></label><button class="button button-secondary" type="submit">Одбиј</button></form></div>';
            elseif($row['reviewed_by_name'])$body.='<p><strong>Разгледано од:</strong> '.View::e($row['reviewed_by_name']).' · '.View::e($row['reviewed_at_display']).'<br><strong>Причина:</strong> '.View::e($row['review_reason']).'</p>';
            if(is_array($result))$body.='<h3>Резултат од извршувањето</h3><pre>'.View::e(json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)).'</pre>';
            $body.='</section>';
        }
        $this->view->render('Технички AI асистент',$body);
    }

    public function userEdit(int $id): never
    {
        $user=$this->db->one('SELECT id,name,username,email,status,CONVERT(varchar(23),updated_at,121) updated_at_token FROM users WHERE id=:id',['id'=>$id]);if(!$user)throw new HttpException(404,'Корисникот не е пронајден.');
        $scopes=$this->db->all('SELECT urs.id,r.name role_name,r.code role_code,d.code directorate_code,d.name directorate_name,CONVERT(varchar(10),urs.valid_from,23) valid_from,CONVERT(varchar(10),urs.valid_to,23) valid_to,urs.reason FROM user_role_scopes urs JOIN roles r ON r.id=urs.role_id LEFT JOIN directorates d ON d.id=urs.directorate_id WHERE urs.user_id=:id AND (urs.valid_to IS NULL OR urs.valid_to>=SYSUTCDATETIME()) ORDER BY r.name',['id'=>$id]);
        $roles=$this->db->all('SELECT id,code,name FROM roles WHERE active=1 ORDER BY name');$directorates=$this->db->all('SELECT id,code,name FROM directorates WHERE active=1 ORDER BY name');
        $roleOptions='<option value="">— Не додавај улога —</option>';foreach($roles as$row)$roleOptions.='<option value="'.(int)$row['id'].'">'.View::e($row['name'].' · '.$row['code']).'</option>';
        $directorateOptions='<option value="">Глобален пристап / без сектор</option>';foreach($directorates as$row)$directorateOptions.='<option value="'.(int)$row['id'].'">'.View::e($row['code'].' · '.$row['name']).'</option>';
        $statuses='';foreach(['active'=>'Активно','disabled'=>'Неактивно','locked'=>'Блокирано']as$value=>$label)$statuses.='<option value="'.$value.'"'.($user['status']===$value?' selected':'').'>'.$label.'</option>';
        $scopeRows='';foreach($scopes as$scope)$scopeRows.='<tr><td data-label="Улога"><strong>'.View::e($scope['role_name']).'</strong><br><small>'.View::e($scope['role_code']).'</small></td><td data-label="Сектор">'.View::e($scope['directorate_code']?$scope['directorate_code'].' · '.$scope['directorate_name']:'Глобални').'</td><td data-label="Важност">'.View::e(($scope['valid_from']?:'—').' → '.($scope['valid_to']?:'без рок')).'</td><td data-label="Отстрани"><label class="checkbox"><input type="checkbox" name="expire_scope_ids[]" value="'.(int)$scope['id'].'"> Отстрани го пристапот</label></td></tr>';
        $body='<form method="post" action="/users/'.$id.'" class="stack">'.$this->view->csrf().'<input type="hidden" name="updated_at" value="'.View::e($user['updated_at_token']).'"><section class="card"><h2>Профил</h2><div class="form-grid"><label>Име и презиме<input name="name" maxlength="255" value="'.View::e($user['name']).'" required></label><label>Username<input name="username" minlength="3" maxlength="100" pattern="[a-zA-Z0-9._-]+" value="'.View::e($user['username']).'" required></label><label>Email<input type="email" name="email" maxlength="255" value="'.View::e($user['email']).'" required></label><label>Статус<select name="status">'.$statuses.'</select></label></div></section>'
            .'<section class="card"><h2>Активни пристапи</h2><p class="muted">Секој ред е улога доделена за еден сектор или глобално. Другите улоги се чуваат; отстранете ги само оние што ги означувате.</p><div class="table-wrap"><table><thead><tr><th>Улога</th><th>Сектор</th><th>Важност</th><th>Отстрани</th></tr></thead><tbody>'.($scopeRows?:'<tr><td colspan="4">Корисникот нема ниеден активен пристап.</td></tr>').'</tbody></table></div>'
            .'<h3>Додај пристап</h3><div class="form-grid"><label>Улога<select name="role_id">'.$roleOptions.'</select></label><label>Сектор<select name="directorate_id">'.$directorateOptions.'</select><small class="hint">Се игнорира за глобалните улоги (Градоначалник, Финансии, Администратор…).</small></label></div></section>'
            .'<div class="form-actions"><a class="button button-secondary" href="/users">Откажи</a><button class="primary">Зачувај ги промените</button></div></form>';
        if($id!==$this->userId())$body.='<section class="card"><h2>Ресетирај ја лозинката</h2><p class="muted">Промената ги затвора сите активни сесии на овој корисник.</p><form method="post" action="/users/'.$id.'/password" class="form-grid">'.$this->view->csrf().'<label>Нова лозинка<input type="password" name="new_password" minlength="14" autocomplete="new-password" required></label><label>Потврда<input type="password" name="new_password_confirmation" minlength="14" autocomplete="new-password" required></label><div class="form-actions wide"><button class="primary">Промени лозинка</button></div></form></section>';
        $this->view->render('Уредување на корисникот',$body);
    }

    public function aiReporting(): never
    {
        $client=new OpenAIResponsesClient(OpenAIConfig::fromApplication($this->config));$selected=$this->request->integer('report');
        $reports=$this->pagedQuery('SELECT id,request_text,report_type,CONVERT(varchar(19),created_at,120) created_at FROM ai_reports WHERE requested_by=:user ORDER BY id DESC',['user'=>$this->userId()],'history');
        $body='<section class="card"><h2>Создај извештај од обичен јазик</h2><p class="muted">Агентот избира однапред дефиниран извештај, а апликацијата извршува само SQL за читање, параметризиран и ограничен според вашиот сектор.</p>';
