        $body.='<form method="post" action="/ai-reporting" class="form-grid">'.$this->view->csrf().'<label class="wide">Опишете го извештајот<textarea name="request_text" maxlength="2000" required placeholder="На пр. прикажи ги активните проекти и нивниот напредок за овој месец"></textarea></label><div><button class="primary" type="submit"'.($client->isConfigured()?'':' disabled').'>Генерирај извештај</button></div></form></section>';
        if($selected>0){$report=$this->db->one('SELECT * FROM ai_reports WHERE id=:id AND requested_by=:user',['id'=>$selected,'user'=>$this->userId()]);if(!$report)throw new HttpException(404,'Извештајот не е пронајден.');$result=json_decode((string)$report['result_json'],true);$result=is_array($result)?$result:[];$highlights='';foreach((array)($result['highlights']??[])as$item)$highlights.='<li>'.View::e($item).'</li>';$body.='<section class="card"><h2>'.View::e($result['title']??'Извештај').'</h2><p>'.View::e($result['summary']??'').'</p>'.($highlights!==''?'<ul>'.$highlights.'</ul>':'').$this->simpleTable((array)($result['rows']??[])).'</section>';}
        $history='';foreach($reports as$row)$history.='<tr><td><a href="/ai-reporting?report='.(int)$row['id'].'">#'.(int)$row['id'].'</a></td><td>'.View::e($row['request_text']).'</td><td>'.View::e($row['report_type']).'</td><td>'.View::e($row['created_at']).'</td></tr>';
        $body.='<section class="card"><h2>Мои извештаи</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Барање</th><th>Вид</th><th>Создадено</th></tr></thead><tbody>'.($history?:'<tr><td colspan="4">Нема извештаи.</td></tr>').'</tbody></table></div>'.$this->pager('history').'</section>';
        $this->view->render('AI известување',$body);
    }

    public function logs(bool $feed=false): never
    {
        $metrics=['failed_jobs'=>(int)$this->db->scalar('SELECT COUNT(*) FROM failed_jobs'),'failed_emails'=>(int)$this->db->scalar("SELECT COUNT(*) FROM notifications WHERE channel='email' AND status='failed'"),'pending_emails'=>(int)$this->db->scalar("SELECT COUNT(*) FROM notifications WHERE channel='email' AND status IN ('pending','sending')"),'scheduler_heartbeat'=>(string)($this->db->scalar("SELECT value FROM cache WHERE [key]='scheduler:last_heartbeat'")?:'mungon')];$data=$this->readLogs((string)$this->request->input('cursor',''),(string)$this->request->input('level','warning'),(string)$this->request->input('q',$this->request->input('search','')));
        if($feed){$data['metrics']=$metrics;$this->json($data);}
        $body=$this->filterBar('logs',['level','q']).'<div class="metrics">';foreach($metrics as $k=>$v)$body.='<div class="metric"><span>'.View::e($k).'</span><strong>'.View::e($v).'</strong></div>';$body.='</div><section class="card"><div id="log-feed" data-cursor="'.View::e($data['cursor']??'').'">'.$this->simpleTable($data['data'],false).'</div></section>';$this->view->render('Системски логови',$body,['script'=>'<script src="/assets/logs.js?v=28" defer></script>']);
    }

