        private const EXPORT_LIMIT=50000;

    private function exportData(string $module,bool $paged=false): array
    {
        // On screen every list is paged in SQL (key ''); exports are capped.
        $list=fn(string $sql,array $params)=>$paged?$this->pagedQuery($sql,$params):$this->db->all($sql.' OFFSET 0 ROWS FETCH NEXT '.self::EXPORT_LIMIT.' ROWS ONLY',$params);
        $q=trim((string)$this->request->input('q',''));$status=trim((string)$this->request->input('status',''));$category=trim((string)$this->request->input('category',''));$type=trim((string)$this->request->input('type',''));$year=$this->request->integer('year');$directorate=$this->request->integer('directorate_id');
        if($module==='projects'){
            [$where,$params]=$this->scope->sql($this->userId(),'p.directorate_id','xp');
            if($directorate>0){$where.=' AND p.directorate_id=:directorate';$params['directorate']=$directorate;}if($status!==''){$where.=' AND p.status=:status';$params['status']=$status;}if($q!==''){$where.=' AND '.$this->likeAny(['p.code','p.name','p.objective'],$q,$params);}
            if($this->request->input('late')==='1')$where.=" AND EXISTS(SELECT 1 FROM project_tasks lt WHERE lt.project_id=p.id AND lt.status NOT IN ('done','cancelled') AND lt.due_at<CONVERT(date,SYSUTCDATETIME()))";
            if($this->request->input('mine')==='1'){$where.=' AND p.manager_id=:mineUser';$params['mineUser']=$this->userId();}
            $rows=$list("SELECT p.id,p.code,p.name,d.code directorate_code,d.name directorate,u.name manager,p.status,p.progress,CONVERT(varchar(10),p.starts_at,23) starts_at,CONVERT(varchar(10),p.ends_at,23) ends_at,p.objective,(SELECT COUNT(*) FROM project_tasks t WHERE t.project_id=p.id) tasks,(SELECT COUNT(*) FROM project_tasks t WHERE t.project_id=p.id AND t.status='done') tasks_done,(SELECT COUNT(*) FROM project_tasks t WHERE t.project_id=p.id AND t.status NOT IN ('done','cancelled') AND t.due_at<CONVERT(date,SYSUTCDATETIME())) late_tasks,(SELECT MAX(COALESCE(r.residual_score,r.inherent_score)) FROM risks r WHERE r.project_id=p.id AND r.status NOT IN ('closed','mitigated')) risk_score,(SELECT CONVERT(varchar(10),MAX(pu.period),23) FROM progress_updates pu WHERE pu.project_id=p.id) last_report FROM projects p JOIN directorates d ON d.id=p.directorate_id LEFT JOIN users u ON u.id=p.manager_id WHERE {$where} ORDER BY p.updated_at DESC",$params);
        }elseif($module==='budget'){
            [$where,$params]=$this->scope->budgetLineSql($this->userId(),'bl','report','xb');$where.=' AND bl.budget_category IS NOT NULL';if($directorate>0){$where.=' AND bl.directorate_id=:directorate';$params['directorate']=$directorate;}if($year>0){$where.=' AND bc.base_year=:year';$params['year']=$year;}if($category!==''){$where.=' AND bl.budget_category=:category';$params['category']=$category;}if($q!==''){$where.=' AND '.$this->likeAny(['bl.code','bl.name','d.name'],$q,$params);}
            $rows=$list("SELECT bl.id,bl.directorate_id owner_directorate_id,bc.base_year fiscal_year,d.code directorate_code,d.name directorate,bl.code project_code,bl.name,bl.budget_category,bl.own_revenue,bl.government_grant,bl.health_grant,bl.education_grant,bl.loan_financing,bl.carryover_revenue,bl.source_section_code,bl.total_amount,bl.imported_available_amount,CONVERT(varchar(10),bl.imported_available_as_of,23) imported_available_as_of,".BudgetExecution::LINE_FIGURES_SELECT." FROM budget_lines bl JOIN budget_versions bv ON bv.id=bl.budget_version_id JOIN budget_cycles bc ON bc.id=bv.budget_cycle_id JOIN directorates d ON d.id=bl.directorate_id".BudgetExecution::LINE_FIGURES_APPLY." WHERE bv.is_official=1 AND {$where} ORDER BY bc.base_year DESC,d.name,bl.code",$params);
        }elseif($module==='execution'||$module==='reports'){
            [$where,$params]=$module==='execution'?$this->scope->budgetAllocationSql($this->userId(),'bl','p','xe'):$this->scope->budgetLineSql($this->userId(),'bl','report','xe');if($directorate>0){$where.=' AND bl.directorate_id=:directorate';$params['directorate']=$directorate;}if($year>0){$where.=' AND ba.fiscal_year=:year';$params['year']=$year;}if($q!==''){$where.=' AND '.$this->likeAny(['bl.code','bl.name','p.name','d.name'],$q,$params);}
            $rows=$this->db->all("SELECT ba.id allocation_id,ba.fiscal_year,d.code directorate_code,d.name directorate,bl.code budget_line_code,bl.name budget_line,p.code project_code,p.name project,ba.planned_amount,ba.current_amount,ba.forecast_amount,COALESCE((SELECT SUM(r.amount) FROM reservations r WHERE r.budget_allocation_id=ba.id AND r.status='active'),0) reserved,COALESCE((SELECT SUM(c.amount) FROM commitments c WHERE c.budget_allocation_id=ba.id AND c.status='active'),0) committed,COALESCE((SELECT SUM(e.amount) FROM expenditures e WHERE e.budget_allocation_id=ba.id),0) spent,ba.current_amount-COALESCE((SELECT SUM(r.amount) FROM reservations r WHERE r.budget_allocation_id=ba.id AND r.status='active'),0)-COALESCE((SELECT SUM(c.amount) FROM commitments c WHERE c.budget_allocation_id=ba.id AND c.status='active'),0) available FROM budget_allocations ba JOIN budget_lines bl ON bl.id=ba.budget_line_id JOIN directorates d ON d.id=bl.directorate_id LEFT JOIN projects p ON p.id=ba.project_id WHERE {$where} ORDER BY ba.fiscal_year DESC,bl.code",$params);
            // Source of each row: allocations recorded in e-Kabineti, or budget lines whose figures come from the FreeBalance import.
            $rows=array_map(static fn(array $r): array => $r+['source'=>'e-Kabineti','source_as_of'=>null,'budget_line_id'=>null],$rows);
            foreach($this->freeBalanceLineRows('xefb',$year,$directorate,$q) as$f)$rows[]=['allocation_id'=>null,'fiscal_year'=>$f['fiscal_year'],'directorate_code'=>$f['directorate_code'],'directorate'=>$f['directorate'],'budget_line_code'=>$f['budget_line_code'],'budget_line'=>$f['budget_line'],'project_code'=>$f['project_code'],'project'=>$f['project_name'],'planned_amount'=>null,'current_amount'=>$f['allocated'],'forecast_amount'=>null,'reserved'=>0,'committed'=>$f['committed'],'spent'=>$f['spent'],'available'=>$f['balance'],'source'=>'Import FreeBalance','source_as_of'=>$f['as_of'],'budget_line_id'=>$f['budget_line_id']];
            if($paged)$rows=$this->pageOf($rows);
        }elseif($module==='changes'){
            [$where,$params]=$this->scope->budgetAllocationSql($this->userId(),'sbl','sp','xc');if($directorate>0){$where.=' AND sbl.directorate_id=:directorate';$params['directorate']=$directorate;}if($year>0){$where.=' AND bcr.fiscal_year=:year';$params['year']=$year;}if($status!==''){$where.=' AND bcr.workflow_status=:status';$params['status']=$status;}if($type!==''){$where.=' AND bcr.type=:type';$params['type']=$type;}if($q!==''){$where.=' AND '.$this->likeAny(['bcr.justification','sbl.code','tbl.code','u.name'],$q,$params);}
            $rows=$list("SELECT bcr.id,bcr.type,bcr.amount,bcr.fiscal_year,bcr.urgency,bcr.workflow_status,sbl.code source_line,tbl.code target_line,d.code directorate_code,d.name directorate,bcr.justification,bcr.impact,u.name requested_by,bcr.created_at FROM budget_change_requests bcr JOIN budget_allocations sba ON sba.id=bcr.source_allocation_id JOIN budget_lines sbl ON sbl.id=sba.budget_line_id LEFT JOIN projects sp ON sp.id=sba.project_id LEFT JOIN budget_allocations tba ON tba.id=bcr.target_allocation_id LEFT JOIN budget_lines tbl ON tbl.id=tba.budget_line_id JOIN directorates d ON d.id=sbl.directorate_id JOIN users u ON u.id=bcr.requested_by WHERE {$where} ORDER BY bcr.id DESC",$params);
        }elseif($module==='workflows'){
            [$where,$params]=$this->scope->sql($this->userId(),'wi.directorate_id','xw');if(!$this->scope->isSystemAdmin($this->userId())){$roles=$this->scope->roles($this->userId());if(!$roles)return[$this->localizedHeaders(['workflow_number'],'mk'),[]];$marks=[];foreach($roles as$i=>$role){$marks[]=':workflow_role_'.$i;$params['workflow_role_'.$i]=$role;}$where.=' AND ws.required_role IN ('.implode(',',$marks).')';}if($status!==''){$where.=' AND wi.state=:status';$params['status']=$status;}if($type!==''){$where.=' AND wi.workflow_type=:type';$params['type']=$type;}if($q!==''){$where.=' AND '.$this->likeAny(['wi.workflow_type','CAST(wi.entity_id AS varchar(30))','bcr.justification','d.name'],$q,$params);}
            $rows=$list("SELECT wi.id workflow_number,wi.workflow_type,wi.entity_type,wi.entity_id,CASE WHEN wi.entity_type='App\\Models\\BudgetChangeRequest' THEN CONCAT('Budget change #',wi.entity_id,' · ',COALESCE(bcr.type,''),' · ',COALESCE(CONVERT(varchar(40),bcr.amount),''),N' ден. · ',COALESCE(bcr.justification,'')) ELSE CONCAT(wi.entity_type,' #',wi.entity_id) END subject,d.code directorate_code,d.name directorate,wi.state,ws.sequence current_step,ws.required_role,ws.state step_state,CONVERT(varchar(19),ws.due_at,120) due_at FROM workflow_instances wi JOIN directorates d ON d.id=wi.directorate_id JOIN workflow_steps ws ON ws.workflow_instance_id=wi.id AND ws.state='active' LEFT JOIN budget_change_requests bcr ON wi.entity_type='App\\Models\\BudgetChangeRequest' AND bcr.id=wi.entity_id WHERE {$where} ORDER BY wi.id DESC,ws.sequence",$params);
        }elseif($module==='risks'){
            [$where,$params]=$this->scope->sql($this->userId(),'r.directorate_id','xr');if($directorate>0){$where.=' AND r.directorate_id=:directorate';$params['directorate']=$directorate;}if($status!==''){$where.=' AND r.status=:status';$params['status']=$status;}if($category!==''){$where.=' AND r.category=:category';$params['category']=$category;}if($q!==''){$where.=' AND '.$this->likeAny(['r.description','r.cause','r.consequence','p.code','p.name'],$q,$params);}
            $rows=$list("SELECT r.id,d.code directorate_code,d.name directorate,p.id project_id,p.code project_code,p.name project_name,p.status project_status,r.category,r.description,r.cause,r.consequence,r.probability,r.impact,r.inherent_score,r.residual_probability,r.residual_impact,r.residual_score,r.response,r.status,CONVERT(varchar(10),r.review_at,23) review_at,(SELECT COUNT(*) FROM risk_actions ra WHERE ra.risk_id=r.id) measure_count,(SELECT COUNT(*) FROM risk_actions ra WHERE ra.risk_id=r.id AND ra.status='completed') completed_measure_count FROM risks r JOIN directorates d ON d.id=r.directorate_id LEFT JOIN projects p ON p.id=r.project_id WHERE {$where} ORDER BY COALESCE(r.residual_score,r.inherent_score) DESC,r.id DESC",$params);
        }elseif($module==='imports'){
            $params=[];$where='1=1';if($status!==''){$where.=' AND ib.status=:status';$params['status']=$status;}if($q!==''){$where.=' AND '.$this->likeAny(['ib.type','ib.status','ib.summary','ib.errors','u.name'],$q,$params);}$rows=$list("SELECT ib.id,ib.type,ib.status,ib.summary,ib.errors,u.name created_by,CONVERT(varchar(19),ib.confirmed_at,120) confirmed_at,CONVERT(varchar(19),ib.created_at,120) created_at FROM import_batches ib LEFT JOIN users u ON u.id=ib.created_by WHERE {$where} ORDER BY ib.created_at DESC,ib.id",$params);
        }elseif($module==='logs'){
            $data=$this->readLogs('',(string)$this->request->input('level','warning'),$q);$rows=$data['data'];if($paged)$rows=$this->pageOf($rows);
        }elseif($module==='audit'){
            $params=[];$where='1=1';if($q!==''){$where.=' AND '.$this->likeAny(['ae.action','ae.entity_type','ae.correlation_id','ae.reason','u.name'],$q,$params);}
            $rows=$list("SELECT ae.id,CONVERT(varchar(19),ae.occurred_at,120) occurred_at,u.name actor,ae.action,ae.entity_type,ae.entity_id,ae.correlation_id,ae.reason FROM audit_events ae LEFT JOIN users u ON u.id=ae.actor_id WHERE {$where} ORDER BY ae.id DESC",$params);
        }elseif($module==='directorates'){
            $params=[];$where='1=1';if($status!==''){$where.=' AND d.active=:active';$params['active']=$status==='active'?1:0;}if($q!==''){$where.=' AND '.$this->likeAny(['d.code','d.name'],$q,$params);}
            $rows=$list("SELECT d.id,d.code,d.name,d.budget_codes,d.active,(SELECT COUNT(*) FROM projects p WHERE p.directorate_id=d.id) projects,(SELECT COUNT(DISTINCT urs.user_id) FROM user_role_scopes urs WHERE urs.directorate_id=d.id AND (urs.valid_to IS NULL OR urs.valid_to>=SYSUTCDATETIME())) active_users,d.created_at FROM directorates d WHERE {$where} ORDER BY d.active DESC,d.name",$params);
        }elseif($module==='users'){
            $params=[];$where='1=1';if($status!==''){$where.=' AND u.status=:status';$params['status']=$status;}if($q!==''){$like='%'.$q.'%';$where.=' AND (u.name LIKE :q_name OR u.username LIKE :q_username OR u.email LIKE :q_email)';$params['q_name']=$like;$params['q_username']=$like;$params['q_email']=$like;}
            $rows=$list("SELECT u.id,u.name,u.username,u.email,u.locale,u.status,CONVERT(varchar(19),u.last_login_at,120) last_login_at,STRING_AGG(CONCAT(r.name,CASE WHEN d.code IS NULL THEN '' ELSE CONCAT(' · ',d.code) END),', ') roles FROM users u LEFT JOIN user_role_scopes urs ON urs.user_id=u.id AND (urs.valid_to IS NULL OR urs.valid_to>=SYSUTCDATETIME()) LEFT JOIN roles r ON r.id=urs.role_id LEFT JOIN directorates d ON d.id=urs.directorate_id WHERE {$where} GROUP BY u.id,u.name,u.username,u.email,u.locale,u.status,u.last_login_at ORDER BY u.name",$params);
        }else throw new HttpException(404,'Модулот за извоз не е пронајден.');
        return [$this->localizedHeaders(array_keys($rows[0]??['id'=>null]),'mk'),$rows];
    }

    /** Builds "(a LIKE :q_0 OR b LIKE :q_1 ...)" with distinct placeholders (PDO_SQLSRV native prepares reject repeated names) and escaped wildcards. */
    private function likeAny(array $columns,string $q,array &$params,string $prefix='q_'): string
    {
        $like='%'.str_replace(['[','%','_'],['[[]','[%]','[_]'],$q).'%';$parts=[];
        foreach(array_values($columns) as$i=>$column){$key=$prefix.$i;$parts[]=$column.' LIKE :'.$key;$params[$key]=$like;}
        return '('.implode(' OR ',$parts).')';
    }

