    private function projectActions(array$project): string
    {
        $id=(int)$project['id'];try{(new EvidenceAccess($this->db,$this->scope,$this->userId()))->project($id,true);}catch(HttpException $e){return'';}$links=[];
        if($this->scope->can($this->userId(),'create','project'))$links[]=['/projects/'.$id.'/tasks/new','Нова задача'];
        if($this->scope->can($this->userId(),'create','allocation')&&$this->scope->allowsFinancial($this->userId(),(int)$project['directorate_id']))$links[]=['/projects/'.$id.'/budget/new','Поврзи го проектот со буџетска ставка'];
        if($this->scope->can($this->userId(),'create','project_report'))$links[]=['/projects/'.$id.'/reports/new','Нов извештај'];
        if($this->scope->can($this->userId(),'create','attachment')){$links[]=['/projects/'.$id.'/documents/new','Додај документи'];$links[]=['/projects/'.$id.'/photos/new','Додај фотографии'];}
        try{(new EvidenceAccess($this->db,$this->scope,$this->userId()))->project($id,true,true);$links[]=['/projects/'.$id.'/share','Сподели со други корисници'];}catch(HttpException $e){}
        if(!$links)return'';$html='<nav class="card project-action-bar" aria-label="Дејства за проектот"><strong>Дејства</strong><div>';foreach($links as[$url,$label])$html.='<a class="button button-secondary" href="'.$url.'">'.View::e($label).'</a>';return$html.'</div></nav>';
    }
