    private function effectiveUploadMb(): int { $parse=static function(string $v):int{$v=trim($v);$n=(int)$v;return str_ends_with(strtolower($v),'g')?$n*1024:(str_ends_with(strtolower($v),'k')?(int)ceil($n/1024):$n);};return max(1,min((int)($this->config['uploads']['requested_max_mb']??20),$parse((string)ini_get('upload_max_filesize')),$parse((string)ini_get('post_max_size')))); }
    private function readLogs(string $cursor,string $level,string $search): array { $files=glob(APP_ROOT.'/storage/logs/application-*.log')?:[];rsort($files);$file=$files[0]??null;if(!$file)return ['data'=>[],'cursor'=>'','file'=>null];$offset=0;if($cursor){$decoded=json_decode((string)base64_decode($cursor,true),true);if(is_array($decoded)&&($decoded['file']??'')===basename($file))$offset=max(0,(int)($decoded['offset']??0));}$h=fopen($file,'rb');fseek($h,$offset);$weights=['debug'=>100,'info'=>200,'notice'=>250,'warning'=>300,'error'=>400,'critical'=>500,'alert'=>550,'emergency'=>600];$data=[];while(($line=fgets($h))!==false){$r=json_decode($line,true);if(!is_array($r))continue;$l=strtolower((string)($r['level_name']??'info'));if(($weights[$l]??200)<($weights[$level]??300))continue;if($search!==''&&!str_contains(mb_strtolower($line),mb_strtolower($search)))continue;$data[]=['timestamp'=>$r['datetime']??null,'level'=>$l,'message'=>$r['message']??'','correlation_id'=>$r['context']['correlation_id']??null];if(count($data)>200)array_shift($data);} $new=ftell($h);fclose($h);return ['data'=>$data,'cursor'=>base64_encode(json_encode(['file'=>basename($file),'offset'=>$new])),'file'=>basename($file)]; }

    private function mayorAgendaRows(?int $directorateId=null,bool $includeClosed=false): array
    {
        $where=$includeClosed?'1=1':"mai.status='open'";$params=[];
        if($directorateId!==null){$where.=' AND mai.directorate_id=:directorate';$params['directorate']=$directorateId;}
        else{$allowed=$this->scope->mayorAgendaDirectorateIds($this->userId());if($allowed!==null){$marks=[];foreach($allowed as$i=>$id){$key='agenda_scope_'.$i;$marks[]=':'.$key;$params[$key]=$id;}$where.=$marks?' AND mai.directorate_id IN ('.implode(',',$marks).')':' AND 1=0';}}
        return $this->db->all("SELECT TOP 300 mai.id,mai.item_type,mai.priority,CONVERT(varchar(10),mai.discussion_date,23) discussion_date,mai.status,mai.topic_title,mai.topic_details,d.code directorate_code,d.name directorate,p.id project_id,p.code project_code,p.name project_name,p.progress project_progress,p.status project_status,r.id risk_id,r.category risk_category,r.description risk_description,r.inherent_score,r.residual_score,r.status risk_status,r.project_id risk_project_id,rp.code risk_project_code,rp.name risk_project_name,rp.status risk_project_status,ac.id case_id,ac.case_number,ac.subject case_subject,ac.status case_status,u.name selected_by,CONVERT(varchar(19),mai.selected_at,120) selected_at FROM mayor_agenda_items mai JOIN directorates d ON d.id=mai.directorate_id LEFT JOIN projects p ON p.id=mai.project_id LEFT JOIN risks r ON r.id=mai.risk_id LEFT JOIN projects rp ON rp.id=r.project_id LEFT JOIN administrative_cases ac ON ac.id=mai.case_id JOIN users u ON u.id=mai.selected_by WHERE {$where} ORDER BY CASE mai.priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 ELSE 2 END,CASE WHEN mai.discussion_date IS NULL THEN 1 ELSE 0 END,mai.discussion_date,mai.id DESC",$params);
    }

    private function mayorAgendaTable(array $rows,bool $manageable=false,?int $directorateId=null): string
    {
        if(!$rows)return '<p class="muted">Нема активни точки за дискусија.</p>';
        $typeLabels=['project'=>'Проект','risk'=>'Ризик','case'=>'Предмети','topic'=>'Тема'];$priorityLabels=['normal'=>'Normal','high'=>'Висок','critical'=>'Критичен'];
        $html='<div class="table-wrap"><table><thead><tr><th>Приоритет</th><th>Вид</th><th>Сектор</th><th>Прашање за дискусија</th><th>Тековна состојба</th><th>Датум</th><th>Избрано од</th>'.($manageable?'<th>Дејство</th>':'').'</tr></thead><tbody>';
        foreach($rows as$row){
            if($row['item_type']==='project'){$issue='<a href="/projects/'.(int)$row['project_id'].'"><strong>'.View::e($row['project_code']).'</strong> · '.View::e($row['project_name']).'</a>';$state=(int)$row['project_progress'].'% · '.View::e($row['project_status']);}
            elseif($row['item_type']==='risk'){$project=$row['risk_project_id']?' · Проект #'.(int)$row['risk_project_id'].' · '.View::e($row['risk_project_code'].' · '.$row['risk_project_name']):' · Без проект';$issue='<a href="/risks/'.(int)$row['risk_id'].'/edit"><strong>#'.(int)$row['risk_id'].' · '.View::e($this->riskCategoryLabel((string)$row['risk_category'])).'</strong></a><br><small>'.View::e($row['risk_description']).'</small><br><small>'.$project.'</small>';$state='Исход '.(int)$row['inherent_score'].' → '.(int)($row['residual_score']??$row['inherent_score']).' · '.View::e($row['risk_status']);}
            elseif($row['item_type']==='case'){$issue='<a href="/cases/'.(int)$row['case_id'].'"><strong>'.View::e($row['case_number']).'</strong> · '.View::e($row['case_subject']).'</a>';$state=View::e($row['case_status']);}
            else{$issue='<strong>'.View::e($row['topic_title']).'</strong>'.($row['topic_details']?'<br><small>'.View::e($row['topic_details']).'</small>':'');$state='Чека дискусија';}
            $actions='';if($manageable&&$directorateId!==null){$actions='<div class="inline-actions"><a class="button button-secondary" href="/directorates/'.$directorateId.'/mayor-agenda/'.(int)$row['id'].'/edit">Уреди</a><form method="post" action="/directorates/'.$directorateId.'/mayor-agenda/'.(int)$row['id'].'/status">'.$this->view->csrf().'<input type="hidden" name="status" value="discussed"><button class="button button-secondary">Означи како разгледано</button></form><form method="post" action="/directorates/'.$directorateId.'/mayor-agenda/'.(int)$row['id'].'/status">'.$this->view->csrf().'<input type="hidden" name="status" value="removed"><button class="button button-secondary">Отстрани</button></form></div>';}
            $html.='<tr><td><span class="status-badge status-'.View::e($row['priority']).'">'.View::e($priorityLabels[$row['priority']]??$row['priority']).'</span></td><td>'.View::e($typeLabels[$row['item_type']]??$row['item_type']).'</td><td><strong>'.View::e($row['directorate_code']).'</strong><br><small>'.View::e($row['directorate']).'</small></td><td>'.$issue.'<br><a class="button button-secondary button-small" href="/mayor-agenda/'.(int)$row['id'].'/prepare">Подготви средба</a></td><td>'.$state.'</td><td>'.View::e($row['discussion_date']?:'Без датум').'</td><td>'.View::e($row['selected_by']).'<br><small>'.View::e($row['selected_at']).'</small></td>'.($manageable?'<td>'.$actions.'</td>':'').'</tr>';
        }
        return $html.'</tbody></table></div>';
    }

    /** Risk level of a project from its highest open residual score. */
    private static function riskLevel(mixed $score): array { if($score===null)return['—','status-draft'];$score=(int)$score;return$score>=15?['Висок','status-overdue']:($score>=8?['Среден','status-on_hold']:['Низок','status-active']); }

    private function projectDeadline(array $r): array
    {
        if(!$r['ends_at'])return['—','Без рок',''];if(in_array($r['status'],['completed','cancelled'],true))return[self::shortDate($r['ends_at']),$r['status']==='completed'?'Завршена':'Откажано',''];
        if((int)$r['late_tasks']>0)return[self::shortDate($r['ends_at']),(int)$r['late_tasks'].' task'.((int)$r['late_tasks']===1?'':'s').' со доцнење','text-danger'];
        $days=(int)(new \DateTimeImmutable('today'))->diff(new \DateTimeImmutable($r['ends_at']))->format('%r%a');return[self::shortDate($r['ends_at']),$days<0?'доцнење '.(-$days).' дена':'edhe '.$days.' дена',$days<0?'text-danger':''];
    }

    /** Projects list: the project column stays fixed when the table scrolls horizontally. */
    private function projectsListTable(array $rows): string
    {
        if(!$rows)return'<div class="empty-state">Ниеден проект не одговара на филтрите.</div>';
        $html='<div class="table-wrap table-wrap--wide"><table class="data-table"><thead><tr><th>Проект</th><th>Сектор</th><th>Менаџер</th><th>Статус</th><th>Напредок</th><th>Tasks</th><th>Рок</th><th>Ризик</th><th>Последен извештај</th></tr></thead><tbody>';
        foreach($rows as$r){[$due,$note,$noteClass]=$this->projectDeadline($r);[$risk,$riskClass]=self::riskLevel($r['risk_score']);$progress=(int)$r['progress'];
            $html.='<tr id="project-'.(int)$r['id'].'"><td><a href="/projects/'.(int)$r['id'].'"><strong>'.View::e($r['name']).'</strong></a><small class="cell-sub">'.View::e($r['code']).'</small></td><td>'.View::e($r['directorate']).'</td><td>'.View::e($r['manager']??'—').'</td><td>'.$this->badge((string)$r['status']).'</td><td><span class="progress-cell"><progress class="progress-bar" max="100" value="'.$progress.'" aria-hidden="true"></progress><span class="num">'.$progress.'%</span></span></td><td class="num">'.(int)$r['tasks_done'].' / '.(int)$r['tasks'].'</td><td><span class="num">'.$due.'</span><small class="cell-sub '.$noteClass.'">'.View::e($note).'</small></td><td><span class="status-badge '.$riskClass.'">'.$risk.'</span></td><td class="num">'.self::shortDate($r['last_report']).'</td></tr>';}
        return$html.'</tbody></table></div><p class="table-hint">Колоната „Проект“ останува фиксирана лево; табелата се движи хоризонтално со ← → или Shift + тркалце на глувчето.</p>';
    }

    private function projectCards(array $rows): string
    {
        if(!$rows)return'<div class="empty-state">Ниеден проект не одговара на филтрите.</div>';
        $html='<div class="project-cards">';
        foreach($rows as$r){[$due,$note,$noteClass]=$this->projectDeadline($r);[$risk,$riskClass]=self::riskLevel($r['risk_score']);$progress=(int)$r['progress'];
            $html.='<article class="project-card" id="project-'.(int)$r['id'].'"><div class="project-hero__badges"><span class="code-chip">'.View::e($r['code']).'</span>'.$this->badge((string)$r['status']).($r['risk_score']!==null?'<span class="status-badge '.$riskClass.'">Ризик '.mb_strtolower($risk).'</span>':'').'</div><h3><a href="/projects/'.(int)$r['id'].'">'.View::e($r['name']).'</a></h3><p class="project-card__meta">'.View::e($r['directorate'].' · '.($r['manager']??'Без менаџер')).'</p><span class="progress-cell"><progress class="progress-bar" max="100" value="'.$progress.'" aria-hidden="true"></progress><span class="num">'.$progress.'%</span></span><p class="project-card__meta">Tasks '.(int)$r['tasks_done'].' / '.(int)$r['tasks'].' · Рок '.$due.' · <span class="'.$noteClass.'">'.View::e($note).'</span></p></article>';}
        return$html.'</div>';
    }

