    private function approvedBudgetTable(array$rows,bool$editable): string {if(!$rows)return'<p class="muted">Нема ставки од одобрениот буџет.</p>';$labels=['goods_services'=>'Стоки и услуги','capital_investments'=>'Капитални инвестиции','wages'=>'Плата','subsidies'=>'Субвенции','utilities'=>'Комунални трошоци'];$showActions=$editable&&array_filter($rows,fn(array$r):bool=>$this->scope->allowsFinancial($this->userId(),(int)$r['owner_directorate_id']));$html='<div class="table-wrap"><table><thead><tr><th>Година</th><th>Сектор сопственик</th><th>Шифра на проектот / ID</th><th>Категорија</th><th>Сопствени приходи</th><th>Блок дотација</th><th>Дотација здравство</th><th>Дотација образование</th><th>Задолжување</th><th>Bartja (22)</th><th>Вкупно</th><th>Остаток според увозот</th><th>Состојба на</th><th>Распределено</th><th>Преземено</th><th>Потрошено</th><th>Слободни</th><th>Извор</th>'.($showActions?'<th>Дејство</th>':'').'</tr></thead><tbody>';foreach($rows as$r){$canManage=$showActions&&$this->scope->allowsFinancial($this->userId(),(int)$r['owner_directorate_id']);$html.='<tr><td>'.(int)$r['fiscal_year'].'</td><td>'.View::e($r['directorate']).'</td><td><strong>'.View::e($r['project_code']).'</strong><br><small>'.View::e($r['name']).'</small></td><td>'.View::e($labels[$r['budget_category']]??$r['budget_category']).'</td><td>'.View::money($r['own_revenue']).'</td><td>'.View::money($r['government_grant']).'</td><td>'.View::money($r['health_grant']).'</td><td>'.View::money($r['education_grant']).'</td><td>'.View::money($r['loan_financing'] ?? 0).'</td><td>'.View::money($r['carryover_revenue'] ?? 0).'</td><td>'.View::money($r['total_amount']).'</td><td>'.($r['imported_available_amount']===null?'—':View::money($r['imported_available_amount'])).'</td><td>'.View::e($r['imported_available_as_of']??'').'</td><td>'.View::money($r['allocated']).'</td><td>'.View::money($r['committed']).'</td><td>'.View::money($r['spent']).'</td><td>'.View::money($r['free_amount']).'</td><td>'.(($r['execution_source']??'')==='FreeBalance'?'<span class="status-badge status-draft">FreeBalance</span><br><small>'.View::e($r['execution_as_of']??'').'</small>':(($r['execution_source']??'')==='e-Kabineti'?'<span class="status-badge status-active">е-Кабинет</span>':'—')).'</td>'.($showActions?'<td>'.($canManage?'<a class="button button-secondary" href="/budget/lines/'.(int)$r['id'].'/edit">Уреди / определи пристап</a>':'<span class="muted">Само известување</span>').'</td>':'').'</tr>';}return$html.'</tbody></table></div>';}
    private function risksTable(array $rows,bool$editable): string { if(!$rows)return '<p class="muted">Нема податоци.</p>';$html='<div class="table-wrap"><table><thead><tr><th>ID</th><th>Сектор</th><th>Поврзан проект</th><th>Категорија</th><th>Опис</th><th>Почетен</th><th>Резидуален</th><th>Мерки</th><th>Статус</th>'.($editable?'<th>Дејство</th>':'').'</tr></thead><tbody>';foreach($rows as$r){$project=$r['project_id']?'<a href="/projects/'.(int)$r['project_id'].'"><strong>#'.(int)$r['project_id'].' · '.View::e($r['project_code']).'</strong><br>'.View::e($r['project_name']).'<br><small>'.View::e($r['project_status']).'</small></a>':'<span class="muted">Без проект</span>';$html.='<tr><td>'.(int)$r['id'].'</td><td><strong>'.View::e($r['directorate_code']).'</strong><br><small>'.View::e($r['directorate']).'</small></td><td>'.$project.'</td><td>'.View::e($this->riskCategoryLabel((string)$r['category'])).'</td><td>'.View::e($r['description']).'</td><td>'.(int)$r['probability'].'×'.(int)$r['impact'].' = '.(int)$r['inherent_score'].'</td><td>'.(int)($r['residual_probability']??$r['probability']).'×'.(int)($r['residual_impact']??$r['impact']).' = '.(int)($r['residual_score']??$r['inherent_score']).'</td><td>'.(int)$r['completed_measure_count'].'/'.(int)$r['measure_count'].' завршени</td><td>'.$this->badge((string)$r['status']).'</td>'.($editable?'<td><a class="button button-secondary" href="/risks/'.(int)$r['id'].'/edit">Отвори и управувај</a></td>':'').'</tr>';}return$html.'</tbody></table></div>'; }
    private function riskMeasuresTable(array$rows,int$riskId): string {if(!$rows)return'<p class="muted">Нема евидентирани мерки.</p>';$types=['prevent'=>'Превентивна','reduce'=>'Намалувачка','transfer'=>'Пренесувачка','avoid'=>'Избегнувачка','contingency'=>'Резервна'];$html='<div class="table-wrap"><table><thead><tr><th>Вид</th><th>Мерка</th><th>Одговорно лице</th><th>Рок</th><th>Статус</th><th>Планирано намалување</th><th>Ефект врз ризикот</th><th>Доказ</th><th>Дејство</th></tr></thead><tbody>';foreach($rows as$row){$effect=$row['status']==='completed'?'−'.(int)$row['probability_reduction'].' веројатност · −'.(int)$row['impact_reduction'].' ndikim':'Не се применува до завршувањето';$html.='<tr><td>'.View::e($types[$row['measure_type']]??$row['measure_type']).'</td><td>'.View::e($row['action']).'</td><td>'.View::e($row['owner']).'</td><td>'.View::e($row['due_at']).'</td><td>'.View::e($row['status']).'</td><td>−'.(int)$row['probability_reduction'].' / −'.(int)$row['impact_reduction'].'</td><td>'.View::e($effect).'</td><td>'.View::e($row['evidence']).'</td><td><a class="button button-secondary" href="/risks/'.$riskId.'/measures/'.(int)$row['id'].'/edit">Уреди</a></td></tr>';}return$html.'</tbody></table></div>';}
