    private function riskCategoryOptions(?string$current=null): string {$categories=$this->riskCategories();if($current!==null&&!isset($categories[$current]))$categories=[$current=>'Постојна категорија — '.$current]+$categories;$html='<option value="">Изберете категорија и објаснување</option>';foreach($categories as$value=>$label)$html.='<option value="'.View::e($value).'"'.($current===$value?' selected':'').'>'.View::e($label).'</option>';return$html;}
