        $labels = [
            'required'=>'Полето е задолжително', 'missing_header'=>'Колоната недостасува во датотеката',
            'duplicate_in_file'=>'Вредноста се повторува во датотеката', 'unknown_code'=>'Шифрата на секторот не постои',
            'unknown_directorate'=>'Секторот не се совпаѓа со регистарот', 'out_of_scope'=>'Надвор од вашиот опсег',
            'financial_scope_required'=>'Потребна е финансиска улога за секторот', 'invalid_amount'=>'Износот не е валиден',
            'exceeds_budget'=>'Остатокот го надминува буџетот', 'funding_sources_do_not_reconcile'=>'Изворите не се изедначуваат со вкупниот буџет',
            'unknown_category'=>'Категоријата не е препознаена', 'invalid_section'=>'Шифрата на делот не е валидна', 'invalid_id'=>'ID на увозот не е валиден', 'too_long'=>'Вредноста е предолга', 'invalid_date'=>'Датумот не е валиден',
            'already_posted'=>'Референцата е веќе објавена', 'unknown_commitment'=>'Обврската не е пронајдена',
            'commitment_not_active'=>'Обврската не е активна', 'does_not_match_commitment'=>'Вредноста не се совпаѓа со обврската',
            'exceeds_commitment_balance'=>'Износот го надминува салдото на обврската', 'invalid_date_range'=>'Датумите не се во валиден редослед',
            'budget_code_missing'=>'Буџетската шифра недостасува', 'budget_code_unknown'=>'Шифрата не постои во тековниот буџет', 'budget_code_mismatch'=>'Шифрата во описот не се совпаѓа со блокот на шифрирање',
            'budget_code_ambiguous'=>'Шифрата се совпаѓа со повеќе од една ставка', 'existing_conflict'=>'Редот се разликува од постојниот увоз',
            'missing_control_totals'=>'Контролните збирови недостасуваат', 'control_totals_mismatch'=>'Збировите на датотеката не се совпаѓаат со трансакциите',
            'subtotal_mismatch'=>'Меѓузбирот не се изедначува со збирот на ставките', 'formula_mismatch'=>'D=A-(B+C) или F=D-E не се совпаѓа', 'hierarchy_gap'=>'Недостасува матично ниво во хиерархијата',
            'unexpected_indent'=>'Празните места на почетокот на Описот мора да бидат 4 CAT, 6 RESP, 8 PCLASS, 10 MOBJ, 12 PROJ или 14 CLAS', 'missing_fiscal_year'=>'Фискалната година не е пронајдена', 'subtotal_without_lines'=>'Меѓузбир без ставки',
            'program_unmapped'=>'Програмата не е поврзана со сектор', 'below_allocations'=>'Новиот збир е помал од постојните распределби', 'directorate_change_with_allocations'=>'Ставка со распределби не може да премине во друг сектор',
            'code_conflict'=>'Новата шифра се судира со друга ставка на секторот', 'grant_split_needs_review'=>'Постојната распределба на дотациите за образование/здравство ја надминува новата дотација', 'missing_sheet'=>'Листот недостасува', 'missing_section'=>'Делот недостасува',
            'missing_section_total'=>'Редот ВКУПНО на делот недостасува', 'line_without_program'=>'Редот нема програма', 'missing_project_code'=>'Шифрата на проектот недостасува', 'fiscal_year_mismatch'=>'Годината на работната книга се разликува од избраната година',
            'as_of_outside_fiscal_year'=>'Датумот на извештајот не е во фискалната година', 'older_than_current'=>'Постои понов извештај за оваа година', 'empty_file'=>'Датотеката е празна',
        ];
        $html = '<div class="table-wrap"><table><thead><tr><th>External row key</th><th>Статус</th><th>Клучни податоци</th><th>Грешки</th></tr></thead><tbody>';
        foreach ($rows as $row) {
            $payload = json_decode((string) $row['payload'], true) ?: [];
            $errors = json_decode((string) ($row['errors'] ?? '[]'), true) ?: [];
            $details = [];
            foreach (['action','previous_code','matched_by','source_row_number','fund_code','program_code','economic_code','project_code','project_name','function_code','allocated','actual','obligations','commitments','balance','directorate','directorate_code','code','budget_line_code','extracted_budget_code','journal_voucher_number','source_document_number','beneficiary','description','commitment_reference','source_reference','category','section','government_grant','education_grant','health_grant','loan_financing','own_revenue','total_budgeted','carryover_revenue','remaining','total_available','debit_amount','credit_amount','amount','accounting_date'] as $key) {
                if (($payload[$key] ?? '') !== '') $details[] = str_replace('_', ' ', $key).': '.$payload[$key];
            }
            $messages = [];
            foreach ($errors as $error) $messages[] = ($error['column'] ?? '*').': '.($labels[$error['code'] ?? ''] ?? ($error['code'] ?? 'Грешка'));
            $html .= '<tr><td>'.View::e($row['external_row_key']).'</td><td><span class="status-badge status-'.View::e($row['status']).'">'.View::e($row['status']).'</span></td><td>'.View::e(implode(' · ', $details)).'</td><td>'.View::e(implode(' | ', $messages)).'</td></tr>';
        }
        return $html.'</tbody></table></div>';
    }
    private function badge(string $status): string
    {
        $labels=['draft'=>'Нацрт','active'=>'Активно','on_hold'=>'На чекање','completed'=>'Завршена','cancelled'=>'Откажано','not_started'=>'Не е започната','in_progress'=>'Во реализација','blocked'=>'Блокирано','done'=>'Завршена','open'=>'Отворен','monitoring'=>'Во следење','mitigated'=>'Ублажено','closed'=>'Затворен'];
        return '<span class="status-badge status-'.View::e(preg_replace('/[^a-z_]/','',$status)).'">'.View::e($labels[$status]??$status).'</span>';
    }

    /**
     * Generic table. $paging: true pages the rows in PHP under an automatic key, false shows them all (records, live feeds),
     * a string is the key of rows already paged in SQL, whose navigation is added.
     */
    private function simpleTable(array $rows,string|bool $paging=true): string { if($paging===true){$paging='t'.(++$this->autoPager);$rows=$this->pageOf($rows,$paging);}$nav=is_string($paging)?$this->pager($paging):''; if(!$rows)return '<p class="muted">Нема податоци.</p>'.$nav; '<p class="muted">Нема податоци.</p>'; $keys=array_keys($rows[0]); $html='<div class="table-wrap"><table><thead><tr>'; $labels=$this->localizedHeaders($keys,'mk');foreach($keys as $k)$html.='<th>'.View::e($labels[$k]??$k).'</th>'; $html.='</tr></thead><tbody>'; foreach($rows as $r){$html.='<tr>';foreach($keys as $k)$html.='<td>'.View::e($r[$k]).'</td>';$html.='</tr>';}return $html.'</tbody></table></div>'.$nav; }
}
